INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C1','kor',6,2,'u5',1,'음성 언어와 문자 언어 — 음성 언어는 음성으로 나타내는 말로 듣는 사람 앞에서 바로 전해지고, 문자 언어는 글자로 나타내는 말로 적어 두면 다시 볼 수 있으며, 두 언어는 등수를 매기는 사이가 아니라 알맞은 곳이 서로 다를 뿐이다',ARRAY['6국04 문법(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C2','kor',6,2,'u5',1,'특성은 규칙이 아니라 기본 성질 — 말은 보통 그 자리에서 사라지고 글은 보통 오래 남지만 매체에 따라 달라져(녹음한 말은 남고, 빠르게 지나가는 대화 글·잠깐 뜨는 알림·넘기면 없어지는 자막은 흘러감) 「언제나」로 외우지 않고 이 매체에서는 어떻게 되는지를 그때그때 살핀다',ARRAY['6국04 문법(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C3','kor',6,2,'u5',1,'매체 자료의 세 갈래 — 인쇄 매체는 문자 언어를 바탕으로 표·그림·사진을, 음성 매체는 음성 언어를 바탕으로 소리·음악을, 영상 매체는 음성 언어·문자 언어·그림·소리·움직임을 어울러 쓰며, 더 나은 매체는 없고 전하려는 내용과 받는 사람에 따라 알맞은 매체가 달라진다',ARRAY['6국06 매체(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C4','kor',6,2,'u5',2,'문자 언어의 표현 특성 — 적은 내용이 그대로 남아 필요할 때 다시 볼 수 있고, 여러 사람이 똑같은 내용을 정확하게 나누어 가지며, 글자의 크기·굵기·문장 부호·줄 나눔으로 중요한 곳을 눈에 보이게 하고, 천천히 생각하며 읽고 쓴 뒤에 고칠 수 있다',ARRAY['6국04 문법(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C5','kor',6,2,'u5',2,'음성 언어의 표현 특성 — 그 자리에서 바로 전해지고 말이 끝나면 소리가 사라지며, 목소리의 크기·억양·속도·잠깐 쉬기로 감정과 의도를 함께 전하고, 듣는 사람의 반응을 보며 말을 바꾸거나 다시 설명하고, 모르는 곳을 그 자리에서 되물을 수 있다',ARRAY['6국04 문법(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C6','kor',6,2,'u5',2,'그 자리에 알맞은 방법 고르기 — 어느 쪽이 더 나은지가 아니라 전하려는 내용과 받는 사람의 처지를 함께 보아, 차례가 여럿이거나 다시 봐야 하면 글, 마음을 생생하게 전하거나 바로 주고받아야 하면 말, 어렵거나 헷갈리면 둘을 함께 쓰며, 고른 까닭을 언어의 특성과 이어 말하는 데까지가 답이다',ARRAY['6국04 문법(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C7','kor',6,2,'u5',2,'두 언어를 함께 써 서로 보완하기 — 말로 설명하면 생생하지만 놓치면 되돌릴 수 없고 같은 내용을 글로도 보여 주면 놓친 곳을 다시 확인할 수 있어, 어렵거나 헷갈리는 내용일수록 말과 글을 함께 쓴다',ARRAY['6국04 문법(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C8','kor',6,2,'u5',4,'영상 매체를 이루는 요소 — 해설하는 말(흐름을 이어 줌)·자막(꼭 남겨야 할 내용을 다시 보여 줌)·장면과 움직임(어떤 일이 벌어지는지 한눈에)·소리와 음악(어디를 눈여겨볼지 알림)이 함께 내용을 전하며, 올린 날짜·만든 사람 이름·본 사람 수·화면 크기는 뜻을 나르는 요소가 아니다',ARRAY['6국06 매체(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C9','kor',6,2,'u5',4,'말과 자막의 보완 · 강조 방법 — 해설하는 말은 흐름을 이어 주지만 놓치면 되돌릴 수 없어, 어렵거나 헷갈리는 내용은 자막으로 정리해 눈으로 다시 확인하게 하고, 자막은 색·크기·모양으로, 말은 음악과 효과음으로 중요한 곳을 강조한다',ARRAY['6국06 매체(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C10','kor',6,2,'u5',4,'표현 효과는 무엇을 돕는가로 본다 — 자막을 화면 가득 채우거나 음악을 계속 크게 깔거나 장면을 쉴 새 없이 바꾸면 무엇이 중요한지 흐려지고, 꼭 남길 곳에만 자막을 두고 중요한 곳에서 소리를 바꾸면 또렷해지므로, 표현 효과는 요소의 개수가 아니라 그 요소가 무엇을 돕는가로 본다',ARRAY['6국06 매체(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C11','kor',6,2,'u5',5,'장면마다 방법이 다른 까닭 — 같은 영상 안에서도 그 장면에서 해야 할 일이 달라 쓰는 방법이 다르다: 무엇을 다룰지 알릴 때 자막으로 제목, 처음 듣는 낱말을 정확히 남길 때 말과 자막을 함께, 느낌을 바꿀 때 음악의 빠르기를 바꾼다',ARRAY['6국06 매체(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C12','kor',6,2,'u5',5,'영상 감상의 세 걸음 — 찾기(이 장면에 말·글·그림·소리 가운데 무엇이 쓰였는가)·잇기(그것이 이해를 무엇으로 돕는가)·말하기(나는 어떻게 느꼈고 까닭은 무엇인가)이며, 어느 장면이 인상 깊었는가 같은 느낌은 사람마다 다를 수 있지만 무엇이 쓰였고 무엇을 돕는가는 영상 안에서 함께 확인할 수 있으므로, 감상은 좋았다·별로였다에서 멈추지 않고 어떤 표현 때문인지 까닭을 함께 말한다',ARRAY['6국06 매체(초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C13','kor',6,2,'u5',5,'영상의 내용 파악하기 — 장면 차례로 무엇을 다루는지 짐작하고 낯선 낱말(밀물·썰물·퇴적·갯벌)을 먼저 익혀, 강물과 바닷물이 실어 온 고운 흙과 모래가 물살이 느린 얕은 바닥에 오랫동안 쌓여 갯벌이 만들어지고 그곳에 게·조개·갯지렁이가 산다는 내용을 정확히 확인하며 본다',ARRAY['6국06 매체(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C14','kor',6,2,'u5',7,'독자를 고려한다는 것 — 글을 읽는 사람(독자)의 처지에서 헤아려 보는 것으로, 독자의 흥미·배경지식·수준(알아들을 수 있는 낱말과 표현)·글을 읽는 매체를 살피고, 독자가 겪는 어려움과 독자가 할 수 있는 일까지 보이게 쓴다 — 같은 내용이라도 누가 읽느냐에 따라 낱말도 차례도 달라진다',ARRAY['6국03 쓰기(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C15','kor',6,2,'u5',7,'독자 고려는 비위 맞추기가 아니다 — 독자가 좋아할 내용만 고르거나 어려운 이야기를 빼 버리거나 낱말만 쉽게 바꾸면 끝나는 것이 아니라, 전하려는 것은 그대로 두고 독자가 알아들을 수 있게 짜는 것이며, 말하고 싶은 것을 줄이는 일이 아니라 그것이 독자에게 닿게 하는 일이다',ARRAY['6국03 쓰기(초안)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C16','kor',6,2,'u5',7,'글 쓰는 세 단계와 고쳐 쓰기 — 계획 세우기(누가 읽을지·무엇을 왜 쓸지)·내용 생성하고 조직하기(쓸 거리를 모아 차례 짜기)·글 쓰고 고쳐 쓰기를 거치며 단계마다 독자를 다시 떠올리고, 고쳐 쓸 때에는 독자의 수준에 맞는가·주제가 드러나는가·낱말과 문장에 잘못이 없는가·오해할 만한 표현이 없는가를 본다 — 고쳐 쓰기는 틀린 곳을 벌하는 일이 아니라 독자에게 더 잘 닿게 하는 일',ARRAY['6국03 쓰기(초안)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C17','kor',6,2,'u5',7,'글에 자료를 넣는 까닭 — 글만으로 잘 전해지지 않을 때 수를 견줄 때는 표나 그래프, 모습이나 차례는 사진이나 그림, 할 일은 기호와 줄 나눔을 함께 놓으며, 자료는 개수를 채우려고가 아니라 독자의 이해를 도우려고 넣고 글에서 말한 내용과 이어지는 것만 고른다',ARRAY['6국03 쓰기(초안)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C18','kor',6,2,'u5',9,'기사문의 특성 — 어떤 사실이나 사건을 여러 사람에게 알리는 글로, 직접 보고 듣고 조사한 내용을, 느낌이 아니라 사실로, 빠르고 정확하게, 객관적이고 간결한 표현으로 쓰며, 읽는 사람이 사실이라고 믿고 읽기 때문에 지어낼 수 없다',ARRAY['6국03 쓰기(초안)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C19','kor',6,2,'u5',9,'기사문의 짜임과 육하원칙 — 제목(표제는 내용을 간결하게 드러내고 부제는 필요할 때 표제를 보충)·전문(주요 내용을 누가·언제·어디에서·무엇을·어떻게·왜의 육하원칙으로 앞에서 요약)·본문(주된 내용을 자세히)으로 이루어진다',ARRAY['6국03 쓰기(초안)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C20','kor',6,2,'u5',9,'확인한 사실과 생각 가르기 — 직접 세어 본 수·직접 들은 말·눈으로 확인한 일·본인에게 물어 확인한 계획은 쓰고, 확인하지 못한 소문·그럴 것 같아 지어낸 숫자는 쓰지 않으며, 「모두 기뻐했다」처럼 쓴 사람의 생각을 사실처럼 쓰지 않고 생각을 쓰려면 누구의 생각인지 밝힌다',ARRAY['6국03 쓰기(초안)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C21','kor',6,2,'u5',9,'기사문 계획 · 자료 출처 · 제목 — 독자의 특성·기삿거리(독자가 관심 있고 내가 가서 확인할 수 있는 일)·필요한 자료·자료 수집 방법을 정한 뒤 개요를 짜고, 사진·표 같은 자료는 출처(내가 조사했으면 언제·누구에게·어떻게)를 밝히며, 제목은 내용을 담고 읽고 싶어지게 쓰되 본문에 없는 말로 부풀리지 않는다',ARRAY['6국03 쓰기(초안)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C22','kor',6,2,'u5',12,'편지의 짜임과 독자 — 받는 사람·첫인사(안부)·하고 싶은 말(쓴 목적)·끝인사·쓴 날짜와 보내는 사람의 다섯 부분으로 이루어지며, 독자가 받는 사람 한 사람이라 알맞은 높임말을 쓰고 목적이 뚜렷이 드러나게 하고 받는 사람이 모를 만한 일은 앞뒤를 설명해 준다',ARRAY['6국03 쓰기(초안)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C23','kor',6,2,'u5',12,'전하려는 마음에 맞는 내용 — 고마울 때는 무엇이 고마웠는지 그 일을 콕 집어, 미안할 때는 변명보다 무엇이 잘못이었는지를 먼저, 축하할 때는 그 사람이 애쓴 과정을 함께, 힘을 내라고 할 때는 섣부른 충고보다 곁에 있다는 말을 쓴다',ARRAY['6국03 쓰기(초안)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C24','kor',6,2,'u5',12,'편지의 매체 고르기와 건네기 — 손 편지(글씨와 종이가 남아 오래 간직)·영상 편지(목소리와 표정이 생생)·누리집이나 게시판 글(여러 사람이 함께 봄) 가운데 전하려는 마음과 받는 사람의 처지에 맞는 것을 고르며(매체에 등수 없음), 정말 전하고 싶은 사람에게 쓰고 실제로 건네 반응을 보아야 편지가 완성된다',ARRAY['6국03 쓰기(초안)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C25','kor',6,2,'u5',12,'겹받침이 있는 낱말의 발음 — 받침에 자음자가 두 개 있는 겹받침은 받침에서 한 번에 한 소리만 낼 수 있어 뒤에 자음자가 오거나 낱말이 끝나면 하나만 소리 나고(붉다[북따]·얇다[얄따]·짧다[짤따]), 뒤에 모음이 오면 두 소리가 다 나며 뒤엣것이 뒷글자로 넘어간다(붉어요[불거요]·얇아요[얄바요]) (기초 다지기)',ARRAY['6국04 문법(초안)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X01','kor',6,'u5',ARRAY['K6-2-u5-C1']::text[],'음성 언어와 문자 언어의 뜻을 서로 바꾸어 알거나, 글로 옮겨 적은 말을 음성 언어로 여긴다','음성으로? 글자로?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X02','kor',6,'u5',ARRAY['K6-2-u5-C2','K6-2-u5-C4','K6-2-u5-C5']::text[],'「말은 언제나 사라진다 · 글은 언제나 남는다」처럼 특성을 어떤 경우에도 맞는 규칙으로 외워, 녹음한 말이나 흘러가는 글을 설명하지 못한다','보통은 그렇지만 매체에 따라 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X03','kor',6,'u5',ARRAY['K6-2-u5-C1','K6-2-u5-C3','K6-2-u5-C24']::text[],'글이 말보다, 영상이 글보다 낫다처럼 언어나 매체에 등수를 매긴다','더 나은 쪽이 아니라 그 자리에 알맞은 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X04','kor',6,'u5',ARRAY['K6-2-u5-C3']::text[],'인쇄 · 음성 · 영상 매체가 주로 쓰는 방법을 헷갈린다','무엇을 바탕으로 무엇을 더하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X05','kor',6,'u5',ARRAY['K6-2-u5-C3','K6-2-u5-C8']::text[],'올린 날짜 · 만든 사람 이름 · 본 사람 수 · 화면 크기처럼 뜻을 나르지 않는 것을 매체 자료의 표현 방법으로 고른다','화면이나 지면에서 뜻을 나르는 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X06','kor',6,'u5',ARRAY['K6-2-u5-C4','K6-2-u5-C5']::text[],'글의 강조 방법(굵은 글씨 · 밑줄 · 문장 부호)과 말의 강조 방법(목소리 크기 · 억양 · 속도)을 뒤섞는다','글은 눈에, 말은 귀에 띄게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X07','kor',6,'u5',ARRAY['K6-2-u5-C4']::text[],'문자 언어의 장점(다시 보기 · 똑같이 나누어 갖기 · 천천히 읽고 고치기)을 모르거나 글은 쓰고 나면 고칠 수 없다고 여긴다','적어 두면 무엇이 좋을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X08','kor',6,'u5',ARRAY['K6-2-u5-C5']::text[],'음성 언어의 장점(목소리로 감정 전하기 · 반응 보고 바꾸기 · 그 자리에서 되묻기)을 모른다','마주 보고 말하면 무엇을 할 수 있을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X09','kor',6,'u5',ARRAY['K6-2-u5-C6']::text[],'알맞은 방법을 고르기만 하고 까닭을 말하지 않거나, 까닭을 언어의 특성과 잇지 못한다','고른 것 + 그 특성 때문에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X10','kor',6,'u5',ARRAY['K6-2-u5-C6','K6-2-u5-C24']::text[],'전하려는 내용과 받는 사람의 처지를 보지 않고 늘 한 가지 방법만 쓰거나 빠르고 편한 방법만 고른다','무엇을 · 누구에게?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X11','kor',6,'u5',ARRAY['K6-2-u5-C7','K6-2-u5-C9']::text[],'말한 내용을 글(자막)로도 보여 주면 겹쳐서 쓸모없다고 여겨, 두 언어가 서로 보완하는 것을 모른다','놓친 곳을 다시 확인하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X12','kor',6,'u5',ARRAY['K6-2-u5-C8','K6-2-u5-C9','K6-2-u5-C11']::text[],'해설하는 말 · 자막 · 장면 · 소리와 음악이 각각 하는 일을 헷갈린다','흐름 · 붙들기 · 한눈에 · 눈여겨볼 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X13','kor',6,'u5',ARRAY['K6-2-u5-C10','K6-2-u5-C17']::text[],'자막 · 음악 · 장면 · 자료를 많이 넣을수록 잘 전달되고 좋은 자료라고 여긴다','개수가 아니라 무엇을 돕는가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X14','kor',6,'u5',ARRAY['K6-2-u5-C11']::text[],'장면마다 방법을 아무렇게나 골랐다고 여겨, 그 장면에서 해야 할 일과 방법을 잇지 못한다','이 장면에서 시청자가 알아야 할 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X15','kor',6,'u5',ARRAY['K6-2-u5-C12']::text[],'감상을 「좋았다 · 재미있었다 · 별로였다」에서 멈추고 어떤 표현 때문인지 까닭을 말하지 않는다','찾기 · 잇기 · 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X16','kor',6,'u5',ARRAY['K6-2-u5-C12']::text[],'느낌이 나와 다르면 잘못 본 것이라 여기거나, 사람마다 다를 수 있는 느낌과 영상 안에서 확인할 수 있는 것을 가르지 못한다','갈릴 수 있는 것 · 함께 확인할 수 있는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X17','kor',6,'u5',ARRAY['K6-2-u5-C13']::text[],'영상의 장면 차례를 이어 보지 않아 갯벌이 만들어지는 과정을 잘못 안다(솟아올라서 · 얼었다 녹아서 등)','무엇이 어디에 오래 쌓이나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X18','kor',6,'u5',ARRAY['K6-2-u5-C13']::text[],'영상에 나온 낱말(밀물 · 썰물 · 퇴적 · 갯벌)의 뜻을 서로 헷갈린다','들어오는 물 · 나가는 물 · 쌓이는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X19','kor',6,'u5',ARRAY['K6-2-u5-C14']::text[],'독자 고려를 낱말만 쉽게 바꾸는 일로 좁히거나, 독자의 흥미 · 배경지식 · 수준 · 매체 가운데 일부만 살핀다','흥미 · 배경지식 · 수준 · 매체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X20','kor',6,'u5',ARRAY['K6-2-u5-C15']::text[],'독자 고려를 독자가 좋아할 내용만 고르거나 어려운 이야기를 빼 버리는 비위 맞추기로 여긴다','전하려는 것은 그대로, 닿는 방법을 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X21','kor',6,'u5',ARRAY['K6-2-u5-C16']::text[],'글 쓰는 세 단계와 그 단계에서 하는 일을 헷갈리거나, 독자는 처음 계획할 때만 떠올리면 된다고 여긴다','쓰기 전 · 쓰는 중 · 쓴 뒤, 단계마다 독자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X22','kor',6,'u5',ARRAY['K6-2-u5-C16']::text[],'고쳐 쓸 곳을 글씨 · 길이 · 꾸밈 같은 겉모습에서 찾거나, 고쳐 쓰기를 틀린 곳을 벌하는 일로 여긴다','독자에게 더 잘 닿게 하려고 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X23','kor',6,'u5',ARRAY['K6-2-u5-C17']::text[],'자료를 개수를 채우려고 넣거나, 글과 이어지지 않는 자료를 넣거나, 자료를 넣으면 글을 덜 써도 된다고 여긴다','글만으로 어려운 곳을 돕는 자료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X24','kor',6,'u5',ARRAY['K6-2-u5-C14','K6-2-u5-C16']::text[],'어렵고 딱딱한 낱말을 많이 쓰면 글이 훌륭해 보인다고 여겨, 독자가 알아듣지 못하는 문제를 보지 않는다','독자가 아는 말인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X25','kor',6,'u5',ARRAY['K6-2-u5-C14','K6-2-u5-C15']::text[],'글에서 독자가 무엇을 하면 되는지, 왜 그래야 하는지가 빠져도 괜찮다고 여긴다','까닭과 할 일이 함께 보이게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X26','kor',6,'u5',ARRAY['K6-2-u5-C18','K6-2-u5-C20']::text[],'기사문에 쓴 사람의 느낌이나 생각을 사실처럼 쓴다(「모두 기뻐했다」 · 「가장 큰 변화」)','누구든 다시 확인할 수 있는가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X27','kor',6,'u5',ARRAY['K6-2-u5-C18','K6-2-u5-C20']::text[],'확인하지 못한 소문이나 그럴 것 같아 지어낸 숫자를 기사문에 쓴다','세어 보거나 물어본 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X28','kor',6,'u5',ARRAY['K6-2-u5-C19']::text[],'기사문의 짜임(표제 · 부제 · 전문 · 본문)과 하는 일을 헷갈리거나, 전문을 느낌이나 못다 한 말을 쓰는 곳으로 여긴다','전문 = 주요 내용 요약') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X29','kor',6,'u5',ARRAY['K6-2-u5-C19']::text[],'육하원칙(누가 · 언제 · 어디에서 · 무엇을 · 어떻게 · 왜)의 항목을 서로 헷갈리거나 빠뜨린다','여섯 가지 물음에 하나씩 답하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X30','kor',6,'u5',ARRAY['K6-2-u5-C21']::text[],'기삿거리를 독자의 관심이나 직접 확인할 수 있는지를 보지 않고 고른다','독자가 관심 있고, 내가 가서 확인할 수 있는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X31','kor',6,'u5',ARRAY['K6-2-u5-C21']::text[],'기사문 제목을 본문에 없는 말로 부풀리거나, 반대로 아무 내용도 담지 않은 제목을 쓴다','내용을 담되 부풀리지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X32','kor',6,'u5',ARRAY['K6-2-u5-C21','K6-2-u5-C17']::text[],'사진 · 표 같은 자료를 넣으면서 어디에서 얻었는지, 언제 누구에게 어떻게 조사했는지 출처를 밝히지 않는다','출처를 밝혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X33','kor',6,'u5',ARRAY['K6-2-u5-C22']::text[],'편지의 다섯 부분(받는 사람 · 첫인사 · 하고 싶은 말 · 끝인사 · 쓴 날짜와 보내는 사람)을 빠뜨리거나 하는 일을 헷갈린다','누구에게 · 인사 · 목적 · 인사 · 언제 누가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X34','kor',6,'u5',ARRAY['K6-2-u5-C22']::text[],'편지를 받는 사람에게 알맞은 높임말을 쓰지 않거나, 받는 사람이 모를 만한 일을 앞뒤 설명 없이 쓴다','받는 사람 한 사람을 떠올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X35','kor',6,'u5',ARRAY['K6-2-u5-C23']::text[],'전하려는 마음과 맞지 않는 내용을 쓴다(축하에 충고, 사과에 변명 먼저, 위로에 섣부른 충고)','이 마음에 맞는 말은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X36','kor',6,'u5',ARRAY['K6-2-u5-C23']::text[],'「고마워」 · 「잘했네」처럼 무엇이 그런지 없이 막연하게 써서 마음이 잘 닿지 않는다','그 일을 콕 집어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X37','kor',6,'u5',ARRAY['K6-2-u5-C24']::text[],'편지를 숙제로 아무에게나 쓰거나 꾸미기에 시간을 다 쓰고, 건네고 반응을 보는 것을 하지 않는다','건네고 나서 완성돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X38','kor',6,'u5',ARRAY['K6-2-u5-C25']::text[],'겹받침 뒤에 자음자가 오거나 낱말이 끝날 때에도 두 소리를 다 내거나, 뒤에 모음이 와도 하나만 소리 낸다','뒤에 오는 것이 자음자? 모음?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X39','kor',6,'u5',ARRAY['K6-2-u5-C25']::text[],'겹받침 낱말에서 어느 자음자가 소리 나는지, 뒤엣것이 어느 글자로 넘어가는지를 헷갈린다','소리 내어 천천히 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X40','kor',6,'u5',ARRAY['K6-2-u5-C16','K6-2-u5-C24']::text[],'「앞으로 열심히 하겠다」처럼 언제 · 어디에서 · 무엇을 할지 없는 다짐을 실천 계획으로 여긴다','언제 · 어디에서 · 무엇을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#1','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',1,'mc','auto','「음성 언어」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X04']::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"mc","stem":"「음성 언어」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"음성으로 나타내는 말","correct":true},{"t":"글자로 나타내는 말","mis":"K6-2-u5-X01"},{"t":"그림과 사진으로 나타내는 것","mis":"K6-2-u5-X04"},{"t":"어느 고장에서만 쓰는 말","mis":"K6-2-u5-X01"}],"explanation":["글자로 나타내는 말은 문자 언어예요.","그림과 사진은 언어가 아니라 함께 쓰는 자료예요.","음성으로 나타내는 말이 음성 언어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#2','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',1,'sa','auto','글자로 나타내는 말을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C1","difficulty":1,"kind":"sa","stem":"글자로 나타내는 말을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["문자언어","문자 언어"],"explanation":["음성으로 나타내는 말은 음성 언어예요.","글자로 나타내는 말은 문자 언어예요.","적어 두면 다시 볼 수 있어요."],"mis":"K6-2-u5-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#3','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',1,'ox','auto','음성 언어와 문자 언어 가운데 문자 언어가 더 좋은 언어예요.',ARRAY['K6-2-u5-X03']::text[],false,'{"seq":3,"concept":"K6-2-u5-C1","difficulty":1,"kind":"ox","stem":"음성 언어와 문자 언어 가운데 문자 언어가 더 좋은 언어예요.","answer":"X","reason_options":[{"t":"두 언어는 알맞은 곳이 서로 다를 뿐이기 때문에","correct":true},{"t":"글은 남고 말은 사라지기 때문에","mis":"K6-2-u5-X03"}],"mis":"K6-2-u5-X03","explanation":["두 언어는 등수를 매기는 사이가 아니에요.","상황마다 알맞은 쪽이 달라요.","그래서 더 좋은 언어는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#4','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C3',1,'mc','auto','음성 언어를 바탕으로 소리와 음악을 함께 쓰는 매체는 어느 것인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":4,"concept":"K6-2-u5-C3","difficulty":1,"kind":"mc","stem":"음성 언어를 바탕으로 소리와 음악을 함께 쓰는 매체는 어느 것인가요?","options":[{"t":"음성 매체","correct":true},{"t":"인쇄 매체","mis":"K6-2-u5-X04"},{"t":"영상 매체","mis":"K6-2-u5-X04"},{"t":"문자 매체","mis":"K6-2-u5-X04"}],"explanation":["인쇄 매체는 문자 언어를 바탕으로 해요.","영상 매체는 여러 방법이 어우러져요.","소리로 전하는 라디오 같은 것이 음성 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#5','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',2,'mc','auto','시율이와 도아가 준비물을 다시 확인할 수 있었던 까닭은 무엇인가요?',ARRAY['K6-2-u5-X08','K6-2-u5-X09','K6-2-u5-X02']::text[],false,'{"seq":5,"concept":"K6-2-u5-C1","difficulty":2,"kind":"mc","stem":"시율이와 도아가 준비물을 다시 확인할 수 있었던 까닭은 무엇인가요?","options":[{"t":"같은 내용이 글로도 남아 있었기 때문에","correct":true},{"t":"선생님의 목소리가 아주 컸기 때문에","mis":"K6-2-u5-X08"},{"t":"두 사람의 기억력이 좋았기 때문에","mis":"K6-2-u5-X09"},{"t":"말은 언제나 남기 때문에","mis":"K6-2-u5-X02"}],"explanation":["두 사람은 앞부분만 기억났어요.","알림 게시글을 다시 읽어 보기로 했어요.","글로 남은 내용은 다시 볼 수 있어요."],"asset":{"type":"speech","turns":[{"who":"시율","text":"도아야, 아까 선생님이 준비물 말씀하셨잖아. 뭐였지?"},{"who":"도아","text":"나도 앞부분만 기억나. 잠깐, 알림 게시글에도 올라와 있어."},{"who":"시율","text":"아, 글로도 올려 주셨구나. 그럼 다시 읽어 보면 되겠다."},{"who":"도아","text":"응. 말씀은 지나갔지만 글은 그대로 남아 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#6','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C6',2,'match','auto','상황과 알맞은 방법을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u5-C6","difficulty":2,"kind":"match","stem":"상황과 알맞은 방법을 이으세요.","pairs":[{"l":"여러 사람이 오래 기억해야 할 준비물 안내","r":"글로 적어 둡니다"},{"l":"다친 친구에게 지금 걱정하는 마음 전하기","r":"직접 말로 전합니다"},{"l":"실험 차례를 보여 주며 설명하기","r":"말과 글을 함께 씁니다"}],"mis":"K6-2-u5-X10","explanation":["다시 봐야 하는 안내는 글이 알맞아요.","지금 마음을 전할 때는 말이 알맞아요.","차례가 헷갈리는 설명은 둘을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#7','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C2',2,'mc','auto','다음 가운데 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X03']::text[],false,'{"seq":7,"concept":"K6-2-u5-C2","difficulty":2,"kind":"mc","stem":"다음 가운데 알맞게 말한 것은 어느 것인가요?","options":[{"t":"음성 메모로 남기면 말도 다시 들을 수 있다","correct":true},{"t":"말은 어떤 경우에도 다시 확인할 수 없다","mis":"K6-2-u5-X02"},{"t":"글은 어떤 경우에도 사라지지 않는다","mis":"K6-2-u5-X02"},{"t":"남는 쪽이 언제나 더 좋은 방법이다","mis":"K6-2-u5-X03"}],"explanation":["말은 보통 그 자리에서 사라져요.","그래도 녹음하면 남아요.","특성은 규칙이 아니라 기본 성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#8','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C8',2,'mc','auto','매체 자료가 내용을 전달할 때 쓰는 방법이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X05']::text[],false,'{"seq":8,"concept":"K6-2-u5-C8","difficulty":2,"kind":"mc","stem":"매체 자료가 내용을 전달할 때 쓰는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"파일에 붙인 이름","correct":true},{"t":"말하는 사람의 목소리","mis":"K6-2-u5-X05"},{"t":"화면에 뜨는 자막","mis":"K6-2-u5-X05"},{"t":"배경에 깔리는 음악","mis":"K6-2-u5-X05"}],"explanation":["목소리 · 자막 · 음악은 뜻을 나르는 방법이에요.","파일 이름은 화면에서 뜻을 나르지 않아요.","뜻을 나르는 것만 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#9','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C3',2,'ox','auto','영상 매체는 음성 언어와 문자 언어에 그림 · 소리 · 움직임이 어우러진 매체예요.',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":9,"concept":"K6-2-u5-C3","difficulty":2,"kind":"ox","stem":"영상 매체는 음성 언어와 문자 언어에 그림 · 소리 · 움직임이 어우러진 매체예요.","answer":"O","reason_options":[{"t":"여러 방법을 함께 써서 내용을 전하기 때문에","correct":true},{"t":"글자만 써서 내용을 전하기 때문에","mis":"K6-2-u5-X04"}],"mis":"K6-2-u5-X04","explanation":["영상에는 말도 글도 들어 있어요.","그림과 소리, 움직임도 함께 있어요.","그래서 여러 방법이 어우러진 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#10','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C2',3,'error','auto','이 단원의 약속에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X03']::text[],false,'{"seq":10,"concept":"K6-2-u5-C2","difficulty":3,"kind":"error","stem":"이 단원의 약속에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「말은 언제나 없어지고 글은 언제나 남으니까 그대로 외우면 돼.」","correct":true,"mis_target":"K6-2-u5-X02"},{"t":"리안 — 「녹음한 말은 남고, 빠르게 지나가는 대화 글은 흘러가기도 해.」","mis":"K6-2-u5-X02"},{"t":"하진 — 「그 자리에 무엇이 알맞은지를 살펴보면 돼.」","mis":"K6-2-u5-X03"}],"explanation":["리안과 하진은 약속을 바르게 말했어요.","태오는 특성을 규칙으로 외웠어요.","보통은 그렇지만 매체에 따라 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#1','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C14',2,'mc','auto','글을 읽는 사람을 무엇이라고 하나요?',ARRAY['K6-2-u5-X19']::text[],false,'{"seq":1,"concept":"K6-2-u5-C14","difficulty":2,"kind":"mc","stem":"글을 읽는 사람을 무엇이라고 하나요?","options":[{"t":"독자","correct":true},{"t":"작가","mis":"K6-2-u5-X19"},{"t":"기자","mis":"K6-2-u5-X19"},{"t":"화자","mis":"K6-2-u5-X19"}],"explanation":["글을 쓰는 사람은 글쓴이예요.","글을 읽는 사람은 독자예요.","같은 내용도 누가 읽느냐에 따라 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#2','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C3',2,'mc','auto','인쇄 매체가 주로 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X04','K6-2-u5-X05']::text[],false,'{"seq":2,"concept":"K6-2-u5-C3","difficulty":2,"kind":"mc","stem":"인쇄 매체가 주로 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"문자 언어를 바탕으로 표 · 그림 · 사진을 함께 쓴다","correct":true},{"t":"음성 언어를 바탕으로 소리와 음악을 함께 쓴다","mis":"K6-2-u5-X04"},{"t":"말 · 글 · 소리 · 움직임을 모두 어울러 쓴다","mis":"K6-2-u5-X04"},{"t":"파일 이름과 올린 날짜로 내용을 전한다","mis":"K6-2-u5-X05"}],"explanation":["책과 신문은 인쇄 매체예요.","글자를 바탕으로 해요.","표 · 그림 · 사진을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#3','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C2',3,'mc','auto','「글인데 흘러가는 경우」로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X01']::text[],false,'{"seq":3,"concept":"K6-2-u5-C2","difficulty":3,"kind":"mc","stem":"「글인데 흘러가는 경우」로 알맞은 것은 어느 것인가요?","options":[{"t":"잠깐 떴다 사라지는 휴대 전화 알림","correct":true},{"t":"도서관에 꽂힌 책","mis":"K6-2-u5-X02"},{"t":"학급 게시판에 붙은 안내문","mis":"K6-2-u5-X02"},{"t":"녹음해 둔 음성 메모","mis":"K6-2-u5-X01"}],"explanation":["책과 게시판의 글은 오래 남아요.","음성 메모는 말인데 남는 경우예요.","잠깐 뜨고 사라지는 알림은 글인데 흘러가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#4','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C6',3,'mc','auto','내일 소풍 장소와 모일 시각을 반 전체에 알리려고 해요. 어떤 방법이 가장 알맞나요?',ARRAY['K6-2-u5-X10','K6-2-u5-X03']::text[],false,'{"seq":4,"concept":"K6-2-u5-C6","difficulty":3,"kind":"mc","stem":"내일 소풍 장소와 모일 시각을 반 전체에 알리려고 해요. 어떤 방법이 가장 알맞나요?","options":[{"t":"말로 알리고 같은 내용을 글로도 적어 둔다","correct":true},{"t":"말로만 한 번 크게 알린다","mis":"K6-2-u5-X10"},{"t":"가장 빨리 할 수 있는 방법이면 무엇이든 괜찮다","mis":"K6-2-u5-X10"},{"t":"글이 말보다 좋으니 글로만 알린다","mis":"K6-2-u5-X03"}],"explanation":["여러 사람이 오래 기억해야 하는 내용이에요.","말로 알리면 그 자리에서 되물을 수 있어요.","글로도 적어 두면 놓친 사람이 다시 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#5','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C8',3,'ox','auto','영상을 올린 날짜도 그 영상이 내용을 전하는 표현 방법이에요.',ARRAY['K6-2-u5-X05']::text[],false,'{"seq":5,"concept":"K6-2-u5-C8","difficulty":3,"kind":"ox","stem":"영상을 올린 날짜도 그 영상이 내용을 전하는 표현 방법이에요.","answer":"X","reason_options":[{"t":"화면에서 뜻을 나르는 요소가 아니기 때문에","correct":true},{"t":"영상에 관한 것은 모두 표현 방법이기 때문에","mis":"K6-2-u5-X05"}],"mis":"K6-2-u5-X05","explanation":["표현 방법은 화면이나 소리로 뜻을 나르는 것이에요.","올린 날짜는 영상 밖의 정보예요.","목소리 · 자막 · 음악 · 장면을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#6','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C3',3,'match','auto','매체와 그 매체의 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u5-C3","difficulty":3,"kind":"match","stem":"매체와 그 매체의 예를 알맞게 이으세요.","pairs":[{"l":"인쇄 매체","r":"신문과 책"},{"l":"음성 매체","r":"라디오 방송"},{"l":"영상 매체","r":"공익 안내 영상"}],"mis":"K6-2-u5-X04","explanation":["신문과 책은 글자를 바탕으로 해요.","라디오는 소리로 전해요.","영상은 말 · 글 · 그림 · 소리가 어우러져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#7','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C3',3,'error','auto','매체에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X10']::text[],false,'{"seq":7,"concept":"K6-2-u5-C3","difficulty":3,"kind":"error","stem":"매체에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서준 — 「여러 방법을 다 쓰니까 영상 매체가 언제나 제일 좋아.」","correct":true,"mis_target":"K6-2-u5-X03"},{"t":"나윤 — 「전하려는 내용에 따라 알맞은 매체가 달라.」","mis":"K6-2-u5-X03"},{"t":"은재 — 「받는 사람이 누구인지도 함께 봐야 해.」","mis":"K6-2-u5-X10"}],"explanation":["나윤과 은재는 바르게 말했어요.","서준은 매체에 등수를 매겼어요.","셋 가운데 더 나은 매체는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#8','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C1',4,'mc','auto','도아가 「말씀은 지나갔지만 글은 그대로 남아 있으니까.」라고 한 말과 이 단원의 약속을 함께 생각할 때 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X03']::text[],false,'{"seq":8,"concept":"K6-2-u5-C1","difficulty":4,"kind":"mc","stem":"도아가 「말씀은 지나갔지만 글은 그대로 남아 있으니까.」라고 한 말과 이 단원의 약속을 함께 생각할 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이 상황에서는 글이 남아 도움이 되었지만, 녹음한 말처럼 말이 남는 경우도 있으니 매체마다 살펴야 한다","correct":true},{"t":"글은 언제나 남으니 앞으로 모든 안내는 글로만 하면 된다","mis":"K6-2-u5-X02"},{"t":"선생님이 말로 하신 것이 잘못이다","mis":"K6-2-u5-X03"},{"t":"도아의 말은 틀렸다. 글도 금방 사라진다","mis":"K6-2-u5-X02"}],"explanation":["이 상황에서는 글이 남아 다시 볼 수 있었어요.","그렇다고 언제나 그런 것은 아니에요.","매체에 따라 남고 사라지는 것이 달라져요."],"asset":{"type":"speech","turns":[{"who":"시율","text":"도아야, 아까 선생님이 준비물 말씀하셨잖아. 뭐였지?"},{"who":"도아","text":"나도 앞부분만 기억나. 잠깐, 알림 게시글에도 올라와 있어."},{"who":"시율","text":"아, 글로도 올려 주셨구나. 그럼 다시 읽어 보면 되겠다."},{"who":"도아","text":"응. 말씀은 지나갔지만 글은 그대로 남아 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#9','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C2',4,'essay','teacher','「말은 언제나 사라지고 글은 언제나 남는다.」라는 말이 왜 알맞지 않은지 예를 두 가지 들어 쓰고, 어떻게 알아 두어야 하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C2","difficulty":4,"kind":"essay","stem":"「말은 언제나 사라지고 글은 언제나 남는다.」라는 말이 왜 알맞지 않은지 예를 두 가지 들어 쓰고, 어떻게 알아 두어야 하는지 쓰세요.","answer_guide":{"answer":"예: 음성 메모로 녹음한 말은 다시 들을 수 있어서 말인데도 남는다. 잠깐 떴다 사라지는 알림이나 넘기면 없어지는 자막은 글인데도 다시 보기 어렵다. 그래서 말은 보통 그 자리에서 사라지고 글은 보통 오래 남는다는 것은 기본 성질일 뿐이고, 매체에 따라 달라지므로 이 매체에서는 어떻게 되는지 그때그때 살펴야 한다.","scoring_points":["말인데 남는 예를 들었는가","글인데 흘러가는 예를 들었는가","기본 성질이며 매체에 따라 달라진다고 썼는가"]},"explanation":["녹음한 말을 떠올려요.","사라지는 알림을 떠올려요.","규칙이 아니라 기본 성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#10','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C6',4,'essay','teacher','「멀리 이사 간 친구에게 생일 축하하는 마음 전하기」와 「모둠 과제의 차례 다섯 가지 알리기」 가운데 하나를 골라 알맞은 방법(말 · 글 · 둘 다)을 정하고, 그 까닭을 언어의 특성과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C6","difficulty":4,"kind":"essay","stem":"「멀리 이사 간 친구에게 생일 축하하는 마음 전하기」와 「모둠 과제의 차례 다섯 가지 알리기」 가운데 하나를 골라 알맞은 방법(말 · 글 · 둘 다)을 정하고, 그 까닭을 언어의 특성과 이어 쓰세요.","answer_guide":{"answer":"예: 모둠 과제의 차례 다섯 가지를 알릴 때는 글로 적어 두는 것이 알맞다. 차례가 여러 개라 나중에 다시 봐야 하는데, 글은 그대로 남아 필요할 때 다시 볼 수 있고 모둠원이 똑같은 내용을 나누어 가질 수 있기 때문이다. (또는) 생일 축하는 영상 통화로 직접 말로 전하는 것이 알맞다. 목소리의 크기와 억양으로 반가운 마음을 생생하게 전할 수 있기 때문이다.","scoring_points":["상황 하나를 골라 방법을 정했는가","까닭을 썼는가","까닭을 언어의 특성과 이어 썼는가"]},"explanation":["고르는 것까지는 절반이에요.","왜 그런지를 써요.","특성과 이어야 까닭이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#1','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C4',1,'mc','auto','안내 글에서 중요한 내용을 눈에 띄게 한 방법은 어느 것인가요?',ARRAY['K6-2-u5-X06']::text[],false,'{"seq":1,"concept":"K6-2-u5-C4","difficulty":1,"kind":"mc","stem":"안내 글에서 중요한 내용을 눈에 띄게 한 방법은 어느 것인가요?","options":[{"t":"글자를 굵게 하고 줄을 나누었다","correct":true},{"t":"목소리를 크게 했다","mis":"K6-2-u5-X06"},{"t":"배경 음악을 넣었다","mis":"K6-2-u5-X06"},{"t":"말을 천천히 했다","mis":"K6-2-u5-X06"}],"explanation":["목소리 · 음악 · 말의 속도는 말로 할 때 쓰는 방법이에요.","글에서는 글자 굵기와 줄 나눔을 써요.","그래서 목장갑과 겉옷이 눈에 띄어요."],"asset":{"type":"passage","lines":["학급 텃밭 가꾸기 안내","언제 · 다음 주 목요일 다섯째 시간","어디에서 · 학교 뒤편 작은 텃밭 / 무엇을 · 상추 모종 심기","챙길 것 · 손을 덮는 【목장갑】을 꼭 가져오세요.","· 흙이 묻어도 되는 【겉옷】을 입고 오세요.","· 모종은 학교에서 준비하니 따로 사 오지 않아도 됩니다."],"title":"학급 게시판에 붙은 안내 글 (【 】는 굵은 글씨)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#2','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C5',1,'mc','auto','방송하는 사람이 중요한 곳을 알린 방법은 어느 것인가요?',ARRAY['K6-2-u5-X06']::text[],false,'{"seq":2,"concept":"K6-2-u5-C5","difficulty":1,"kind":"mc","stem":"방송하는 사람이 중요한 곳을 알린 방법은 어느 것인가요?","options":[{"t":"목소리를 크고 또박또박하게 하고 말을 천천히 했다","correct":true},{"t":"중요한 낱말에 밑줄을 그었다","mis":"K6-2-u5-X06"},{"t":"문장 끝에 느낌표를 붙였다","mis":"K6-2-u5-X06"},{"t":"글자를 크게 썼다","mis":"K6-2-u5-X06"}],"explanation":["밑줄 · 느낌표 · 글자 크기는 글의 방법이에요.","말에서는 목소리의 크기와 속도를 써요.","괄호 안을 다시 읽어 보세요."],"asset":{"type":"passage","lines":["자, 알림 하나 하겠습니다. 다음 주 목요일 다섯째 시간에","학교 뒤편 텃밭에서 상추 모종을 심습니다.","(목소리를 크고 또박또박하게) 목장갑을 꼭 가져오세요.","흙이 묻어도 되는 겉옷을 입고 오면 됩니다.","(말을 천천히 하며) 모종은 학교에서 준비합니다.","따로 사 오지 않아도 됩니다."],"title":"같은 안내를 방송으로 한 말 (괄호는 목소리가 달라진 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#3','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C4',1,'ox','auto','문자 언어는 한 번 적으면 필요할 때 다시 볼 수 있어요.',ARRAY['K6-2-u5-X07']::text[],false,'{"seq":3,"concept":"K6-2-u5-C4","difficulty":1,"kind":"ox","stem":"문자 언어는 한 번 적으면 필요할 때 다시 볼 수 있어요.","answer":"O","reason_options":[{"t":"적은 내용이 그대로 남기 때문에","correct":true},{"t":"글은 쓰고 나면 고칠 수 없기 때문에","mis":"K6-2-u5-X07"}],"mis":"K6-2-u5-X07","explanation":["글은 보통 오래 남아요.","그래서 다시 볼 수 있어요.","쓴 뒤에 고칠 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#4','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C5',1,'sa','auto','음성 언어에서 말소리의 높낮이를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u5-C5","difficulty":1,"kind":"sa","stem":"음성 언어에서 말소리의 높낮이를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["억양"],"explanation":["말은 목소리의 크기와 속도로도 뜻을 전해요.","말소리의 높낮이는 억양이에요.","억양으로 감정과 의도를 함께 전해요."],"mis":"K6-2-u5-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#5','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C4',2,'match','auto','같은 일을 하는 방법끼리 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C4","difficulty":2,"kind":"match","stem":"같은 일을 하는 방법끼리 이으세요.","pairs":[{"l":"글자를 굵게 합니다","r":"목소리를 크게 합니다"},{"l":"느낌표를 붙입니다","r":"억양을 올립니다"},{"l":"줄을 나누어 띄웁니다","r":"잠깐 쉬었다 말합니다"}],"mis":"K6-2-u5-X06","explanation":["글은 눈에, 말은 귀에 띄게 해요.","굵은 글씨와 큰 목소리는 강조예요.","줄 나눔과 쉬기는 나누어 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#6','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C5',2,'mc','auto','음성 언어의 특성으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X06']::text[],false,'{"seq":6,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"음성 언어의 특성으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람의 반응을 보며 다시 설명할 수 있다","correct":true},{"t":"적은 내용이 그대로 남는다","mis":"K6-2-u5-X01"},{"t":"글자의 굵기로 중요한 곳을 보인다","mis":"K6-2-u5-X06"},{"t":"쓴 뒤에 천천히 고칠 수 있다","mis":"K6-2-u5-X01"}],"explanation":["남기 · 굵기 · 고치기는 문자 언어의 특성이에요.","말은 마주 보고 해요.","그래서 반응을 보며 바꿀 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#7','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C6',2,'mc','auto','복잡한 차례를 글로도 적어 주면 좋은 까닭으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-2-u5-X09']::text[],false,'{"seq":7,"concept":"K6-2-u5-C6","difficulty":2,"kind":"mc","stem":"복잡한 차례를 글로도 적어 주면 좋은 까닭으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글로 적으면 언제나 더 훌륭한 안내가 되기 때문에","correct":true},{"t":"잊어버렸을 때 다시 볼 수 있기 때문에","mis":"K6-2-u5-X09"},{"t":"차례를 눈으로 짚어 가며 따라 할 수 있기 때문에","mis":"K6-2-u5-X09"},{"t":"여러 사람이 똑같은 내용을 나누어 갖기 때문에","mis":"K6-2-u5-X09"}],"explanation":["세 까닭은 글의 특성과 이어져 있어요.","「언제나 더 훌륭하다」는 등수를 매긴 말이에요.","까닭은 특성과 이어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#8','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C7',2,'ox','auto','어렵거나 헷갈리는 내용일수록 말과 글을 함께 쓰면 좋아요.',ARRAY['K6-2-u5-X11']::text[],false,'{"seq":8,"concept":"K6-2-u5-C7","difficulty":2,"kind":"ox","stem":"어렵거나 헷갈리는 내용일수록 말과 글을 함께 쓰면 좋아요.","answer":"O","reason_options":[{"t":"말로 놓친 곳을 글로 다시 확인할 수 있기 때문에","correct":true},{"t":"같은 내용을 두 번 쓰면 시간이 아깝기 때문에","mis":"K6-2-u5-X11"}],"mis":"K6-2-u5-X11","explanation":["말은 생생하지만 놓치면 되돌릴 수 없어요.","글은 남아서 다시 볼 수 있어요.","둘을 함께 쓰면 서로 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#9','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C4',2,'mc','auto','안내 글과 방송을 견주었을 때 안내 글만 할 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u5-X06','K6-2-u5-X08']::text[],false,'{"seq":9,"concept":"K6-2-u5-C4","difficulty":2,"kind":"mc","stem":"안내 글과 방송을 견주었을 때 안내 글만 할 수 있는 것은 어느 것인가요?","options":[{"t":"집에 가서도 챙길 것을 다시 읽어 볼 수 있다","correct":true},{"t":"목소리로 「꼭」을 힘주어 말할 수 있다","mis":"K6-2-u5-X06"},{"t":"듣는 사람이 그 자리에서 되물을 수 있다","mis":"K6-2-u5-X08"},{"t":"말을 천천히 해서 중요한 곳을 알린다","mis":"K6-2-u5-X06"}],"explanation":["힘주어 말하기와 되묻기, 천천히 말하기는 말의 특성이에요.","글은 남아 있어요.","그래서 나중에 다시 볼 수 있어요."],"asset":{"type":"passage","lines":["학급 텃밭 가꾸기 안내","언제 · 다음 주 목요일 다섯째 시간","어디에서 · 학교 뒤편 작은 텃밭 / 무엇을 · 상추 모종 심기","챙길 것 · 손을 덮는 【목장갑】을 꼭 가져오세요.","· 흙이 묻어도 되는 【겉옷】을 입고 오세요.","· 모종은 학교에서 준비하니 따로 사 오지 않아도 됩니다."],"title":"학급 게시판에 붙은 안내 글 (【 】는 굵은 글씨)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#10','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C6',3,'error','auto','「이 상황에는 문자 언어가 알맞다」를 말했어요. 까닭까지 바르게 말하지 않은 친구는 누구인가요?',ARRAY['K6-2-u5-X09']::text[],false,'{"seq":10,"concept":"K6-2-u5-C6","difficulty":3,"kind":"error","stem":"「이 상황에는 문자 언어가 알맞다」를 말했어요. 까닭까지 바르게 말하지 않은 친구는 누구인가요?","options":[{"t":"민서 — 「글이 알맞아. 그냥 글이 좋으니까.」","correct":true,"mis_target":"K6-2-u5-X09"},{"t":"주원 — 「차례가 여러 개라 나중에 다시 봐야 하는데, 글은 그대로 남거든.」","mis":"K6-2-u5-X09"},{"t":"가은 — 「여러 사람이 똑같은 내용을 정확하게 나누어 가져야 해서야.」","mis":"K6-2-u5-X09"}],"explanation":["주원과 가은은 까닭을 글의 특성과 이었어요.","민서는 고르기만 하고 까닭이 없어요.","고른 까닭까지가 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#1','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C5',2,'mc','auto','방송에서 「모종은 학교에서 준비합니다」를 말을 천천히 하며 알린 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X08','K6-2-u5-X06']::text[],false,'{"seq":1,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"방송에서 「모종은 학교에서 준비합니다」를 말을 천천히 하며 알린 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람이 놓치지 않고 「사 오지 않아도 된다」는 것을 알게 하려고","correct":true},{"t":"방송 시간을 늘리려고","mis":"K6-2-u5-X08"},{"t":"글자 수를 맞추려고","mis":"K6-2-u5-X06"},{"t":"목소리가 작아서","mis":"K6-2-u5-X08"}],"explanation":["천천히 말하면 귀에 또렷이 남아요.","사 오지 않아도 된다는 것은 중요한 내용이에요.","말의 속도도 강조 방법이에요."],"asset":{"type":"passage","lines":["자, 알림 하나 하겠습니다. 다음 주 목요일 다섯째 시간에","학교 뒤편 텃밭에서 상추 모종을 심습니다.","(목소리를 크고 또박또박하게) 목장갑을 꼭 가져오세요.","흙이 묻어도 되는 겉옷을 입고 오면 됩니다.","(말을 천천히 하며) 모종은 학교에서 준비합니다.","따로 사 오지 않아도 됩니다."],"title":"같은 안내를 방송으로 한 말 (괄호는 목소리가 달라진 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#2','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C5',2,'ox','auto','음성 언어로 말할 때에는 모르는 곳을 그 자리에서 되물을 수 있어요.',ARRAY['K6-2-u5-X03']::text[],false,'{"seq":2,"concept":"K6-2-u5-C5","difficulty":2,"kind":"ox","stem":"음성 언어로 말할 때에는 모르는 곳을 그 자리에서 되물을 수 있어요.","answer":"O","reason_options":[{"t":"말하는 사람과 듣는 사람이 그 자리에서 주고받기 때문에","correct":true},{"t":"말은 글보다 언제나 정확하기 때문에","mis":"K6-2-u5-X03"}],"mis":"K6-2-u5-X03","explanation":["말은 마주 보고 주고받아요.","모르면 바로 물을 수 있어요.","어느 쪽이 언제나 정확한 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#3','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C4',3,'mc','auto','안내 글에서 「모종은 학교에서 준비하니 따로 사 오지 않아도 됩니다」를 따로 적은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X06','K6-2-u5-X25']::text[],false,'{"seq":3,"concept":"K6-2-u5-C4","difficulty":3,"kind":"mc","stem":"안내 글에서 「모종은 학교에서 준비하니 따로 사 오지 않아도 됩니다」를 따로 적은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"읽는 사람이 잘못 알고 모종을 사 오는 일이 없도록 하려고","correct":true},{"t":"글을 길게 보이게 하려고","mis":"K6-2-u5-X13"},{"t":"목소리로 강조할 수 없어서 아무 줄이나 더 적으려고","mis":"K6-2-u5-X06"},{"t":"모종 가게를 알리려고","mis":"K6-2-u5-X25"}],"explanation":["읽는 사람은 모종도 챙겨야 하는지 궁금할 수 있어요.","그래서 할 일과 하지 않아도 될 일을 함께 적었어요.","독자를 생각한 줄이에요."],"asset":{"type":"passage","lines":["학급 텃밭 가꾸기 안내","언제 · 다음 주 목요일 다섯째 시간","어디에서 · 학교 뒤편 작은 텃밭 / 무엇을 · 상추 모종 심기","챙길 것 · 손을 덮는 【목장갑】을 꼭 가져오세요.","· 흙이 묻어도 되는 【겉옷】을 입고 오세요.","· 모종은 학교에서 준비하니 따로 사 오지 않아도 됩니다."],"title":"학급 게시판에 붙은 안내 글 (【 】는 굵은 글씨)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#4','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C6',3,'mc','auto','다음 가운데 음성 언어가 더 알맞은 상황은 어느 것인가요?',ARRAY['K6-2-u5-X10']::text[],false,'{"seq":4,"concept":"K6-2-u5-C6","difficulty":3,"kind":"mc","stem":"다음 가운데 음성 언어가 더 알맞은 상황은 어느 것인가요?","options":[{"t":"처음 만난 전학생에게 반갑게 인사하며 우리 반을 소개할 때","correct":true},{"t":"일주일 동안 지킬 청소 당번표를 알릴 때","mis":"K6-2-u5-X10"},{"t":"도서관 책을 빌리는 다섯 가지 차례를 알릴 때","mis":"K6-2-u5-X10"},{"t":"학급 회의에서 정한 규칙을 오래 기억하게 할 때","mis":"K6-2-u5-X10"}],"explanation":["당번표 · 차례 · 규칙은 다시 봐야 해서 글이 알맞아요.","반가운 마음은 목소리로 생생하게 전해져요.","전학생도 그 자리에서 되물을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#5','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C5',3,'match','auto','음성 언어의 특성과 그 예를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C5","difficulty":3,"kind":"match","stem":"음성 언어의 특성과 그 예를 이으세요.","pairs":[{"l":"바로 전해지고 끝나면 사라진다","r":"방송을 놓친 친구가 내용을 모른다"},{"l":"목소리로 감정을 함께 전한다","r":"「축하해!」를 밝은 목소리로 말한다"},{"l":"반응을 보며 다시 설명한다","r":"친구 표정을 보고 더 쉽게 말해 준다"}],"mis":"K6-2-u5-X08","explanation":["놓치면 되돌릴 수 없어요.","목소리에 마음이 실려요.","마주 보면 반응을 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#6','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C2',3,'error','auto','「매체에 따라 특성이 달라지는 예」를 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X02']::text[],false,'{"seq":6,"concept":"K6-2-u5-C2","difficulty":3,"kind":"error","stem":"「매체에 따라 특성이 달라지는 예」를 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"수아 — 「말은 절대 남지 않고, 글은 절대 사라지지 않아.」","correct":true,"mis_target":"K6-2-u5-X02"},{"t":"도윤 — 「녹음한 말은 남고, 빠르게 지나가는 대화 글은 흘러가.」","mis":"K6-2-u5-X02"},{"t":"라온 — 「화면을 넘기면 없어지는 자막은 글인데도 다시 보기 어려워.」","mis":"K6-2-u5-X02"}],"explanation":["도윤과 라온은 매체에 따라 달라지는 예를 들었어요.","수아는 「절대」로 규칙을 만들었어요.","특성은 기본 성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#7','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C7',3,'mc','auto','선생님이 실험 차례를 말로 설명하면서 칠판에도 차례를 적었어요. 이렇게 한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X08','K6-2-u5-X03']::text[],false,'{"seq":7,"concept":"K6-2-u5-C7","difficulty":3,"kind":"mc","stem":"선생님이 실험 차례를 말로 설명하면서 칠판에도 차례를 적었어요. 이렇게 한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말로 생생하게 설명하고, 놓친 차례는 칠판을 보며 다시 확인하게 하려고","correct":true},{"t":"같은 내용을 두 번 해서 시간을 채우려고","mis":"K6-2-u5-X11"},{"t":"말만으로는 감정을 전할 수 없어서","mis":"K6-2-u5-X08"},{"t":"글이 말보다 언제나 정확해서","mis":"K6-2-u5-X03"}],"explanation":["말은 흐름을 이어 주지만 놓치면 사라져요.","칠판의 글은 남아요.","두 언어가 서로 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#8','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C6',4,'mc','auto','「다음 주 목요일 텃밭 가꾸기」를 알리는 가장 알맞은 방법과 까닭을 함께 말한 것은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X03','K6-2-u5-X10']::text[],false,'{"seq":8,"concept":"K6-2-u5-C6","difficulty":4,"kind":"mc","stem":"「다음 주 목요일 텃밭 가꾸기」를 알리는 가장 알맞은 방법과 까닭을 함께 말한 것은 어느 것인가요?","options":[{"t":"방송으로 알리고 게시판에도 붙인다 — 말로는 중요한 곳을 힘주어 전하고, 글로는 여러 날 뒤에도 챙길 것을 다시 볼 수 있으니까","correct":true},{"t":"방송만 한다 — 목소리가 크면 누구나 기억하니까","mis":"K6-2-u5-X02"},{"t":"게시판에만 붙인다 — 글이 말보다 좋은 방법이니까","mis":"K6-2-u5-X03"},{"t":"아무 방법이나 괜찮다 — 어차피 내용은 같으니까","mis":"K6-2-u5-X10"}],"explanation":["여러 날 뒤의 일이라 다시 봐야 해요.","말은 귀에 띄게 강조할 수 있어요.","둘을 함께 쓰고 까닭을 특성과 이어요."],"asset":{"type":"passage","lines":["자, 알림 하나 하겠습니다. 다음 주 목요일 다섯째 시간에","학교 뒤편 텃밭에서 상추 모종을 심습니다.","(목소리를 크고 또박또박하게) 목장갑을 꼭 가져오세요.","흙이 묻어도 되는 겉옷을 입고 오면 됩니다.","(말을 천천히 하며) 모종은 학교에서 준비합니다.","따로 사 오지 않아도 됩니다."],"title":"같은 안내를 방송으로 한 말 (괄호는 목소리가 달라진 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#9','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C4',4,'essay','teacher','텃밭 안내 글과 방송을 견주어, 중요한 내용을 알리는 방법이 어떻게 다른지 쓰고, 각각의 방법이 어떤 언어의 특성 때문인지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C4","difficulty":4,"kind":"essay","stem":"텃밭 안내 글과 방송을 견주어, 중요한 내용을 알리는 방법이 어떻게 다른지 쓰고, 각각의 방법이 어떤 언어의 특성 때문인지 쓰세요.","answer_guide":{"answer":"예: 안내 글은 목장갑과 겉옷을 굵은 글씨로 쓰고 줄을 나누어 눈에 띄게 했다. 문자 언어는 글자의 크기 · 굵기 · 줄 나눔으로 중요한 곳을 눈에 보이게 하기 때문이다. 방송은 목장갑 부분을 크고 또박또박하게, 모종 부분을 천천히 말해 귀에 띄게 했다. 음성 언어는 목소리의 크기 · 억양 · 속도로 강조하기 때문이다.","scoring_points":["안내 글의 강조 방법을 썼는가","방송의 강조 방법을 썼는가","각 방법을 해당 언어의 특성과 이었는가"]},"explanation":["글은 눈에 띄게.","말은 귀에 띄게.","방법마다 특성과 이어요."],"asset":{"type":"passage","lines":["자, 알림 하나 하겠습니다. 다음 주 목요일 다섯째 시간에","학교 뒤편 텃밭에서 상추 모종을 심습니다.","(목소리를 크고 또박또박하게) 목장갑을 꼭 가져오세요.","흙이 묻어도 되는 겉옷을 입고 오면 됩니다.","(말을 천천히 하며) 모종은 학교에서 준비합니다.","따로 사 오지 않아도 됩니다."],"title":"같은 안내를 방송으로 한 말 (괄호는 목소리가 달라진 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#10','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C7',4,'essay','teacher','어렵거나 헷갈리는 내용을 알릴 때 말과 글을 함께 쓰면 좋은 까닭을 두 언어의 특성으로 설명하고, 우리 반에서 말과 글을 함께 쓰면 좋을 상황을 하나 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C7","difficulty":4,"kind":"essay","stem":"어렵거나 헷갈리는 내용을 알릴 때 말과 글을 함께 쓰면 좋은 까닭을 두 언어의 특성으로 설명하고, 우리 반에서 말과 글을 함께 쓰면 좋을 상황을 하나 들어 쓰세요.","answer_guide":{"answer":"예: 말로 설명하면 목소리와 억양으로 생생하게 전하고 그 자리에서 되물을 수 있지만, 놓치면 되돌릴 수 없다. 같은 내용을 글로도 보여 주면 남아 있어서 놓친 곳을 다시 확인할 수 있다. 그래서 둘을 함께 쓰면 서로 보완한다. 상황 — 학예회 무대 차례와 모이는 곳을 알릴 때 선생님이 말로 설명하고 칠판에도 적어 준다.","scoring_points":["음성 언어의 장점과 한계를 썼는가","문자 언어가 보완하는 점을 썼는가","알맞은 상황을 들었는가"]},"explanation":["말은 생생하지만 사라져요.","글은 남아요.","어렵고 헷갈릴수록 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#1','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C8',1,'mc','auto','영상에서 [자막]은 무엇을 가리키나요?',ARRAY['K6-2-u5-X12']::text[],false,'{"seq":1,"concept":"K6-2-u5-C8","difficulty":1,"kind":"mc","stem":"영상에서 [자막]은 무엇을 가리키나요?","options":[{"t":"화면에 글자로 뜨는 말","correct":true},{"t":"해설하는 사람이 하는 말","mis":"K6-2-u5-X12"},{"t":"배경에 깔리는 음악","mis":"K6-2-u5-X12"},{"t":"그때 보이는 장면","mis":"K6-2-u5-X12"}],"explanation":["해설하는 말은 [말]이에요.","음악은 [소리], 장면은 [화면]이에요.","글자로 뜨는 말이 자막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#2','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C8',1,'mc','auto','이 영상이 전하려는 것은 무엇인가요?',ARRAY['K6-2-u5-X12']::text[],false,'{"seq":2,"concept":"K6-2-u5-C8","difficulty":1,"kind":"mc","stem":"이 영상이 전하려는 것은 무엇인가요?","options":[{"t":"서로 잠깐 기다려 주면 다치는 일을 막을 수 있다","correct":true},{"t":"승강기는 되도록 타지 않는 것이 좋다","mis":"K6-2-u5-X12"},{"t":"승강기를 탈 때에는 빨리 움직여야 한다","mis":"K6-2-u5-X12"},{"t":"열림 단추는 누르면 안 된다","mis":"K6-2-u5-X12"}],"explanation":["장면 이에서 뛰어드는 위험을 보여 줘요.","장면 삼에서 열림 단추를 누르면 된다고 알려 줘요.","마지막에 「잠깐만 기다려 주세요」라고 부탁해요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#3','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C9',1,'ox','auto','자막은 꼭 남겨야 할 내용을 눈에 보이게 붙들어 두는 일을 해요.',ARRAY['K6-2-u5-X11']::text[],false,'{"seq":3,"concept":"K6-2-u5-C9","difficulty":1,"kind":"ox","stem":"자막은 꼭 남겨야 할 내용을 눈에 보이게 붙들어 두는 일을 해요.","answer":"O","reason_options":[{"t":"말은 지나가지만 글자는 화면에 남아 다시 볼 수 있기 때문에","correct":true},{"t":"자막은 영상을 꾸미는 장식일 뿐이기 때문에","mis":"K6-2-u5-X11"}],"mis":"K6-2-u5-X11","explanation":["해설하는 말은 지나가요.","자막은 화면에 글자로 남아요.","그래서 놓친 내용을 다시 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#4','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C3',1,'mc','auto','책과 신문은 어떤 매체인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":4,"concept":"K6-2-u5-C3","difficulty":1,"kind":"mc","stem":"책과 신문은 어떤 매체인가요?","options":[{"t":"인쇄 매체","correct":true},{"t":"음성 매체","mis":"K6-2-u5-X04"},{"t":"영상 매체","mis":"K6-2-u5-X04"},{"t":"소리 매체","mis":"K6-2-u5-X04"}],"explanation":["책과 신문은 글자를 바탕으로 해요.","표 · 그림 · 사진을 함께 써요.","그래서 인쇄 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#5','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C8',2,'match','auto','장면과 그 장면에서 쓴 방법을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C8","difficulty":2,"kind":"match","stem":"장면과 그 장면에서 쓴 방법을 이으세요.","pairs":[{"l":"장면 이 — 뛰어드는 순간","r":"음악을 그치고 자막으로 위험을 알림"},{"l":"장면 삼 — 열림 단추","r":"말과 자막으로 할 일을 함께 알림"},{"l":"장면 사 — 마지막 부탁","r":"장면과 말로 부탁을 남김"}],"mis":"K6-2-u5-X12","explanation":["장면 이에서는 음악이 뚝 그쳐요.","장면 삼에서는 말과 자막을 함께 써요.","장면 사에서는 웃는 장면과 말이 남아요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#6','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C9',2,'mc','auto','말한 내용을 자막으로 함께 보여 주면 좋은 까닭은 무엇인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X13']::text[],false,'{"seq":6,"concept":"K6-2-u5-C9","difficulty":2,"kind":"mc","stem":"말한 내용을 자막으로 함께 보여 주면 좋은 까닭은 무엇인가요?","options":[{"t":"놓치거나 헷갈리는 내용을 눈으로 다시 확인할 수 있어서","correct":true},{"t":"영상의 길이를 짧게 줄일 수 있어서","mis":"K6-2-u5-X11"},{"t":"화면에 들어가는 글자 수를 늘릴 수 있어서","mis":"K6-2-u5-X13"},{"t":"해설하는 말을 하지 않아도 되어서","mis":"K6-2-u5-X11"}],"explanation":["말은 지나가요.","자막은 화면에 남아요.","둘이 서로 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#7','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C8',2,'mc','auto','장면 이에서 음악이 뚝 그친 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X14','K6-2-u5-X12']::text[],false,'{"seq":7,"concept":"K6-2-u5-C8","difficulty":2,"kind":"mc","stem":"장면 이에서 음악이 뚝 그친 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"위험한 순간에 눈길을 모으려고","correct":true},{"t":"음악이 다 끝나서","mis":"K6-2-u5-X14"},{"t":"영상이 고장 나서","mis":"K6-2-u5-X14"},{"t":"해설하는 사람이 쉬려고","mis":"K6-2-u5-X12"}],"explanation":["조용한 음악이 흐르다 갑자기 그쳐요.","그 순간 화면도 멈춰요.","소리를 바꾸어 어디를 눈여겨볼지 알려요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#8','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C10',2,'ox','auto','자막을 화면 가득 채울수록 전하려는 것이 또렷해져요.',ARRAY['K6-2-u5-X13']::text[],false,'{"seq":8,"concept":"K6-2-u5-C10","difficulty":2,"kind":"ox","stem":"자막을 화면 가득 채울수록 전하려는 것이 또렷해져요.","answer":"X","reason_options":[{"t":"무엇이 중요한지 흐려지기 때문에","correct":true},{"t":"글자가 많을수록 많이 전해지기 때문에","mis":"K6-2-u5-X13"}],"mis":"K6-2-u5-X13","explanation":["자막이 너무 많으면 어디를 봐야 할지 몰라요.","꼭 남길 곳에만 자막을 둬요.","표현 효과는 개수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#9','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C9',2,'mc','auto','자막에서 중요한 곳을 강조하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X06','K6-2-u5-X12']::text[],false,'{"seq":9,"concept":"K6-2-u5-C9","difficulty":2,"kind":"mc","stem":"자막에서 중요한 곳을 강조하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"색 · 크기 · 모양을 달리한다","correct":true},{"t":"목소리의 억양을 올린다","mis":"K6-2-u5-X06"},{"t":"효과음을 크게 넣는다","mis":"K6-2-u5-X12"},{"t":"말을 천천히 한다","mis":"K6-2-u5-X06"}],"explanation":["억양 · 효과음 · 말의 속도는 소리로 하는 강조예요.","자막은 글자예요.","글자의 색 · 크기 · 모양으로 강조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#10','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C10',3,'error','auto','매체 자료의 표현 효과에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X10']::text[],false,'{"seq":10,"concept":"K6-2-u5-C10","difficulty":3,"kind":"error","stem":"매체 자료의 표현 효과에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「자막 · 음악 · 장면을 많이 넣을수록 표현 효과가 좋은 영상이야.」","correct":true,"mis_target":"K6-2-u5-X13"},{"t":"연우 — 「중요한 곳에서 소리를 바꾸면 눈길이 모여.」","mis":"K6-2-u5-X10"},{"t":"지민 — 「그 요소가 무엇을 돕고 있는지를 봐야 해.」","mis":"K6-2-u5-X10"}],"explanation":["연우와 지민은 바르게 말했어요.","하율은 개수로 효과를 쟀어요.","표현 효과는 무엇을 돕는가로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#1','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C8',2,'mc','auto','영상에서 [화면] — 장면과 움직임이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X12','K6-2-u5-X05']::text[],false,'{"seq":1,"concept":"K6-2-u5-C8","difficulty":2,"kind":"mc","stem":"영상에서 [화면] — 장면과 움직임이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 일이 벌어지는지 한눈에 보여 준다","correct":true},{"t":"꼭 남겨야 할 내용을 글자로 붙들어 둔다","mis":"K6-2-u5-X12"},{"t":"흐름을 말로 이어 준다","mis":"K6-2-u5-X12"},{"t":"영상을 만든 날짜를 알려 준다","mis":"K6-2-u5-X05"}],"explanation":["글자로 붙들기는 자막이 해요.","말로 잇기는 해설이 해요.","장면은 일이 벌어지는 모습을 한눈에 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#2','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C8',2,'ox','auto','이 영상은 문자 언어 없이 음성 언어만 썼어요.',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":2,"concept":"K6-2-u5-C8","difficulty":2,"kind":"ox","stem":"이 영상은 문자 언어 없이 음성 언어만 썼어요.","answer":"X","reason_options":[{"t":"장면 이와 장면 삼에 자막이 있기 때문에","correct":true},{"t":"영상에는 글자를 넣을 수 없기 때문에","mis":"K6-2-u5-X04"}],"mis":"K6-2-u5-X04","explanation":["[자막]이 문자 언어예요.","장면 이와 장면 삼에 자막이 있어요.","말과 자막을 함께 썼어요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#3','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C9',3,'mc','auto','장면 삼에서 「열림 단추」를 말로도 하고 자막으로도 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X08','K6-2-u5-X13']::text[],false,'{"seq":3,"concept":"K6-2-u5-C9","difficulty":3,"kind":"mc","stem":"장면 삼에서 「열림 단추」를 말로도 하고 자막으로도 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해야 할 일을 놓치지 않고 눈으로도 확인하게 하려고","correct":true},{"t":"같은 말을 두 번 해서 영상을 길게 하려고","mis":"K6-2-u5-X11"},{"t":"말만으로는 감정을 전할 수 없어서","mis":"K6-2-u5-X08"},{"t":"자막이 많을수록 좋은 영상이라서","mis":"K6-2-u5-X13"}],"explanation":["열림 단추를 누르는 것이 시청자가 할 일이에요.","말은 지나가지만 자막은 남아요.","할 일을 두 언어로 붙들어 줬어요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#4','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C4',3,'mc','auto','매체마다 주로 쓰는 방법을 알맞게 짝 지은 것은 어느 것인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":4,"concept":"K6-2-u5-C4","difficulty":3,"kind":"mc","stem":"매체마다 주로 쓰는 방법을 알맞게 짝 지은 것은 어느 것인가요?","options":[{"t":"라디오 — 음성 언어에 소리와 음악을 더한다","correct":true},{"t":"신문 — 음성 언어에 움직임을 더한다","mis":"K6-2-u5-X04"},{"t":"공익 영상 — 문자 언어만 쓴다","mis":"K6-2-u5-X04"},{"t":"책 — 소리와 음악을 바탕으로 한다","mis":"K6-2-u5-X04"}],"explanation":["신문과 책은 문자 언어가 바탕이에요.","영상은 여러 방법이 어우러져요.","라디오는 소리로 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#5','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C12',3,'error','auto','영상의 요소가 하는 일을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X12']::text[],false,'{"seq":5,"concept":"K6-2-u5-C12","difficulty":3,"kind":"error","stem":"영상의 요소가 하는 일을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「배경 음악은 꼭 남겨야 할 낱말을 글자로 보여 줘.」","correct":true,"mis_target":"K6-2-u5-X12"},{"t":"소윤 — 「해설하는 말은 장면과 장면 사이의 흐름을 이어 줘.」","mis":"K6-2-u5-X12"},{"t":"다인 — 「자막은 놓치기 쉬운 것을 붙들어 둬.」","mis":"K6-2-u5-X12"}],"explanation":["소윤과 다인은 바르게 말했어요.","글자로 보여 주는 것은 자막이에요.","음악은 어디를 눈여겨볼지 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#6','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C10',3,'mc','auto','어떤 영상이 처음부터 끝까지 큰 음악을 깔고 장면을 쉴 새 없이 바꾸었어요. 어떤 문제가 생기나요?',ARRAY['K6-2-u5-X13','K6-2-u5-X04']::text[],false,'{"seq":6,"concept":"K6-2-u5-C10","difficulty":3,"kind":"mc","stem":"어떤 영상이 처음부터 끝까지 큰 음악을 깔고 장면을 쉴 새 없이 바꾸었어요. 어떤 문제가 생기나요?","options":[{"t":"무엇이 중요한지 흐려져 전하려는 것이 잘 보이지 않는다","correct":true},{"t":"신나는 느낌이 나서 전하려는 것이 더 또렷해진다","mis":"K6-2-u5-X13"},{"t":"아무 문제가 없다. 요소가 많을수록 좋다","mis":"K6-2-u5-X13"},{"t":"자막을 하나도 쓰지 않았으니 영상이 아니다","mis":"K6-2-u5-X04"}],"explanation":["계속 크면 중요한 곳에서 소리를 바꿀 수 없어요.","장면이 쉴 새 없이 바뀌면 오래 볼 수 없어요.","요소가 많다고 잘 전달되는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#7','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C9',3,'match','auto','강조하는 방법과 그 방법을 쓰는 것을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C9","difficulty":3,"kind":"match","stem":"강조하는 방법과 그 방법을 쓰는 것을 이으세요.","pairs":[{"l":"자막의 색과 크기를 달리한다","r":"문자 언어"},{"l":"목소리를 크고 또박또박하게 한다","r":"음성 언어"},{"l":"중요한 곳에서 음악을 그친다","r":"소리와 음악"}],"mis":"K6-2-u5-X06","explanation":["자막은 글자로 강조해요.","목소리는 말로 강조해요.","음악을 바꾸면 소리로 강조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#8','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C10',4,'mc','auto','「잠깐만 기다려 주세요」 영상에 대한 평가로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X14','K6-2-u5-X15']::text[],false,'{"seq":8,"concept":"K6-2-u5-C10","difficulty":4,"kind":"mc","stem":"「잠깐만 기다려 주세요」 영상에 대한 평가로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장면 이에서 음악을 그치고 자막을 쓴 것은 위험한 순간을 눈여겨보게 도와 표현 효과가 있다","correct":true},{"t":"자막이 두 번밖에 없어 표현 효과가 적다","mis":"K6-2-u5-X13"},{"t":"음악이 그친 것은 실수라서 고쳐야 한다","mis":"K6-2-u5-X14"},{"t":"그냥 좋은 영상이다","mis":"K6-2-u5-X15"}],"explanation":["자막 수로 효과를 재지 않아요.","음악이 그친 것은 까닭이 있어요.","그 요소가 무엇을 돕는지 말해야 평가가 돼요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#9','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C9',4,'essay','teacher','「잠깐만 기다려 주세요」 영상에서 말과 자막이 서로 어떻게 보완하는지 장면 하나를 골라 쓰고, 음악이 한 일도 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C9","difficulty":4,"kind":"essay","stem":"「잠깐만 기다려 주세요」 영상에서 말과 자막이 서로 어떻게 보완하는지 장면 하나를 골라 쓰고, 음악이 한 일도 함께 쓰세요.","answer_guide":{"answer":"예: 장면 삼에서 해설하는 사람은 「안에서 열림 단추를 눌러 주면 됩니다.」라고 말하고, 자막으로 「열림 단추 ← 문 옆」을 보여 준다. 말은 흐름을 이어 주지만 지나가 버리는데, 자막은 단추가 어디에 있는지를 눈으로 다시 확인하게 해 준다. 음악은 장면 이에서 뚝 그쳐 뛰어드는 순간이 위험하다는 것을 눈여겨보게 했다.","scoring_points":["장면 하나를 골라 말과 자막을 찾았는가","말과 자막이 서로 보완하는 점을 썼는가","음악이 한 일을 썼는가"]},"explanation":["말은 흐름을 이어요.","자막은 붙들어 둬요.","음악은 눈여겨볼 곳을 알려요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#10','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C10',4,'essay','teacher','「표현 효과는 요소의 개수가 아니라 그 요소가 무엇을 돕는가로 본다.」는 말을 예를 들어 설명하고, 둘레의 안내문이나 영상 하나를 떠올려 「이 ○○은 △△을 돕는다」 꼴로 한 문장을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C10","difficulty":4,"kind":"essay","stem":"「표현 효과는 요소의 개수가 아니라 그 요소가 무엇을 돕는가로 본다.」는 말을 예를 들어 설명하고, 둘레의 안내문이나 영상 하나를 떠올려 「이 ○○은 △△을 돕는다」 꼴로 한 문장을 쓰세요.","answer_guide":{"answer":"예: 자막을 화면 가득 채우거나 음악을 계속 크게 깔면 요소는 많아도 무엇이 중요한지 흐려진다. 꼭 남길 곳에만 자막을 두고 중요한 곳에서 소리를 바꾸면 요소가 적어도 전하려는 것이 또렷해진다. 문장 — 우리 학교 급식실 안내판의 빨간 글씨는 뜨거운 국 조심을 놓치지 않게 돕는다.","scoring_points":["많이 넣을 때의 문제를 예로 썼는가","알맞게 넣을 때의 효과를 썼는가","요소와 그것이 돕는 것을 이어 한 문장을 썼는가"]},"explanation":["개수로 재지 않아요.","무엇을 돕는지 봐요.","「이 ○○은 △△을 돕는다」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#1','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C13',1,'mc','auto','바닷물이 뭍 쪽으로 밀려 들어오는 것을 무엇이라고 하나요?',ARRAY['K6-2-u5-X18']::text[],false,'{"seq":1,"concept":"K6-2-u5-C13","difficulty":1,"kind":"mc","stem":"바닷물이 뭍 쪽으로 밀려 들어오는 것을 무엇이라고 하나요?","options":[{"t":"밀물","correct":true},{"t":"썰물","mis":"K6-2-u5-X18"},{"t":"퇴적","mis":"K6-2-u5-X18"},{"t":"갯벌","mis":"K6-2-u5-X18"}],"explanation":["바다 쪽으로 빠져나가는 것은 썰물이에요.","쌓이는 일은 퇴적이에요.","밀려 들어오는 것이 밀물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#2','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C13',1,'sa','auto','흙이나 모래 같은 것이 물이나 바람의 힘으로 쌓이는 일을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C13","difficulty":1,"kind":"sa","stem":"흙이나 모래 같은 것이 물이나 바람의 힘으로 쌓이는 일을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["퇴적"],"explanation":["강물이 흙과 모래를 실어 와요.","물살이 느려지면 가라앉아 쌓여요.","이렇게 쌓이는 일이 퇴적이에요."],"mis":"K6-2-u5-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#3','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C13',1,'mc','auto','이 영상은 무엇을 다루고 있나요?',ARRAY['K6-2-u5-X17']::text[],false,'{"seq":3,"concept":"K6-2-u5-C13","difficulty":1,"kind":"mc","stem":"이 영상은 무엇을 다루고 있나요?","options":[{"t":"갯벌이 만들어지는 과정","correct":true},{"t":"바닷물이 오염되는 까닭","mis":"K6-2-u5-X17"},{"t":"배가 항구에 드나드는 차례","mis":"K6-2-u5-X17"},{"t":"강물이 얼어붙는 과정","mis":"K6-2-u5-X17"}],"explanation":["장면 일의 자막이 다룰 내용을 알려 줘요.","장면 이에서 흙과 모래가 흘러가요.","갯벌이 어떻게 만들어지는지를 다뤄요."],"asset":{"type":"passage","lines":["장면 일 [화면] 물이 빠진 바닷가에 끝없는 흙벌판이 펼쳐진다.","[소리] 잔잔한 파도 소리와 낮은 음악. [자막] 갯벌은 어떻게 만들어질까","장면 이 [화면] 뿌연 강물을 따라 흙과 모래가 함께 흘러간다.","[말] 강물은 흙과 모래를 조금씩 싣고 바다로 흘러갑니다.","[자막] 강물이 실어 오는 것 · 고운 흙과 모래"],"title":"갯벌 영상 (장면 일~이)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#4','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C11',1,'ox','auto','장면 일에서는 자막으로 영상의 제목을 보여 주었어요.',ARRAY['K6-2-u5-X14']::text[],false,'{"seq":4,"concept":"K6-2-u5-C11","difficulty":1,"kind":"ox","stem":"장면 일에서는 자막으로 영상의 제목을 보여 주었어요.","answer":"O","reason_options":[{"t":"무엇을 다룰 영상인지 먼저 알리려고 썼기 때문에","correct":true},{"t":"자막은 아무 장면에나 넣는 것이기 때문에","mis":"K6-2-u5-X14"}],"mis":"K6-2-u5-X14","explanation":["장면 일의 자막은 「갯벌은 어떻게 만들어질까」예요.","무엇을 다룰지 먼저 알려 줘요.","장면마다 할 일이 있어요."],"asset":{"type":"passage","lines":["장면 일 [화면] 물이 빠진 바닷가에 끝없는 흙벌판이 펼쳐진다.","[소리] 잔잔한 파도 소리와 낮은 음악. [자막] 갯벌은 어떻게 만들어질까","장면 이 [화면] 뿌연 강물을 따라 흙과 모래가 함께 흘러간다.","[말] 강물은 흙과 모래를 조금씩 싣고 바다로 흘러갑니다.","[자막] 강물이 실어 오는 것 · 고운 흙과 모래"],"title":"갯벌 영상 (장면 일~이)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#5','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C13',2,'mc','auto','갯벌은 어떻게 만들어지나요?',ARRAY['K6-2-u5-X17','K6-2-u5-X18']::text[],false,'{"seq":5,"concept":"K6-2-u5-C13","difficulty":2,"kind":"mc","stem":"갯벌은 어떻게 만들어지나요?","options":[{"t":"강과 바다가 실어 온 고운 흙과 모래가 얕은 바닥에 오래 쌓여서","correct":true},{"t":"바다 밑에서 뜨거운 것이 솟아올라 굳어서","mis":"K6-2-u5-X17"},{"t":"바닷물이 얼었다 녹으면서 땅이 갈라져서","mis":"K6-2-u5-X17"},{"t":"밀물 때 물에 잠긴 땅이 깎여 나가서","mis":"K6-2-u5-X18"}],"explanation":["장면 이에서 흙과 모래가 흘러가요.","장면 삼에서 물살이 느린 곳에 쌓여요.","아주 오랜 시간이 걸려요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#6','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C11',2,'mc','auto','장면 사에서 음악이 밝고 빨라진 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X14','K6-2-u5-X12']::text[],false,'{"seq":6,"concept":"K6-2-u5-C11","difficulty":2,"kind":"mc","stem":"장면 사에서 음악이 밝고 빨라진 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"생물이 사는 곳이라는 느낌을 살리려고","correct":true},{"t":"영상이 곧 끝난다는 것을 알리려고","mis":"K6-2-u5-X14"},{"t":"낯선 낱말을 정확하게 남기려고","mis":"K6-2-u5-X12"},{"t":"아무 까닭 없이 바꾼 것이다","mis":"K6-2-u5-X14"}],"explanation":["게와 조개가 움직이는 장면이에요.","느낌을 바꿀 때 음악의 빠르기를 바꿔요.","낱말을 남기는 것은 말과 자막이 해요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#7','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C11',2,'match','auto','장면과 그 방법을 쓴 까닭을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C11","difficulty":2,"kind":"match","stem":"장면과 그 방법을 쓴 까닭을 이으세요.","pairs":[{"l":"장면 일 — 자막으로 제목","r":"무엇을 다룰 영상인지 먼저 알리려고"},{"l":"장면 삼 — 말과 자막을 함께","r":"낯선 낱말을 정확하게 남기려고"},{"l":"장면 사 — 음악이 밝고 빨라짐","r":"생물이 사는 곳이라는 느낌을 살리려고"}],"mis":"K6-2-u5-X14","explanation":["제목은 처음에 알려요.","퇴적 같은 낱말은 말과 자막으로 남겨요.","느낌은 음악으로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#8','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C12',2,'mc','auto','감상을 말한 것 가운데 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X15','K6-2-u5-X16']::text[],false,'{"seq":8,"concept":"K6-2-u5-C12","difficulty":2,"kind":"mc","stem":"감상을 말한 것 가운데 알맞은 것은 어느 것인가요?","options":[{"t":"장면 삼에서 말과 자막을 함께 써서 「퇴적」이라는 낱말이 잘 남았다","correct":true},{"t":"그냥 다 좋았다. 재미있었다","mis":"K6-2-u5-X15"},{"t":"별로였다","mis":"K6-2-u5-X15"},{"t":"자막을 좋아하지 않는 사람은 이 영상을 잘못 본 것이다","mis":"K6-2-u5-X16"}],"explanation":["느낌만 말하면 까닭이 없어요.","느낌이 다르다고 잘못 본 것은 아니에요.","어떤 표현 때문인지 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#9','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C12',2,'ox','auto','어느 장면이 가장 인상 깊었는지는 사람마다 다를 수 있어요.',ARRAY['K6-2-u5-X16']::text[],false,'{"seq":9,"concept":"K6-2-u5-C12","difficulty":2,"kind":"ox","stem":"어느 장면이 가장 인상 깊었는지는 사람마다 다를 수 있어요.","answer":"O","reason_options":[{"t":"느낌은 사람마다 달라도 괜찮기 때문에","correct":true},{"t":"느낌은 정답이 하나뿐이기 때문에","mis":"K6-2-u5-X16"}],"mis":"K6-2-u5-X16","explanation":["인상 깊은 장면은 사람마다 달라요.","그 장면에 무엇이 쓰였는지는 함께 확인할 수 있어요.","느낌과 까닭을 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#10','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C12',3,'error','auto','영상 감상의 세 걸음을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X05','K6-2-u5-X15']::text[],false,'{"seq":10,"concept":"K6-2-u5-C12","difficulty":3,"kind":"error","stem":"영상 감상의 세 걸음을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시후 — 「세 번째 걸음은 영상을 만든 사람의 이름을 찾는 거야.」","correct":true,"mis_target":"K6-2-u5-X05"},{"t":"나래 — 「먼저 장면에 말 · 글 · 그림 · 소리 가운데 무엇이 쓰였는지 찾아.」","mis":"K6-2-u5-X15"},{"t":"윤호 — 「그것이 이해를 무엇으로 돕는지 이어 보는 거야.」","mis":"K6-2-u5-X15"}],"explanation":["세 걸음은 찾기 · 잇기 · 말하기예요.","나래와 윤호는 바르게 말했어요.","마지막은 느낀 것과 까닭을 말하는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#1','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C13',2,'mc','auto','밀물 때 물에 잠기고 썰물 때 드러나는 넓고 평평한 바닷가 땅은 무엇인가요?',ARRAY['K6-2-u5-X18']::text[],false,'{"seq":1,"concept":"K6-2-u5-C13","difficulty":2,"kind":"mc","stem":"밀물 때 물에 잠기고 썰물 때 드러나는 넓고 평평한 바닷가 땅은 무엇인가요?","options":[{"t":"갯벌","correct":true},{"t":"모래섬","mis":"K6-2-u5-X18"},{"t":"강어귀","mis":"K6-2-u5-X18"},{"t":"여울","mis":"K6-2-u5-X18"}],"explanation":["하루에 두 번쯤 드러났다 잠겨요.","게 · 조개 · 갯지렁이가 살아요.","이 땅이 갯벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#2','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C13',2,'ox','auto','갯벌은 뭍에서 흘러든 물을 걸러 주기도 해요.',ARRAY['K6-2-u5-X17']::text[],false,'{"seq":2,"concept":"K6-2-u5-C13","difficulty":2,"kind":"ox","stem":"갯벌은 뭍에서 흘러든 물을 걸러 주기도 해요.","answer":"O","reason_options":[{"t":"장면 오의 말과 자막에서 확인할 수 있기 때문에","correct":true},{"t":"영상에 나오지 않았지만 그럴 것 같기 때문에","mis":"K6-2-u5-X17"}],"mis":"K6-2-u5-X17","explanation":["장면 오에서 해설하는 말이 있어요.","자막에도 「물을 걸러 주는 곳」이 있어요.","영상 안에서 확인한 내용이에요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#3','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C11',3,'mc','auto','장면 삼에서 「퇴적」을 말로 하고 자막으로도 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X14','K6-2-u5-X12','K6-2-u5-X13']::text[],false,'{"seq":3,"concept":"K6-2-u5-C11","difficulty":3,"kind":"mc","stem":"장면 삼에서 「퇴적」을 말로 하고 자막으로도 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"처음 듣는 낱말을 정확하게 남기려고","correct":true},{"t":"영상을 길게 만들려고","mis":"K6-2-u5-X14"},{"t":"생물이 사는 곳이라는 느낌을 살리려고","mis":"K6-2-u5-X12"},{"t":"자막이 많을수록 좋은 영상이라서","mis":"K6-2-u5-X13"}],"explanation":["퇴적은 낯선 낱말이에요.","말로만 하면 지나가 버려요.","자막으로 붙들어 정확히 남겨요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#4','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C12',3,'mc','auto','갈릴 수 있는 것과 함께 확인할 수 있는 것을 바르게 나눈 것은 어느 것인가요?',ARRAY['K6-2-u5-X16']::text[],false,'{"seq":4,"concept":"K6-2-u5-C12","difficulty":3,"kind":"mc","stem":"갈릴 수 있는 것과 함께 확인할 수 있는 것을 바르게 나눈 것은 어느 것인가요?","options":[{"t":"갈릴 수 있는 것 — 음악이 잘 어울렸는가 / 함께 확인할 수 있는 것 — 그 장면에 무엇이 쓰였는가","correct":true},{"t":"갈릴 수 있는 것 — 장면 삼에 자막이 있는가 / 함께 확인할 수 있는 것 — 가장 인상 깊은 장면","mis":"K6-2-u5-X16"},{"t":"모두 사람마다 다르니 확인할 수 있는 것은 없다","mis":"K6-2-u5-X16"},{"t":"모두 정답이 하나이니 느낌도 하나여야 한다","mis":"K6-2-u5-X16"}],"explanation":["어울렸는지는 느낌이라 갈려요.","무엇이 쓰였는지는 영상에서 찾을 수 있어요.","둘을 갈라 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#5','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C8',3,'mc','auto','이 영상이 내용을 전한 방법이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X05']::text[],false,'{"seq":5,"concept":"K6-2-u5-C8","difficulty":3,"kind":"mc","stem":"이 영상이 내용을 전한 방법이 아닌 것은 어느 것인가요?","options":[{"t":"영상을 본 사람의 수","correct":true},{"t":"해설하는 사람의 말","mis":"K6-2-u5-X05"},{"t":"보여 주는 장면과 화면의 움직임","mis":"K6-2-u5-X05"},{"t":"배경 음악의 빠르기 바꾸기","mis":"K6-2-u5-X05"}],"explanation":["말 · 장면 · 음악은 영상 안에서 뜻을 날라요.","본 사람의 수는 영상 밖의 정보예요.","표시가 있는 것만 찾아요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#6','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C13',3,'error','auto','갯벌 영상의 내용을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X18','K6-2-u5-X17']::text[],false,'{"seq":6,"concept":"K6-2-u5-C13","difficulty":3,"kind":"error","stem":"갯벌 영상의 내용을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「썰물은 바닷물이 뭍 쪽으로 밀려 들어오는 거야.」","correct":true,"mis_target":"K6-2-u5-X18"},{"t":"채아 — 「물살이 느려지는 얕은 바닥에 고운 흙이 쌓여.」","mis":"K6-2-u5-X17"},{"t":"도하 — 「갯벌은 하루에 두 번쯤 드러났다 잠겨.」","mis":"K6-2-u5-X17"}],"explanation":["채아와 도하는 영상 내용을 바르게 말했어요.","밀려 들어오는 것은 밀물이에요.","썰물은 빠져나가는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#7','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C12',3,'mc','auto','다른 교과 시간에 본 영상으로 세 걸음 감상을 했어요. 차례가 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X15','K6-2-u5-X05','K6-2-u5-X16']::text[],false,'{"seq":7,"concept":"K6-2-u5-C12","difficulty":3,"kind":"mc","stem":"다른 교과 시간에 본 영상으로 세 걸음 감상을 했어요. 차례가 알맞은 것은 어느 것인가요?","options":[{"t":"자막과 그래프를 찾기 → 그래프가 수의 변화를 한눈에 보여 준다고 잇기 → 그래서 이해가 쉬웠다고 까닭과 함께 말하기","correct":true},{"t":"재미있었다고 말하기 → 끝","mis":"K6-2-u5-X15"},{"t":"영상 길이 재기 → 본 사람 수 세기 → 말하기","mis":"K6-2-u5-X05"},{"t":"느낌이 나와 다른 친구 찾기 → 고쳐 주기","mis":"K6-2-u5-X16"}],"explanation":["찾기 · 잇기 · 말하기 차례예요.","영상 밖의 정보는 찾지 않아요.","느낌에는 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#8','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C11',4,'mc','auto','갯벌 영상의 다섯 장면에 대한 평가로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X14','K6-2-u5-X12','K6-2-u5-X13']::text[],false,'{"seq":8,"concept":"K6-2-u5-C11","difficulty":4,"kind":"mc","stem":"갯벌 영상의 다섯 장면에 대한 평가로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장면마다 해야 할 일이 달라 제목에는 자막, 낯선 낱말에는 말과 자막, 생물이 사는 모습에는 밝은 음악을 골라 썼다","correct":true},{"t":"장면마다 방법이 달라 한 가지로 통일해야 한다","mis":"K6-2-u5-X14"},{"t":"음악이 바뀌는 것은 시청자를 헷갈리게 하니 빼야 한다","mis":"K6-2-u5-X12"},{"t":"자막이 많은 장면일수록 잘 만든 장면이다","mis":"K6-2-u5-X13"}],"explanation":["방법이 다른 데에는 까닭이 있어요.","장면에서 해야 할 일을 먼저 봐요.","그 일에 맞는 방법을 골랐어요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#9','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C12',4,'essay','teacher','갯벌 영상에서 한 장면을 골라 세 걸음(찾기 · 잇기 · 말하기)으로 감상한 내용을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C12","difficulty":4,"kind":"essay","stem":"갯벌 영상에서 한 장면을 골라 세 걸음(찾기 · 잇기 · 말하기)으로 감상한 내용을 쓰세요.","answer_guide":{"answer":"예: 찾기 — 장면 사에서는 게와 조개가 움직이는 장면, 밝고 빨라진 음악, 「게 · 조개 · 갯지렁이가 사는 곳」이라는 자막이 쓰였다. 잇기 — 음악은 생물이 살아 움직이는 느낌을 살리고, 자막은 어떤 생물이 사는지를 정확히 남겨 준다. 말하기 — 그래서 나는 갯벌이 그냥 흙벌판이 아니라 살아 있는 곳이라고 느꼈다. 밝아진 음악 때문에 그렇게 느꼈다.","scoring_points":["장면에 쓰인 요소를 찾았는가","요소가 이해를 무엇으로 돕는지 이었는가","느낌과 그 까닭을 표현 방법과 이어 말했는가"]},"explanation":["무엇이 쓰였나 찾아요.","무엇을 돕나 이어요.","느낌과 까닭을 함께 말해요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#10','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C13',4,'essay','teacher','갯벌이 만들어지는 과정을 장면 차례에 따라 쓰고, 「밀물」 · 「썰물」 · 「퇴적」 가운데 두 낱말을 넣어 갯벌을 소개하는 문장을 쓰세요. 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C13","difficulty":4,"kind":"essay","stem":"갯벌이 만들어지는 과정을 장면 차례에 따라 쓰고, 「밀물」 · 「썰물」 · 「퇴적」 가운데 두 낱말을 넣어 갯벌을 소개하는 문장을 쓰세요. 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 강물이 흙과 모래를 싣고 바다로 흘러가고, 밀물과 썰물의 차가 큰 얕은 바닷가에서 물살이 느려지면 고운 흙이 가라앉아 아주 오랫동안 쌓여 갯벌이 된다. 문장 — 갯벌은 고운 흙의 퇴적으로 만들어진 땅으로, 썰물 때 드러나면 게와 조개가 나와 움직인다.","scoring_points":["흘러감 → 느려짐 → 쌓임의 차례를 썼는가","두 낱말을 뜻에 맞게 넣었는가","숫자 없이 썼는가"]},"explanation":["장면 차례를 이어요.","낱말 뜻을 정확히 알아요.","영상에서 확인한 것으로 써요."],"asset":{"type":"passage","lines":["장면 일 [화면] 물이 빠진 바닷가에 끝없는 흙벌판이 펼쳐진다.","[소리] 잔잔한 파도 소리와 낮은 음악. [자막] 갯벌은 어떻게 만들어질까","장면 이 [화면] 뿌연 강물을 따라 흙과 모래가 함께 흘러간다.","[말] 강물은 흙과 모래를 조금씩 싣고 바다로 흘러갑니다.","[자막] 강물이 실어 오는 것 · 고운 흙과 모래"],"title":"갯벌 영상 (장면 일~이)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#1','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C14',1,'mc','auto','독자를 고려한다는 것은 어떤 뜻인가요?',ARRAY['K6-2-u5-X20','K6-2-u5-X25']::text[],false,'{"seq":1,"concept":"K6-2-u5-C14","difficulty":1,"kind":"mc","stem":"독자를 고려한다는 것은 어떤 뜻인가요?","options":[{"t":"읽는 사람의 처지에서 헤아려 보는 것","correct":true},{"t":"독자가 좋아할 내용만 고르는 것","mis":"K6-2-u5-X20"},{"t":"어려운 이야기는 모두 빼 버리는 것","mis":"K6-2-u5-X20"},{"t":"글쓴이가 쓰고 싶은 대로 쓰는 것","mis":"K6-2-u5-X25"}],"explanation":["비위를 맞추는 것과는 달라요.","내 마음대로 쓰는 것도 아니에요.","읽는 사람의 처지에서 헤아려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#2','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C16',1,'mc','auto','글을 쓰는 세 단계 가운데 가장 먼저 하는 것은 어느 것인가요?',ARRAY['K6-2-u5-X21','K6-2-u5-X22']::text[],false,'{"seq":2,"concept":"K6-2-u5-C16","difficulty":1,"kind":"mc","stem":"글을 쓰는 세 단계 가운데 가장 먼저 하는 것은 어느 것인가요?","options":[{"t":"계획 세우기","correct":true},{"t":"글 쓰고 고쳐 쓰기","mis":"K6-2-u5-X21"},{"t":"내용 생성하고 조직하기","mis":"K6-2-u5-X21"},{"t":"제목 꾸미기","mis":"K6-2-u5-X22"}],"explanation":["먼저 누가 읽을지, 무엇을 왜 쓸지 정해요.","그다음 쓸 거리를 모아 차례를 짜요.","마지막에 쓰고 고쳐 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#3','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C17',1,'ox','auto','글에 자료를 많이 넣을수록 좋은 글이 돼요.',ARRAY['K6-2-u5-X23']::text[],false,'{"seq":3,"concept":"K6-2-u5-C17","difficulty":1,"kind":"ox","stem":"글에 자료를 많이 넣을수록 좋은 글이 돼요.","answer":"X","reason_options":[{"t":"자료는 독자의 이해를 도울 때 넣는 것이기 때문에","correct":true},{"t":"자료가 많으면 글을 덜 써도 되기 때문에","mis":"K6-2-u5-X23"}],"mis":"K6-2-u5-X23","explanation":["자료는 개수를 채우는 것이 아니에요.","글만으로 어려운 곳을 도와요.","글과 이어지는 자료만 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#4','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C14',1,'mc','auto','두 친구가 세인이의 첫 글을 어려워한 까닭은 무엇인가요?',ARRAY['K6-2-u5-X22']::text[],false,'{"seq":4,"concept":"K6-2-u5-C14","difficulty":1,"kind":"mc","stem":"두 친구가 세인이의 첫 글을 어려워한 까닭은 무엇인가요?","options":[{"t":"낱말이 어렵고, 읽는 사람이 무엇을 하면 되는지 없어서","correct":true},{"t":"글의 길이가 너무 짧아서","mis":"K6-2-u5-X22"},{"t":"글씨 색깔이 알록달록해서","mis":"K6-2-u5-X22"},{"t":"제목이 없어서","mis":"K6-2-u5-X22"}],"explanation":["「적치」 같은 낱말을 몰랐어요.","우리가 무엇을 하면 되는지도 없었어요.","독자를 생각하지 않은 글이에요."],"asset":{"type":"passage","lines":["우산 보관 실태와 개선 방안","본교 현관의 우산 보관 시설은 수용 능력이 부족한 실정이다.","강우 시 우산의 무질서한 적치로 인해 통행에 지장이 초래되며,","이는 낙상의 위험을 증대시킨다.","이에 보관 방식의 전면적 재검토가 요구된다."],"title":"세인이가 처음 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#5','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C14',2,'mc','auto','세인이가 다시 쓴 글에서 달라진 점이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X19','K6-2-u5-X25','K6-2-u5-X23']::text[],false,'{"seq":5,"concept":"K6-2-u5-C14","difficulty":2,"kind":"mc","stem":"세인이가 다시 쓴 글에서 달라진 점이 아닌 것은 어느 것인가요?","options":[{"t":"글쓴이의 이름을 크게 적었다","correct":true},{"t":"읽는 사람이 아는 쉬운 낱말로 바꾸었다","mis":"K6-2-u5-X19"},{"t":"할 일을 기호로 나누어 보여 주었다","mis":"K6-2-u5-X25"},{"t":"직접 세어 본 자료를 넣었다","mis":"K6-2-u5-X23"}],"explanation":["쉬운 낱말 · 할 일 · 세어 본 자료가 새로 생겼어요.","이름을 크게 적은 곳은 없어요.","모두 독자를 생각한 고침이에요."],"asset":{"type":"passage","lines":["비 오는 날, 우산은 어디에 둘까","비가 오는 날 현관이 복잡합니다. 우산을 아무 데나 세워 두면","물이 고여 미끄럽고, 지나가다 걸려 넘어질 수도 있습니다.","이렇게 해 주세요 · 우산은 접어서 보관대에 꽂아 주세요.","· 보관대가 다 찼으면 현관 왼쪽 벽에 나란히 세워 주세요.","· 집에 갈 때 내 우산인지 확인하고 가져가세요.","우리 반에서 세어 보니 지난 비 오는 날 남은 우산이 여섯 자루였습니다."],"title":"세인이가 독자를 생각하며 다시 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#6','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C16',2,'match','auto','단계와 그 단계에서 하는 일을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u5-C16","difficulty":2,"kind":"match","stem":"단계와 그 단계에서 하는 일을 이으세요.","pairs":[{"l":"계획 세우기","r":"읽을 사람이 누구인지 알아봅니다"},{"l":"내용 생성하고 조직하기","r":"쓸 거리를 모아 차례를 짭니다"},{"l":"글 쓰고 고쳐 쓰기","r":"오해할 곳이 없는지 다시 읽습니다"}],"mis":"K6-2-u5-X21","explanation":["쓰기 전에는 독자를 알아봐요.","쓰는 중에는 쓸 거리와 차례를 짜요.","쓴 뒤에는 오해할 곳을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#7','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C17',2,'mc','auto','수를 견주어 보여 줄 때 넣으면 좋은 자료는 어느 것인가요?',ARRAY['K6-2-u5-X23','K6-2-u5-X13']::text[],false,'{"seq":7,"concept":"K6-2-u5-C17","difficulty":2,"kind":"mc","stem":"수를 견주어 보여 줄 때 넣으면 좋은 자료는 어느 것인가요?","options":[{"t":"표나 그래프","correct":true},{"t":"사진이나 그림","mis":"K6-2-u5-X23"},{"t":"기호와 줄 나눔","mis":"K6-2-u5-X23"},{"t":"화려한 꾸밈 그림","mis":"K6-2-u5-X13"}],"explanation":["모습이나 차례는 사진이나 그림이 좋아요.","할 일은 기호와 줄 나눔이 좋아요.","수를 견줄 때는 표나 그래프예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#8','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C15',2,'ox','auto','독자를 고려한다는 것은 독자가 좋아할 이야기만 골라 쓰는 거예요.',ARRAY['K6-2-u5-X20']::text[],false,'{"seq":8,"concept":"K6-2-u5-C15","difficulty":2,"kind":"ox","stem":"독자를 고려한다는 것은 독자가 좋아할 이야기만 골라 쓰는 거예요.","answer":"X","reason_options":[{"t":"전하려는 것은 그대로 두고 독자가 알아들을 수 있게 짜는 것이기 때문에","correct":true},{"t":"독자의 마음을 기쁘게 하는 것이 글의 목적이기 때문에","mis":"K6-2-u5-X20"}],"mis":"K6-2-u5-X20","explanation":["좋아할 것만 고르면 전하려는 것이 사라져요.","전하려는 것은 그대로 둬요.","닿는 방법을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#9','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C14',2,'mc','auto','독자를 고려할 때 살피는 네 가지에 들지 않는 것은 어느 것인가요?',ARRAY['K6-2-u5-X19']::text[],false,'{"seq":9,"concept":"K6-2-u5-C14","difficulty":2,"kind":"mc","stem":"독자를 고려할 때 살피는 네 가지에 들지 않는 것은 어느 것인가요?","options":[{"t":"글쓴이가 좋아하는 낱말","correct":true},{"t":"독자의 흥미","mis":"K6-2-u5-X19"},{"t":"독자의 배경지식","mis":"K6-2-u5-X19"},{"t":"독자가 글을 읽는 매체","mis":"K6-2-u5-X19"}],"explanation":["흥미 · 배경지식 · 수준 · 매체를 살펴요.","모두 독자에 관한 것이에요.","글쓴이의 취향은 들지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#10','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C16',3,'error','auto','고쳐 쓸 때 볼 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X22']::text[],false,'{"seq":10,"concept":"K6-2-u5-C16","difficulty":3,"kind":"error","stem":"고쳐 쓸 때 볼 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"아린 — 「글씨가 예쁜지, 줄이 반듯한지부터 봐야 해.」","correct":true,"mis_target":"K6-2-u5-X22"},{"t":"태민 — 「독자가 오해할 만한 표현이 없는지 봐.」","mis":"K6-2-u5-X22"},{"t":"세아 — 「독자의 수준에 맞는 낱말인지 봐.」","mis":"K6-2-u5-X22"}],"explanation":["태민과 세아는 바르게 말했어요.","고쳐 쓰기는 겉모습을 다듬는 일이 아니에요.","독자에게 더 잘 닿게 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#1','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C16',2,'mc','auto','글을 쓸 때 독자는 언제 떠올려야 하나요?',ARRAY['K6-2-u5-X21']::text[],false,'{"seq":1,"concept":"K6-2-u5-C16","difficulty":2,"kind":"mc","stem":"글을 쓸 때 독자는 언제 떠올려야 하나요?","options":[{"t":"계획 · 내용 조직 · 쓰고 고치기의 세 단계마다","correct":true},{"t":"계획을 세울 때 한 번만","mis":"K6-2-u5-X21"},{"t":"글을 다 쓴 뒤에만","mis":"K6-2-u5-X21"},{"t":"제목을 정할 때만","mis":"K6-2-u5-X21"}],"explanation":["독자는 처음에만 떠올리는 것이 아니에요.","단계마다 다시 떠올려요.","그래야 끝까지 독자에게 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#2','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C17',2,'sa','auto','세인이는 다시 쓴 글에서 할 일을 무엇으로 나누어 보여 주었나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C17","difficulty":2,"kind":"sa","stem":"세인이는 다시 쓴 글에서 할 일을 무엇으로 나누어 보여 주었나요? 두 글자로 쓰세요.","answer":["기호"],"explanation":["「·」를 앞에 붙였어요.","할 일이 하나씩 나뉘어 보여요.","할 일을 보여 줄 때는 기호와 줄 나눔이 좋아요."],"asset":{"type":"passage","lines":["비 오는 날, 우산은 어디에 둘까","비가 오는 날 현관이 복잡합니다. 우산을 아무 데나 세워 두면","물이 고여 미끄럽고, 지나가다 걸려 넘어질 수도 있습니다.","이렇게 해 주세요 · 우산은 접어서 보관대에 꽂아 주세요.","· 보관대가 다 찼으면 현관 왼쪽 벽에 나란히 세워 주세요.","· 집에 갈 때 내 우산인지 확인하고 가져가세요.","우리 반에서 세어 보니 지난 비 오는 날 남은 우산이 여섯 자루였습니다."],"title":"세인이가 독자를 생각하며 다시 쓴 글"},"mis":"K6-2-u5-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#3','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C15',3,'mc','auto','독자를 고려해 글을 쓴 사람은 어떻게 했을까요?',ARRAY['K6-2-u5-X20','K6-2-u5-X19']::text[],false,'{"seq":3,"concept":"K6-2-u5-C15","difficulty":3,"kind":"mc","stem":"독자를 고려해 글을 쓴 사람은 어떻게 했을까요?","options":[{"t":"전하려는 내용은 그대로 두고 독자가 알아들을 수 있게 썼다","correct":true},{"t":"어려워 보이는 내용은 모두 덜어 냈다","mis":"K6-2-u5-X20"},{"t":"독자가 좋아할 만한 이야기만 골라서 썼다","mis":"K6-2-u5-X20"},{"t":"낱말만 쉽게 바꾸고 차례는 그대로 두었다","mis":"K6-2-u5-X19"}],"explanation":["덜어 내거나 골라 쓰면 비위 맞추기예요.","낱말만 바꾸면 할 일이 여전히 안 보일 수 있어요.","전하려는 것은 두고 닿는 방법을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#4','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C24',3,'mc','auto','세인이의 첫 글 「우산의 무질서한 적치로 통행에 지장이 초래된다」를 독자를 생각해 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X24','K6-2-u5-X25','K6-2-u5-X22']::text[],false,'{"seq":4,"concept":"K6-2-u5-C24","difficulty":3,"kind":"mc","stem":"세인이의 첫 글 「우산의 무질서한 적치로 통행에 지장이 초래된다」를 독자를 생각해 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우산을 아무 데나 세워 두면 지나가다 걸려 넘어질 수 있습니다. 접어서 보관대에 꽂아 주세요.","correct":true},{"t":"우산의 무질서한 적치는 심각한 문제이다.","mis":"K6-2-u5-X24"},{"t":"우산 문제가 있다.","mis":"K6-2-u5-X25"},{"t":"우산을 정리하자! 정리하자! 정리하자!","mis":"K6-2-u5-X22"}],"explanation":["어려운 낱말을 그대로 두면 안 돼요.","까닭도 할 일도 없으면 독자가 움직이지 않아요.","까닭과 할 일이 함께 보이게 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#5','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C17',3,'mc','auto','세인이가 다시 쓴 글에 「지난 비 오는 날 남은 우산이 여섯 자루」를 넣은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X23','K6-2-u5-X13']::text[],false,'{"seq":5,"concept":"K6-2-u5-C17","difficulty":3,"kind":"mc","stem":"세인이가 다시 쓴 글에 「지난 비 오는 날 남은 우산이 여섯 자루」를 넣은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"현관이 복잡하다는 것을 직접 세어 본 사실로 보여 주려고","correct":true},{"t":"글을 길게 만들려고","mis":"K6-2-u5-X23"},{"t":"숫자를 넣으면 무조건 좋은 글이라서","mis":"K6-2-u5-X13"},{"t":"우산 주인을 찾으려고","mis":"K6-2-u5-X23"}],"explanation":["글에서 말한 현관 문제와 이어진 자료예요.","직접 세어 본 것이라 믿을 수 있어요.","자료는 이해를 돕는 데 써요."],"asset":{"type":"passage","lines":["비 오는 날, 우산은 어디에 둘까","비가 오는 날 현관이 복잡합니다. 우산을 아무 데나 세워 두면","물이 고여 미끄럽고, 지나가다 걸려 넘어질 수도 있습니다.","이렇게 해 주세요 · 우산은 접어서 보관대에 꽂아 주세요.","· 보관대가 다 찼으면 현관 왼쪽 벽에 나란히 세워 주세요.","· 집에 갈 때 내 우산인지 확인하고 가져가세요.","우리 반에서 세어 보니 지난 비 오는 날 남은 우산이 여섯 자루였습니다."],"title":"세인이가 독자를 생각하며 다시 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#6','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C14',3,'match','auto','독자를 고려할 때 살피는 것과 묻는 말을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u5-C14","difficulty":3,"kind":"match","stem":"독자를 고려할 때 살피는 것과 묻는 말을 이으세요.","pairs":[{"l":"흥미","r":"무엇에 관심이 있는가"},{"l":"배경지식","r":"이 주제를 이미 얼마나 아는가"},{"l":"수준","r":"어떤 낱말을 알아들을 수 있는가"},{"l":"매체","r":"어디에서 이 글을 읽게 되는가"}],"mis":"K6-2-u5-X19","explanation":["흥미는 관심이에요.","배경지식은 이미 아는 것이에요.","수준은 낱말, 매체는 읽는 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#7','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C15',3,'error','auto','「독자를 고려한 글」에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X20','K6-2-u5-X19','K6-2-u5-X25']::text[],false,'{"seq":7,"concept":"K6-2-u5-C15","difficulty":3,"kind":"error","stem":"「독자를 고려한 글」에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"준혁 — 「일학년이 읽을 글이면 어려운 내용은 다 빼고 재미있는 것만 쓰면 돼.」","correct":true,"mis_target":"K6-2-u5-X20"},{"t":"소이 — 「일학년이 읽을 글이면 같은 내용을 쉬운 낱말과 그림으로 풀어 써야 해.」","mis":"K6-2-u5-X19"},{"t":"하람 — 「일학년이 할 수 있는 일까지 보이게 써야 해.」","mis":"K6-2-u5-X25"}],"explanation":["소이와 하람은 전하려는 것을 두고 닿는 방법을 바꿨어요.","준혁은 내용을 덜어 냈어요.","독자 고려는 비위 맞추기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#8','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C16',4,'mc','auto','세인이의 두 글을 견주어 고쳐 쓰기를 평가한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X20','K6-2-u5-X21']::text[],false,'{"seq":8,"concept":"K6-2-u5-C16","difficulty":4,"kind":"mc","stem":"세인이의 두 글을 견주어 고쳐 쓰기를 평가한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전하려는 우산 문제는 그대로 두고, 쉬운 낱말 · 할 일 · 세어 본 자료로 독자에게 닿게 고쳤다","correct":true},{"t":"글이 길어졌으니 잘못 고쳤다","mis":"K6-2-u5-X22"},{"t":"어려운 낱말을 빼서 내용이 줄어들었다","mis":"K6-2-u5-X20"},{"t":"제목만 바꾸었으니 달라진 것이 없다","mis":"K6-2-u5-X21"}],"explanation":["길이는 기준이 아니에요.","내용은 줄지 않고 그대로예요.","독자에게 닿게 고친 것이 핵심이에요."],"asset":{"type":"passage","lines":["비 오는 날, 우산은 어디에 둘까","비가 오는 날 현관이 복잡합니다. 우산을 아무 데나 세워 두면","물이 고여 미끄럽고, 지나가다 걸려 넘어질 수도 있습니다.","이렇게 해 주세요 · 우산은 접어서 보관대에 꽂아 주세요.","· 보관대가 다 찼으면 현관 왼쪽 벽에 나란히 세워 주세요.","· 집에 갈 때 내 우산인지 확인하고 가져가세요.","우리 반에서 세어 보니 지난 비 오는 날 남은 우산이 여섯 자루였습니다."],"title":"세인이가 독자를 생각하며 다시 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#9','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C14',4,'essay','teacher','세인이의 첫 글과 다시 쓴 글을 견주어, 독자를 고려해 달라진 점을 세 가지 쓰고 각각 독자에게 어떤 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C14","difficulty":4,"kind":"essay","stem":"세인이의 첫 글과 다시 쓴 글을 견주어, 독자를 고려해 달라진 점을 세 가지 쓰고 각각 독자에게 어떤 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 첫째, 「적치 · 초래」 같은 어려운 낱말을 「아무 데나 세워 두면」처럼 쉬운 말로 바꾸어 같은 반 친구가 알아들을 수 있다. 둘째, 할 일을 기호로 나누어 보여 주어 무엇을 하면 되는지 바로 안다. 셋째, 직접 세어 본 우산 수를 넣어 현관이 복잡하다는 것을 믿을 수 있게 했다.","scoring_points":["달라진 점을 세 가지 찾았는가","각각이 독자에게 주는 도움을 썼는가","전하려는 내용은 그대로임을 알고 썼는가"]},"explanation":["낱말 · 할 일 · 자료를 봐요.","독자에게 무엇이 좋아졌는지 써요.","내용은 줄지 않았어요."],"asset":{"type":"passage","lines":["우산 보관 실태와 개선 방안","본교 현관의 우산 보관 시설은 수용 능력이 부족한 실정이다.","강우 시 우산의 무질서한 적치로 인해 통행에 지장이 초래되며,","이는 낙상의 위험을 증대시킨다.","이에 보관 방식의 전면적 재검토가 요구된다."],"title":"세인이가 처음 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#10','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C15',4,'essay','teacher','「독자를 고려하는 것은 비위를 맞추는 것이 아니다.」라는 말을 설명하고, 일학년 동생들에게 「복도에서 뛰지 않기」를 알리는 글을 쓸 때 어떻게 하면 좋을지 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C15","difficulty":4,"kind":"essay","stem":"「독자를 고려하는 것은 비위를 맞추는 것이 아니다.」라는 말을 설명하고, 일학년 동생들에게 「복도에서 뛰지 않기」를 알리는 글을 쓸 때 어떻게 하면 좋을지 두 가지 쓰세요.","answer_guide":{"answer":"예: 독자를 고려한다는 것은 독자가 좋아할 것만 고르거나 어려운 이야기를 빼는 것이 아니라, 전하려는 것은 그대로 두고 독자가 알아들을 수 있게 짜는 것이다. 첫째, 「충돌」 대신 「부딪쳐 다칠 수 있어요」처럼 동생들이 아는 말로 까닭을 쓴다. 둘째, 「복도에서는 오른쪽으로 천천히 걸어요」처럼 할 일을 그림과 함께 보여 준다.","scoring_points":["비위 맞추기와 다른 점을 설명했는가","독자 수준에 맞춘 방법을 썼는가","전하려는 내용을 줄이지 않고 할 일이 보이게 했는가"]},"explanation":["전하려는 것은 그대로.","알아듣게, 할 일이 보이게.","덜어 내기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#1','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C18',1,'mc','auto','기사문은 어떤 글인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27','K6-2-u5-X28']::text[],false,'{"seq":1,"concept":"K6-2-u5-C18","difficulty":1,"kind":"mc","stem":"기사문은 어떤 글인가요?","options":[{"t":"어떤 사실이나 사건을 여러 사람에게 알리는 글","correct":true},{"t":"글쓴이의 느낌을 솔직하게 쓰는 글","mis":"K6-2-u5-X26"},{"t":"있을 법한 일을 꾸며 쓰는 글","mis":"K6-2-u5-X27"},{"t":"한 사람에게 마음을 전하는 글","mis":"K6-2-u5-X28"}],"explanation":["느낌을 쓰는 글은 기사문이 아니에요.","꾸며 쓰면 안 돼요.","사실을 여러 사람에게 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#2','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C19',1,'mc','auto','기사의 주요 내용을 앞에서 요약해 주는 부분은 어느 것인가요?',ARRAY['K6-2-u5-X28']::text[],false,'{"seq":2,"concept":"K6-2-u5-C19","difficulty":1,"kind":"mc","stem":"기사의 주요 내용을 앞에서 요약해 주는 부분은 어느 것인가요?","options":[{"t":"전문","correct":true},{"t":"표제","mis":"K6-2-u5-X28"},{"t":"부제","mis":"K6-2-u5-X28"},{"t":"본문","mis":"K6-2-u5-X28"}],"explanation":["표제는 제목이에요.","부제는 표제를 보충해요.","전문이 주요 내용을 요약해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#3','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C19',1,'sa','auto','기사문의 제목에서 표제에 덧붙어 표제를 보충하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u5-C19","difficulty":1,"kind":"sa","stem":"기사문의 제목에서 표제에 덧붙어 표제를 보충하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["부제"],"explanation":["표제는 기사의 제목이에요.","부제는 필요할 때만 붙여요.","표제와 부제를 이어 읽으면 무슨 일인지 짐작돼요."],"mis":"K6-2-u5-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#4','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C20',1,'ox','auto','기사문에는 확인하지 못한 소문도 써도 돼요.',ARRAY['K6-2-u5-X27']::text[],false,'{"seq":4,"concept":"K6-2-u5-C20","difficulty":1,"kind":"ox","stem":"기사문에는 확인하지 못한 소문도 써도 돼요.","answer":"X","reason_options":[{"t":"읽는 사람이 사실이라고 믿고 읽는 글이기 때문에","correct":true},{"t":"많이 알릴수록 좋은 기사문이기 때문에","mis":"K6-2-u5-X27"}],"mis":"K6-2-u5-X27","explanation":["기사문은 사실이라고 믿고 읽어요.","확인하지 못한 것은 쓰지 않아요.","보고 듣고 세어 본 것만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#5','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C19',2,'match','auto','기사문의 부분과 하는 일을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C19","difficulty":2,"kind":"match","stem":"기사문의 부분과 하는 일을 이으세요.","pairs":[{"l":"표제","r":"기사 내용을 간결하게 드러냅니다"},{"l":"전문","r":"주요 내용을 앞에서 요약해 줍니다"},{"l":"본문","r":"주된 내용을 자세히 담습니다"}],"mis":"K6-2-u5-X28","explanation":["표제는 먼저 읽게 되는 제목이에요.","전문만 읽어도 무슨 일인지 알아요.","본문이 가장 길고 자세해요."],"asset":{"type":"passage","lines":["[표제] 점심시간 도서관, 이제 문이 열립니다","[부제] ― 도서 도우미 여덟 명이 당번을 나누어 맡아 ―","[전문] 우리 학교 도서관이 이번 달부터 점심시간에도 문을 연다.","육학년 도서 도우미 여덟 명이 요일별로 당번을 나누어 맡기로 하면서","가능해졌다."],"title":"본보기 기사문 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#6','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C19',2,'mc','auto','본보기 기사문의 전문에서 「누가」에 해당하는 것은 어느 것인가요?',ARRAY['K6-2-u5-X29']::text[],false,'{"seq":6,"concept":"K6-2-u5-C19","difficulty":2,"kind":"mc","stem":"본보기 기사문의 전문에서 「누가」에 해당하는 것은 어느 것인가요?","options":[{"t":"육학년 도서 도우미 여덟 명","correct":true},{"t":"우리 학교 도서관","mis":"K6-2-u5-X29"},{"t":"이번 달부터","mis":"K6-2-u5-X29"},{"t":"요일별로 당번을 나누어","mis":"K6-2-u5-X29"}],"explanation":["「도서관」은 어디에서예요.","「이번 달부터」는 언제예요.","「당번을 나누어」는 어떻게예요."],"asset":{"type":"passage","lines":["[표제] 점심시간 도서관, 이제 문이 열립니다","[부제] ― 도서 도우미 여덟 명이 당번을 나누어 맡아 ―","[전문] 우리 학교 도서관이 이번 달부터 점심시간에도 문을 연다.","육학년 도서 도우미 여덟 명이 요일별로 당번을 나누어 맡기로 하면서","가능해졌다."],"title":"본보기 기사문 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#7','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C20',2,'mc','auto','본보기 기사문에서 기자단이 직접 확인한 사실은 어느 것인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27']::text[],false,'{"seq":7,"concept":"K6-2-u5-C20","difficulty":2,"kind":"mc","stem":"본보기 기사문에서 기자단이 직접 확인한 사실은 어느 것인가요?","options":[{"t":"문을 연 첫 사흘 동안 온 사람 수","correct":true},{"t":"학생들이 모두 기뻐했다는 것","mis":"K6-2-u5-X26"},{"t":"다른 학교도 곧 따라 할 것이라는 이야기","mis":"K6-2-u5-X27"},{"t":"도서관이 학교에서 가장 큰 변화라는 것","mis":"K6-2-u5-X26"}],"explanation":["기쁨과 가장 큰 변화는 생각이에요.","다른 학교 이야기는 확인하지 못했어요.","사람 수는 직접 세어 본 사실이에요."],"asset":{"type":"passage","lines":["[본문] 그동안 도서관은 아침 시간과 방과 후에만 열려 있었다.","지난주 도서 도우미들이 모여 날마다 두 명씩 맡기로 당번을 정했다.","기자단이 문을 연 첫 사흘 동안 온 사람 수를 세어 보았다.","첫날은 열두 명, 둘째 날은 열아홉 명, 셋째 날은 스물여섯 명이었다.","하언 학생은 「쉬는 시간이 짧아 못 오던 친구들이 많이 온다」라고 말했다.","도우미들은 다음 달부터 새 책 알림 게시판도 만들 계획이라고 밝혔다."],"title":"본보기 기사문 (본문)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#8','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C21',2,'mc','auto','우리 학교 신문에 실을 기삿거리로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X30','K6-2-u5-X27']::text[],false,'{"seq":8,"concept":"K6-2-u5-C21","difficulty":2,"kind":"mc","stem":"우리 학교 신문에 실을 기삿거리로 알맞은 것은 어느 것인가요?","options":[{"t":"이번 학기부터 달라진 급식실 줄 서기 방법","correct":true},{"t":"먼 나라에서 일어났다는 확인하지 못한 이야기","mis":"K6-2-u5-X30"},{"t":"내가 어제 꾼 꿈과 그때 든 생각","mis":"K6-2-u5-X30"},{"t":"누구도 가서 볼 수 없는 소문","mis":"K6-2-u5-X27"}],"explanation":["독자인 우리 학교 학생이 관심을 가질 일이에요.","내가 직접 가서 확인할 수 있어요.","그래서 알맞은 기삿거리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#9','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C21',2,'ox','auto','기사문에 사진이나 표를 넣을 때에는 출처를 밝혀야 해요.',ARRAY['K6-2-u5-X32']::text[],false,'{"seq":9,"concept":"K6-2-u5-C21","difficulty":2,"kind":"ox","stem":"기사문에 사진이나 표를 넣을 때에는 출처를 밝혀야 해요.","answer":"O","reason_options":[{"t":"어디에서 얻은 자료인지 알아야 읽는 사람이 믿을 수 있기 때문에","correct":true},{"t":"자료는 많을수록 좋은 기사문이 되기 때문에","mis":"K6-2-u5-X32"}],"mis":"K6-2-u5-X32","explanation":["자료는 이해를 높여 줘요.","출처가 있어야 믿을 수 있어요.","내가 조사했으면 언제 누구에게 어떻게 했는지 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#10','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C20',3,'error','auto','기사문 문장을 썼어요. 확인할 수 없는 생각을 사실처럼 쓴 친구는 누구인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27']::text[],false,'{"seq":10,"concept":"K6-2-u5-C20","difficulty":3,"kind":"error","stem":"기사문 문장을 썼어요. 확인할 수 없는 생각을 사실처럼 쓴 친구는 누구인가요?","options":[{"t":"지율 — 「점심시간 도서관이 열리자 학생들은 모두 기뻐했다.」","correct":true,"mis_target":"K6-2-u5-X26"},{"t":"로아 — 「첫날 점심시간에 도서관에 온 사람은 열두 명이었다.」","mis":"K6-2-u5-X27"},{"t":"민재 — 「한 학생은 ‘점심때 많이 온다’라고 말했다.」","mis":"K6-2-u5-X27"}],"explanation":["로아는 세어 본 수를 썼어요.","민재는 들은 말을 그대로 옮겼어요.","「모두 기뻐했다」는 쓴 사람의 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#1','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C19',2,'mc','auto','본보기 기사문의 전문에서 「왜」에 해당하는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X29']::text[],false,'{"seq":1,"concept":"K6-2-u5-C19","difficulty":2,"kind":"mc","stem":"본보기 기사문의 전문에서 「왜」에 해당하는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"점심시간에도 책을 빌릴 수 있게 하려고","correct":true},{"t":"요일별로 당번을 나누어","mis":"K6-2-u5-X29"},{"t":"이번 달부터","mis":"K6-2-u5-X29"},{"t":"도서 도우미 여덟 명이","mis":"K6-2-u5-X29"}],"explanation":["「당번을 나누어」는 어떻게예요.","「이번 달부터」는 언제예요.","「도우미 여덟 명이」는 누가예요."],"asset":{"type":"passage","lines":["[표제] 점심시간 도서관, 이제 문이 열립니다","[부제] ― 도서 도우미 여덟 명이 당번을 나누어 맡아 ―","[전문] 우리 학교 도서관이 이번 달부터 점심시간에도 문을 연다.","육학년 도서 도우미 여덟 명이 요일별로 당번을 나누어 맡기로 하면서","가능해졌다."],"title":"본보기 기사문 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#2','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C19',2,'ox','auto','부제는 모든 기사문에 꼭 붙여야 해요.',ARRAY['K6-2-u5-X28']::text[],false,'{"seq":2,"concept":"K6-2-u5-C19","difficulty":2,"kind":"ox","stem":"부제는 모든 기사문에 꼭 붙여야 해요.","answer":"X","reason_options":[{"t":"표제를 보충할 필요가 있을 때만 붙이기 때문에","correct":true},{"t":"표제만으로는 기사가 될 수 없기 때문에","mis":"K6-2-u5-X28"}],"mis":"K6-2-u5-X28","explanation":["부제는 표제를 보충해요.","필요할 때만 붙여요.","표제만 있는 기사문도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#3','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C21',3,'mc','auto','본보기 기사문의 제목으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X31']::text[],false,'{"seq":3,"concept":"K6-2-u5-C21","difficulty":3,"kind":"mc","stem":"본보기 기사문의 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"점심시간 도서관, 이제 문이 열립니다","correct":true},{"t":"온 학교가 뒤집혔다, 역사에 남을 대사건","mis":"K6-2-u5-X31"},{"t":"어떤 곳에서 어떤 일이 있었다","mis":"K6-2-u5-X31"},{"t":"도서관 도우미들이 학교를 구했다","mis":"K6-2-u5-X31"}],"explanation":["부풀린 제목은 본문에 없는 말이에요.","아무 내용도 없는 제목은 기사를 드러내지 못해요.","내용을 담되 부풀리지 않아요."],"asset":{"type":"passage","lines":["[표제] 점심시간 도서관, 이제 문이 열립니다","[부제] ― 도서 도우미 여덟 명이 당번을 나누어 맡아 ―","[전문] 우리 학교 도서관이 이번 달부터 점심시간에도 문을 연다.","육학년 도서 도우미 여덟 명이 요일별로 당번을 나누어 맡기로 하면서","가능해졌다."],"title":"본보기 기사문 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#4','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C20',3,'mc','auto','「이 일은 우리 학교에서 가장 큰 변화다.」를 기사문에 쓰고 싶어요. 어떻게 고쳐야 하나요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27','K6-2-u5-X31']::text[],false,'{"seq":4,"concept":"K6-2-u5-C20","difficulty":3,"kind":"mc","stem":"「이 일은 우리 학교에서 가장 큰 변화다.」를 기사문에 쓰고 싶어요. 어떻게 고쳐야 하나요?","options":[{"t":"누구의 생각인지 밝혀 「한 학생은 ‘가장 큰 변화’라고 말했다」처럼 쓴다","correct":true},{"t":"그대로 쓴다. 기자가 그렇게 느꼈으니 사실이다","mis":"K6-2-u5-X26"},{"t":"「모든 학생이 가장 큰 변화라고 생각한다」로 바꾼다","mis":"K6-2-u5-X27"},{"t":"느낌표를 붙여 더 크게 쓴다","mis":"K6-2-u5-X31"}],"explanation":["「가장 큰 변화」는 생각이에요.","모든 학생에게 물어본 것도 아니에요.","생각을 쓰려면 누구의 생각인지 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#5','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C19',3,'match','auto','육하원칙과 본보기 기사문의 내용을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C19","difficulty":3,"kind":"match","stem":"육하원칙과 본보기 기사문의 내용을 이으세요.","pairs":[{"l":"누가","r":"도서 도우미 여덟 명이"},{"l":"언제","r":"이번 달부터"},{"l":"어디에서","r":"학교 도서관에서"},{"l":"어떻게","r":"요일별로 당번을 나누어"}],"mis":"K6-2-u5-X29","explanation":["사람은 누가예요.","때는 언제, 곳은 어디에서예요.","방법은 어떻게예요."],"asset":{"type":"passage","lines":["[표제] 점심시간 도서관, 이제 문이 열립니다","[부제] ― 도서 도우미 여덟 명이 당번을 나누어 맡아 ―","[전문] 우리 학교 도서관이 이번 달부터 점심시간에도 문을 연다.","육학년 도서 도우미 여덟 명이 요일별로 당번을 나누어 맡기로 하면서","가능해졌다."],"title":"본보기 기사문 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#6','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C18',3,'mc','auto','기사문의 표현으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27']::text[],false,'{"seq":6,"concept":"K6-2-u5-C18","difficulty":3,"kind":"mc","stem":"기사문의 표현으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「셋째 날은 스물여섯 명이 왔다.」","correct":true},{"t":"「셋째 날은 정말 엄청나게 많이 와서 깜짝 놀랐다!」","mis":"K6-2-u5-X26"},{"t":"「셋째 날은 아마 백 명쯤 왔을 것이다.」","mis":"K6-2-u5-X27"},{"t":"「셋째 날은 사람들이 바글바글, 북적북적!」","mis":"K6-2-u5-X26"}],"explanation":["놀람과 꾸밈은 객관적이지 않아요.","「아마 백 명쯤」은 지어낸 수예요.","세어 본 수를 간결하게 써요."],"asset":{"type":"passage","lines":["[본문] 그동안 도서관은 아침 시간과 방과 후에만 열려 있었다.","지난주 도서 도우미들이 모여 날마다 두 명씩 맡기로 당번을 정했다.","기자단이 문을 연 첫 사흘 동안 온 사람 수를 세어 보았다.","첫날은 열두 명, 둘째 날은 열아홉 명, 셋째 날은 스물여섯 명이었다.","하언 학생은 「쉬는 시간이 짧아 못 오던 친구들이 많이 온다」라고 말했다.","도우미들은 다음 달부터 새 책 알림 게시판도 만들 계획이라고 밝혔다."],"title":"본보기 기사문 (본문)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#7','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C21',3,'error','auto','기사문 계획을 세웠어요. 알맞지 않은 계획은 누구의 것인가요?',ARRAY['K6-2-u5-X32','K6-2-u5-X30','K6-2-u5-X27']::text[],false,'{"seq":7,"concept":"K6-2-u5-C21","difficulty":3,"kind":"error","stem":"기사문 계획을 세웠어요. 알맞지 않은 계획은 누구의 것인가요?","options":[{"t":"서윤 — 「사진은 인터넷에서 아무거나 가져오고 어디서 났는지는 안 적을래.」","correct":true,"mis_target":"K6-2-u5-X32"},{"t":"건우 — 「독자는 우리 학교 학생이니 급식실 줄 서기 방법을 다룰래.」","mis":"K6-2-u5-X30"},{"t":"예린 — 「줄 선 사람 수는 내가 점심시간에 직접 세어 볼래.」","mis":"K6-2-u5-X27"}],"explanation":["건우와 예린은 독자와 확인을 생각했어요.","서윤은 출처를 밝히지 않았어요.","자료의 출처는 반드시 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#8','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C18',4,'mc','auto','본보기 기사문을 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27','K6-2-u5-X31']::text[],false,'{"seq":8,"concept":"K6-2-u5-C18","difficulty":4,"kind":"mc","stem":"본보기 기사문을 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"세어 본 수와 들은 말, 물어 확인한 계획만 썼고, 하언 학생의 생각은 누구의 말인지 밝혀 옮겼다","correct":true},{"t":"느낌이 하나도 없어 재미없는 기사문이다","mis":"K6-2-u5-X26"},{"t":"사람 수를 세어 쓴 것은 지나친 일이다","mis":"K6-2-u5-X27"},{"t":"제목에 놀라운 말을 넣지 않아 실패한 기사문이다","mis":"K6-2-u5-X31"}],"explanation":["기사문은 느낌보다 사실이에요.","세어 본 수가 믿음을 줘요.","생각은 누구의 것인지 밝혔어요."],"asset":{"type":"passage","lines":["[본문] 그동안 도서관은 아침 시간과 방과 후에만 열려 있었다.","지난주 도서 도우미들이 모여 날마다 두 명씩 맡기로 당번을 정했다.","기자단이 문을 연 첫 사흘 동안 온 사람 수를 세어 보았다.","첫날은 열두 명, 둘째 날은 열아홉 명, 셋째 날은 스물여섯 명이었다.","하언 학생은 「쉬는 시간이 짧아 못 오던 친구들이 많이 온다」라고 말했다.","도우미들은 다음 달부터 새 책 알림 게시판도 만들 계획이라고 밝혔다."],"title":"본보기 기사문 (본문)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#9','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C19',4,'essay','teacher','본보기 기사문의 전문을 육하원칙에 따라 여섯 가지로 나누어 쓰고, 전문이 기사문에서 하는 일을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C19","difficulty":4,"kind":"essay","stem":"본보기 기사문의 전문을 육하원칙에 따라 여섯 가지로 나누어 쓰고, 전문이 기사문에서 하는 일을 쓰세요.","answer_guide":{"answer":"예: 누가 — 육학년 도서 도우미 여덟 명이. 언제 — 이번 달부터. 어디에서 — 학교 도서관에서. 무엇을 — 점심시간에 문을 여는 일을. 어떻게 — 요일별로 당번을 나누어. 왜 — 점심시간에도 책을 빌릴 수 있게 하려고. 전문은 기사의 주요 내용을 앞에서 요약해 주어 전문만 읽어도 무슨 일인지 알 수 있게 한다.","scoring_points":["육하원칙 여섯 가지를 바르게 나누었는가","각 항목에 맞는 내용을 찾았는가","전문이 하는 일을 썼는가"]},"explanation":["여섯 물음에 하나씩 답해요.","전문은 요약이에요.","본문이 자세히 풀어요."],"asset":{"type":"passage","lines":["[표제] 점심시간 도서관, 이제 문이 열립니다","[부제] ― 도서 도우미 여덟 명이 당번을 나누어 맡아 ―","[전문] 우리 학교 도서관이 이번 달부터 점심시간에도 문을 연다.","육학년 도서 도우미 여덟 명이 요일별로 당번을 나누어 맡기로 하면서","가능해졌다."],"title":"본보기 기사문 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#10','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C20',4,'essay','teacher','기사문에 들어갈 수 있는 것과 들어갈 수 없는 것을 두 가지씩 쓰고, 그렇게 가른 까닭을 쓰세요. 그리고 쓴 사람의 생각을 기사문에 넣고 싶을 때 어떻게 해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C20","difficulty":4,"kind":"essay","stem":"기사문에 들어갈 수 있는 것과 들어갈 수 없는 것을 두 가지씩 쓰고, 그렇게 가른 까닭을 쓰세요. 그리고 쓴 사람의 생각을 기사문에 넣고 싶을 때 어떻게 해야 하는지 쓰세요.","answer_guide":{"answer":"예: 들어갈 수 있는 것 — 직접 세어 본 사람 수, 직접 들은 사람의 말. 들어갈 수 없는 것 — 확인하지 못한 소문, 그럴 것 같아서 지어낸 숫자. 까닭 — 기사문은 읽는 사람이 사실이라고 믿고 읽는 글이라 누구든 다시 확인할 수 있는 것만 써야 한다. 생각을 넣고 싶으면 「한 학생은 ~라고 말했다」처럼 누구의 생각인지 밝혀 쓴다.","scoring_points":["들어갈 수 있는 것을 두 가지 썼는가","들어갈 수 없는 것을 두 가지 썼는가","까닭과 생각을 넣는 방법을 썼는가"]},"explanation":["확인한 것만.","지어내지 않아요.","생각은 누구의 것인지 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#1','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C22',1,'mc','auto','편지의 짜임에서 편지를 쓴 목적이 담기는 부분은 어느 것인가요?',ARRAY['K6-2-u5-X33']::text[],false,'{"seq":1,"concept":"K6-2-u5-C22","difficulty":1,"kind":"mc","stem":"편지의 짜임에서 편지를 쓴 목적이 담기는 부분은 어느 것인가요?","options":[{"t":"하고 싶은 말","correct":true},{"t":"첫인사","mis":"K6-2-u5-X33"},{"t":"끝인사","mis":"K6-2-u5-X33"},{"t":"쓴 날짜와 보내는 사람","mis":"K6-2-u5-X33"}],"explanation":["첫인사는 안부를 물어요.","끝인사는 마무리 인사예요.","목적은 하고 싶은 말에 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#2','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C22',1,'ox','auto','편지의 독자는 받는 사람 한 사람이에요.',ARRAY['K6-2-u5-X34']::text[],false,'{"seq":2,"concept":"K6-2-u5-C22","difficulty":1,"kind":"ox","stem":"편지의 독자는 받는 사람 한 사람이에요.","answer":"O","reason_options":[{"t":"편지는 받는 사람을 또렷하게 떠올리며 쓰는 글이기 때문에","correct":true},{"t":"편지는 누구나 읽어도 되는 글이기 때문에","mis":"K6-2-u5-X34"}],"mis":"K6-2-u5-X34","explanation":["편지는 한 사람에게 보내요.","그래서 그 사람에게 알맞은 말을 골라요.","독자를 가장 또렷하게 떠올리는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#3','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C25',1,'mc','auto','「붉다」는 어떻게 소리 나나요?',ARRAY['K6-2-u5-X39','K6-2-u5-X38']::text[],false,'{"seq":3,"concept":"K6-2-u5-C25","difficulty":1,"kind":"mc","stem":"「붉다」는 어떻게 소리 나나요?","options":[{"t":"[북따]","correct":true},{"t":"[불따]","mis":"K6-2-u5-X39"},{"t":"[붉따]","mis":"K6-2-u5-X38"},{"t":"[부르따]","mis":"K6-2-u5-X39"}],"explanation":["뒤에 자음자가 오면 하나만 소리 나요.","붉다는 ㄱ 소리가 나요.","그래서 [북따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#4','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C23',1,'mc','auto','고마운 마음을 전하는 편지에 쓰면 좋은 것은 어느 것인가요?',ARRAY['K6-2-u5-X36','K6-2-u5-X35']::text[],false,'{"seq":4,"concept":"K6-2-u5-C23","difficulty":1,"kind":"mc","stem":"고마운 마음을 전하는 편지에 쓰면 좋은 것은 어느 것인가요?","options":[{"t":"무엇이 고마웠는지 그 일을 콕 집어 쓴다","correct":true},{"t":"「고마워」 한 마디만 쓴다","mis":"K6-2-u5-X36"},{"t":"다음에는 이렇게 하라고 충고를 쓴다","mis":"K6-2-u5-X35"},{"t":"내 변명을 먼저 길게 쓴다","mis":"K6-2-u5-X35"}],"explanation":["막연하면 마음이 잘 닿지 않아요.","충고와 변명은 이 마음에 맞지 않아요.","고마운 일을 콕 집어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#5','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C22',2,'match','auto','편지의 부분과 하는 일을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C22","difficulty":2,"kind":"match","stem":"편지의 부분과 하는 일을 이으세요.","pairs":[{"l":"첫인사","r":"안부를 물으며 말문을 엽니다"},{"l":"하고 싶은 말","r":"편지를 쓴 목적을 담습니다"},{"l":"쓴 날짜와 보내는 사람","r":"언제 누가 썼는지 알려 줍니다"}],"mis":"K6-2-u5-X33","explanation":["첫인사로 말문을 열어요.","하고 싶은 말에 목적을 담아요.","끝에 날짜와 이름을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#6','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C23',2,'mc','auto','오래 준비한 발표를 잘 마친 친구에게 쓸 편지로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X36','K6-2-u5-X35']::text[],false,'{"seq":6,"concept":"K6-2-u5-C23","difficulty":2,"kind":"mc","stem":"오래 준비한 발표를 잘 마친 친구에게 쓸 편지로 알맞은 것은 어느 것인가요?","options":[{"t":"쉬는 시간마다 연습하던 걸 봤어. 정말 축하해","correct":true},{"t":"잘했네. 그럼 이만 줄일게","mis":"K6-2-u5-X36"},{"t":"다음에는 목소리를 더 크게 내는 게 좋을 것 같아","mis":"K6-2-u5-X35"},{"t":"나도 발표 잘하는데 다음엔 나랑 같이 하자","mis":"K6-2-u5-X35"}],"explanation":["막연한 칭찬은 잘 닿지 않아요.","축하할 때 충고는 마음에 맞지 않아요.","애쓴 과정을 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#7','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C22',2,'mc','auto','시율이의 편지에서 첫인사에 해당하는 것은 어느 것인가요?',ARRAY['K6-2-u5-X33']::text[],false,'{"seq":7,"concept":"K6-2-u5-C22","difficulty":2,"kind":"mc","stem":"시율이의 편지에서 첫인사에 해당하는 것은 어느 것인가요?","options":[{"t":"요즘 아침 공기가 제법 서늘하지. 감기 걸리지 않게 잘 지내지?","correct":true},{"t":"네가 「천천히 다시 찾아보자」라고 말해 준 게 제일 고마웠어.","mis":"K6-2-u5-X33"},{"t":"고마웠어. 내일 학교에서 보자.","mis":"K6-2-u5-X33"},{"t":"○○월 ○○일 시율이가","mis":"K6-2-u5-X33"}],"explanation":["고마웠던 일은 하고 싶은 말이에요.","「내일 보자」는 끝인사예요.","안부를 묻는 말이 첫인사예요."],"asset":{"type":"passage","lines":["도아에게","도아야, 요즘 아침 공기가 제법 서늘하지. 감기 걸리지 않게 잘 지내지?","지난주에 내가 발표 자료를 잃어버려서 쩔쩔맬 때 네가 같이 찾아 줬잖아.","네가 「천천히 다시 찾아보자」라고 말해 준 게 제일 고마웠어.","다음에 네가 무언가를 잃어버리면 내가 꼭 같이 찾아 줄게.","이번 주 도서관 당번도 나랑 바꾸고 싶으면 말해 줘.","고마웠어. 내일 학교에서 보자.","○○월 ○○일 시율이가"],"title":"시율이가 도아에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#8','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C24',2,'mc','auto','편지를 전할 매체를 고르는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X10','K6-2-u5-X37']::text[],false,'{"seq":8,"concept":"K6-2-u5-C24","difficulty":2,"kind":"mc","stem":"편지를 전할 매체를 고르는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"전하려는 마음과 받는 사람의 처지에 맞는 것을 고른다","correct":true},{"t":"영상으로 만들면 마음이 언제나 더 잘 전해진다","mis":"K6-2-u5-X03"},{"t":"가장 빨리 만들 수 있는 것을 고르면 된다","mis":"K6-2-u5-X10"},{"t":"가장 화려하게 꾸밀 수 있는 것을 고른다","mis":"K6-2-u5-X37"}],"explanation":["매체에는 등수가 없어요.","빠르기나 꾸밈이 기준은 아니에요.","마음과 받는 사람을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#9','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C25',2,'ox','auto','「얇아요」는 [얄바요]로 소리 나요.',ARRAY['K6-2-u5-X38']::text[],false,'{"seq":9,"concept":"K6-2-u5-C25","difficulty":2,"kind":"ox","stem":"「얇아요」는 [얄바요]로 소리 나요.","answer":"O","reason_options":[{"t":"뒤에 모음이 오면 겹받침의 두 소리가 다 나고 뒤엣것이 뒷글자로 넘어가기 때문에","correct":true},{"t":"겹받침은 언제나 앞의 것 하나만 소리 나기 때문에","mis":"K6-2-u5-X38"}],"mis":"K6-2-u5-X38","explanation":["얇다는 [얄따]로 하나만 소리 나요.","얇아요는 뒤에 모음이 와요.","ㅂ이 뒷글자로 넘어가 [얄바요]가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#10','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C23',3,'error','auto','마음에 맞는 편지 내용을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X35']::text[],false,'{"seq":10,"concept":"K6-2-u5-C23","difficulty":3,"kind":"error","stem":"마음에 맞는 편지 내용을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하엘 — 「미안한 마음을 전할 땐 내가 왜 그럴 수밖에 없었는지 변명부터 길게 써야 해.」","correct":true,"mis_target":"K6-2-u5-X35"},{"t":"규리 — 「힘을 내라는 마음은 섣부른 충고보다 곁에 있다는 말로 전해.」","mis":"K6-2-u5-X35"},{"t":"시안 — 「축하할 땐 그 친구가 애쓴 과정을 함께 써.」","mis":"K6-2-u5-X35"}],"explanation":["규리와 시안은 마음에 맞는 내용을 말했어요.","미안할 땐 무엇이 잘못이었는지 먼저 써요.","변명이 앞서면 사과가 닿지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#1','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C25',2,'sa','auto','「짧다」는 어떻게 소리 나나요? 대괄호 없이 소리 나는 대로 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u5-C25","difficulty":2,"kind":"sa","stem":"「짧다」는 어떻게 소리 나나요? 대괄호 없이 소리 나는 대로 두 글자로 쓰세요.","answer":["짤따"],"explanation":["뒤에 자음자가 오면 하나만 소리 나요.","짧다는 ㄹ 소리가 나요.","그래서 [짤따]예요."],"mis":"K6-2-u5-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#2','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C25',2,'mc','auto','겹받침 뒤에 모음이 올 때 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-2-u5-X38','K6-2-u5-X39']::text[],false,'{"seq":2,"concept":"K6-2-u5-C25","difficulty":2,"kind":"mc","stem":"겹받침 뒤에 모음이 올 때 바르게 읽은 것은 어느 것인가요?","options":[{"t":"늙어요 → [늘거요]","correct":true},{"t":"늙어요 → [늑어요]","mis":"K6-2-u5-X38"},{"t":"늙어요 → [늘어요]","mis":"K6-2-u5-X39"},{"t":"늙어요 → [느거요]","mis":"K6-2-u5-X39"}],"explanation":["늙다는 [늑따]로 하나만 소리 나요.","뒤에 모음이 오면 두 소리가 다 나요.","ㄱ이 뒷글자로 넘어가 [늘거요]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#3','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C24',3,'mc','auto','편지를 쓴 뒤 하면 좋은 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X37']::text[],false,'{"seq":3,"concept":"K6-2-u5-C24","difficulty":3,"kind":"mc","stem":"편지를 쓴 뒤 하면 좋은 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실제로 건네고 받는 사람이 어떤 부분이 마음에 남았는지 들어 본다","correct":true},{"t":"숙제로 냈으니 다시 생각하지 않는다","mis":"K6-2-u5-X37"},{"t":"편지지를 더 예쁘게 꾸미는 데 시간을 쓴다","mis":"K6-2-u5-X37"},{"t":"받는 사람이 고칠 점을 말하면 다시는 쓰지 않는다","mis":"K6-2-u5-X37"}],"explanation":["편지는 건네고 나서 완성돼요.","꾸밈에 시간을 다 쓰지 않아요.","반응을 듣고 다음에 또 쓸 일을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#4','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C22',3,'mc','auto','시율이의 편지에서 독자를 고려한 곳이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X36','K6-2-u5-X33','K6-2-u5-X34']::text[],false,'{"seq":4,"concept":"K6-2-u5-C22","difficulty":3,"kind":"mc","stem":"시율이의 편지에서 독자를 고려한 곳이 아닌 것은 어느 것인가요?","options":[{"t":"편지의 글자 수를 정확히 맞추었다","correct":true},{"t":"둘이 함께 겪은 일을 콕 집어 적었다","mis":"K6-2-u5-X36"},{"t":"받는 사람의 안부를 먼저 물었다","mis":"K6-2-u5-X33"},{"t":"받는 사람이 고를 수 있게 당번을 바꾸자고 제안했다","mis":"K6-2-u5-X34"}],"explanation":["함께 겪은 일 · 안부 · 제안은 도아를 떠올린 흔적이에요.","글자 수는 독자와 상관없어요.","받는 사람을 떠올리며 쓴 곳을 찾아요."],"asset":{"type":"passage","lines":["도아에게","도아야, 요즘 아침 공기가 제법 서늘하지. 감기 걸리지 않게 잘 지내지?","지난주에 내가 발표 자료를 잃어버려서 쩔쩔맬 때 네가 같이 찾아 줬잖아.","네가 「천천히 다시 찾아보자」라고 말해 준 게 제일 고마웠어.","다음에 네가 무언가를 잃어버리면 내가 꼭 같이 찾아 줄게.","이번 주 도서관 당번도 나랑 바꾸고 싶으면 말해 줘.","고마웠어. 내일 학교에서 보자.","○○월 ○○일 시율이가"],"title":"시율이가 도아에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#5','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C23',3,'match','auto','전하려는 마음과 쓰면 좋은 내용을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C23","difficulty":3,"kind":"match","stem":"전하려는 마음과 쓰면 좋은 내용을 이으세요.","pairs":[{"l":"고마운 마음","r":"무엇이 고마웠는지 그 일을 콕 집어"},{"l":"미안한 마음","r":"무엇이 잘못이었는지 먼저"},{"l":"축하하는 마음","r":"그 사람이 애쓴 과정을 함께"},{"l":"힘을 내라는 마음","r":"곁에 있다는 말을"}],"mis":"K6-2-u5-X35","explanation":["고마움은 콕 집어요.","사과는 잘못부터, 축하는 과정과 함께예요.","위로는 충고보다 곁에 있다는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#6','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C24',3,'error','auto','편지 매체를 골랐어요. 까닭이 알맞지 않은 친구는 누구인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X10']::text[],false,'{"seq":6,"concept":"K6-2-u5-C24","difficulty":3,"kind":"error","stem":"편지 매체를 골랐어요. 까닭이 알맞지 않은 친구는 누구인가요?","options":[{"t":"태린 — 「영상 편지가 손 편지보다 언제나 더 좋은 거니까 영상으로 할래.」","correct":true,"mis_target":"K6-2-u5-X03"},{"t":"유나 — 「할머니가 오래 간직하시게 손 편지로 쓸래.」","mis":"K6-2-u5-X10"},{"t":"민결 — 「멀리 있는 사촌에게 목소리와 표정을 보여 주려고 영상으로 할래.」","mis":"K6-2-u5-X10"}],"explanation":["유나와 민결은 마음과 받는 사람을 보고 골랐어요.","태린은 매체에 등수를 매겼어요.","매체에는 등수가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#7','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C22',3,'mc','auto','할머니께 편지를 쓸 때 알맞은 첫 문장은 어느 것인가요?',ARRAY['K6-2-u5-X34','K6-2-u5-X36']::text[],false,'{"seq":7,"concept":"K6-2-u5-C22","difficulty":3,"kind":"mc","stem":"할머니께 편지를 쓸 때 알맞은 첫 문장은 어느 것인가요?","options":[{"t":"할머니, 그동안 건강하게 잘 지내셨어요?","correct":true},{"t":"할머니, 잘 지냈어?","mis":"K6-2-u5-X34"},{"t":"안녕! 오랜만이야.","mis":"K6-2-u5-X34"},{"t":"그거 고마웠어.","mis":"K6-2-u5-X36"}],"explanation":["받는 사람은 웃어른이에요.","알맞은 높임말을 써요.","안부를 여쭈며 말문을 열어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#8','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C23',4,'mc','auto','시율이의 편지를 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X36','K6-2-u5-X33','K6-2-u5-X22']::text[],false,'{"seq":8,"concept":"K6-2-u5-C23","difficulty":4,"kind":"mc","stem":"시율이의 편지를 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"함께 찾아 준 일과 「천천히 다시 찾아보자」라는 말을 콕 집어 고마운 까닭을 밝혀, 막연한 고마움보다 마음이 잘 닿는다","correct":true},{"t":"「고마웠어」를 여러 번 쓰지 않아서 고마움이 약하다","mis":"K6-2-u5-X36"},{"t":"당번을 바꾸자는 말은 편지와 상관없어 빼야 한다","mis":"K6-2-u5-X33"},{"t":"편지가 짧아서 마음이 잘 닿지 않는다","mis":"K6-2-u5-X22"}],"explanation":["고마움의 크기는 낱말의 개수가 아니에요.","제안은 받는 사람을 생각한 말이에요.","콕 집어 쓴 것이 마음을 전해요."],"asset":{"type":"passage","lines":["도아에게","도아야, 요즘 아침 공기가 제법 서늘하지. 감기 걸리지 않게 잘 지내지?","지난주에 내가 발표 자료를 잃어버려서 쩔쩔맬 때 네가 같이 찾아 줬잖아.","네가 「천천히 다시 찾아보자」라고 말해 준 게 제일 고마웠어.","다음에 네가 무언가를 잃어버리면 내가 꼭 같이 찾아 줄게.","이번 주 도서관 당번도 나랑 바꾸고 싶으면 말해 줘.","고마웠어. 내일 학교에서 보자.","○○월 ○○일 시율이가"],"title":"시율이가 도아에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#9','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C22',4,'essay','teacher','마음을 전하고 싶은 사람을 한 명 정해, 편지의 다섯 부분을 모두 갖춘 짧은 편지를 쓰세요. 받는 사람에게 알맞은 말을 쓰고, 전하려는 마음에 맞는 내용을 콕 집어 쓰세요. 날짜는 ○○월 ○○일로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C22","difficulty":4,"kind":"essay","stem":"마음을 전하고 싶은 사람을 한 명 정해, 편지의 다섯 부분을 모두 갖춘 짧은 편지를 쓰세요. 받는 사람에게 알맞은 말을 쓰고, 전하려는 마음에 맞는 내용을 콕 집어 쓰세요. 날짜는 ○○월 ○○일로 쓰세요.","answer_guide":{"answer":"예: 선생님께 / 선생님, 요즘 아침저녁으로 쌀쌀한데 감기 걸리지 않으셨어요? / 지난번 줄넘기 시험 날 제가 자꾸 걸려서 울상이었을 때, 선생님께서 「박자를 소리 내어 세어 봐」라고 알려 주셔서 끝까지 넘을 수 있었어요. 그 한마디가 정말 고마웠어요. / 늘 건강하세요. / ○○월 ○○일 제자 ○○ 올림","scoring_points":["다섯 부분을 모두 갖추었는가","받는 사람에게 알맞은 높임말을 썼는가","전하려는 마음에 맞는 내용을 콕 집어 썼는가"]},"explanation":["받는 사람 · 첫인사 · 하고 싶은 말 · 끝인사 · 날짜와 이름.","받는 사람에게 맞는 말.","그 일을 콕 집어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#10','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C25',4,'essay','teacher','겹받침이 있는 낱말이 소리 나는 두 가지 규칙을 쓰고, 「붉다 · 붉어요」와 「짧다 · 짧아요」가 어떻게 소리 나는지 규칙과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C25","difficulty":4,"kind":"essay","stem":"겹받침이 있는 낱말이 소리 나는 두 가지 규칙을 쓰고, 「붉다 · 붉어요」와 「짧다 · 짧아요」가 어떻게 소리 나는지 규칙과 이어 쓰세요.","answer_guide":{"answer":"예: 겹받침 뒤에 자음자가 오거나 낱말이 끝나면 하나만 소리 나고, 뒤에 모음이 오면 두 소리가 다 나며 뒤엣것이 뒷글자로 넘어간다. 붉다는 뒤에 자음자가 와서 [북따], 붉어요는 뒤에 모음이 와서 ㄱ이 넘어가 [불거요]로 소리 난다. 짧다는 [짤따], 짧아요는 ㅂ이 넘어가 [짤바요]로 소리 난다.","scoring_points":["두 가지 규칙을 바르게 썼는가","붉다 · 붉어요의 소리를 규칙과 이었는가","짧다 · 짧아요의 소리를 규칙과 이었는가"]},"explanation":["자음자 앞에서는 하나.","모음 앞에서는 둘.","뒤엣것이 뒷글자로 넘어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#1','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C1',1,'mc','auto','「문자 언어」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X04']::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"mc","stem":"「문자 언어」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"글자로 나타내는 말","correct":true},{"t":"음성으로 나타내는 말","mis":"K6-2-u5-X01"},{"t":"소리와 음악으로 나타내는 것","mis":"K6-2-u5-X04"},{"t":"표정과 몸짓으로 나타내는 것","mis":"K6-2-u5-X01"}],"explanation":["음성으로 나타내는 말은 음성 언어예요.","소리와 음악은 함께 쓰는 요소예요.","글자로 나타내는 말이 문자 언어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#2','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C2',1,'ox','auto','녹음해 둔 말은 다시 들을 수 있어요.',ARRAY['K6-2-u5-X02']::text[],false,'{"seq":2,"concept":"K6-2-u5-C2","difficulty":1,"kind":"ox","stem":"녹음해 둔 말은 다시 들을 수 있어요.","answer":"O","reason_options":[{"t":"매체에 따라 말도 남을 수 있기 때문에","correct":true},{"t":"말은 언제나 사라지기 때문에","mis":"K6-2-u5-X02"}],"mis":"K6-2-u5-X02","explanation":["말은 보통 그 자리에서 사라져요.","녹음하면 남아요.","매체에 따라 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#3','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C3',1,'mc','auto','라디오는 어떤 매체인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":3,"concept":"K6-2-u5-C3","difficulty":1,"kind":"mc","stem":"라디오는 어떤 매체인가요?","options":[{"t":"음성 매체","correct":true},{"t":"인쇄 매체","mis":"K6-2-u5-X04"},{"t":"영상 매체","mis":"K6-2-u5-X04"},{"t":"문자 매체","mis":"K6-2-u5-X04"}],"explanation":["라디오는 소리로 전해요.","음성 언어에 소리와 음악을 더해요.","그래서 음성 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#4','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C4',1,'mc','auto','문자 언어에서 중요한 곳을 강조하는 방법은 어느 것인가요?',ARRAY['K6-2-u5-X06']::text[],false,'{"seq":4,"concept":"K6-2-u5-C4","difficulty":1,"kind":"mc","stem":"문자 언어에서 중요한 곳을 강조하는 방법은 어느 것인가요?","options":[{"t":"글자를 굵게 한다","correct":true},{"t":"목소리를 크게 한다","mis":"K6-2-u5-X06"},{"t":"억양을 올린다","mis":"K6-2-u5-X06"},{"t":"잠깐 쉬었다 말한다","mis":"K6-2-u5-X06"}],"explanation":["목소리 · 억양 · 쉬기는 말의 방법이에요.","글에서는 글자 굵기를 써요.","눈에 띄게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#5','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C9',1,'mc','auto','말한 내용을 자막으로도 보여 주면 좋은 점은 어느 것인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X13']::text[],false,'{"seq":5,"concept":"K6-2-u5-C9","difficulty":1,"kind":"mc","stem":"말한 내용을 자막으로도 보여 주면 좋은 점은 어느 것인가요?","options":[{"t":"놓친 내용을 눈으로 다시 확인할 수 있다","correct":true},{"t":"영상을 짧게 줄일 수 있다","mis":"K6-2-u5-X11"},{"t":"해설하는 말을 없애도 된다","mis":"K6-2-u5-X11"},{"t":"글자가 많아 화려해진다","mis":"K6-2-u5-X13"}],"explanation":["말은 지나가요.","자막은 남아요.","둘이 서로 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#6','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C16',1,'mc','auto','「쓸 거리를 모아 차례를 짜는」 단계는 어느 것인가요?',ARRAY['K6-2-u5-X21']::text[],false,'{"seq":6,"concept":"K6-2-u5-C16","difficulty":1,"kind":"mc","stem":"「쓸 거리를 모아 차례를 짜는」 단계는 어느 것인가요?","options":[{"t":"내용 생성하고 조직하기","correct":true},{"t":"계획 세우기","mis":"K6-2-u5-X21"},{"t":"글 쓰고 고쳐 쓰기","mis":"K6-2-u5-X21"},{"t":"독자에게 건네기","mis":"K6-2-u5-X21"}],"explanation":["계획 세우기에서는 독자와 목적을 정해요.","고쳐 쓰기는 쓴 뒤에 해요.","쓸 거리와 차례는 내용 조직 단계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#7','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C19',1,'mc','auto','기사문의 제목을 무엇이라고 하나요?',ARRAY['K6-2-u5-X28']::text[],false,'{"seq":7,"concept":"K6-2-u5-C19","difficulty":1,"kind":"mc","stem":"기사문의 제목을 무엇이라고 하나요?","options":[{"t":"표제","correct":true},{"t":"전문","mis":"K6-2-u5-X28"},{"t":"본문","mis":"K6-2-u5-X28"},{"t":"부록","mis":"K6-2-u5-X28"}],"explanation":["전문은 요약, 본문은 자세한 내용이에요.","기사의 제목은 표제예요.","부제는 표제를 보충해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#8','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C22',1,'mc','auto','편지의 짜임에서 가장 먼저 오는 것은 어느 것인가요?',ARRAY['K6-2-u5-X33']::text[],false,'{"seq":8,"concept":"K6-2-u5-C22","difficulty":1,"kind":"mc","stem":"편지의 짜임에서 가장 먼저 오는 것은 어느 것인가요?","options":[{"t":"받는 사람","correct":true},{"t":"끝인사","mis":"K6-2-u5-X33"},{"t":"쓴 날짜와 보내는 사람","mis":"K6-2-u5-X33"},{"t":"하고 싶은 말","mis":"K6-2-u5-X33"}],"explanation":["편지는 누구에게 쓰는지부터 밝혀요.","그다음 첫인사, 하고 싶은 말, 끝인사가 와요.","마지막에 날짜와 보내는 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#9','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C5',2,'mc','auto','지안이가 모이는 시각을 벌써 잊어버린 까닭과 가장 관계 깊은 음성 언어의 특성은 어느 것인가요?',ARRAY['K6-2-u5-X08','K6-2-u5-X06']::text[],false,'{"seq":9,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"지안이가 모이는 시각을 벌써 잊어버린 까닭과 가장 관계 깊은 음성 언어의 특성은 어느 것인가요?","options":[{"t":"말이 끝나면 소리가 사라진다","correct":true},{"t":"목소리로 감정을 함께 전한다","mis":"K6-2-u5-X08"},{"t":"그 자리에서 되물을 수 있다","mis":"K6-2-u5-X08"},{"t":"글자 굵기로 강조할 수 있다","mis":"K6-2-u5-X06"}],"explanation":["선생님 말씀은 이미 지나갔어요.","말은 보통 그 자리에서 사라져요.","그래서 지안이가 놓쳤어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#10','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C6',2,'match','auto','은솔이네 반 상황과 알맞은 방법을 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C6","difficulty":2,"kind":"match","stem":"은솔이네 반 상황과 알맞은 방법을 이으세요.","pairs":[{"l":"모일 시각과 챙길 것","r":"알림장에 글로 적는다"},{"l":"비 오는 날 일정이 궁금함","r":"그 자리에서 말로 묻는다"},{"l":"여럿이 헷갈리는 내용","r":"말로 하고 글로도 보여 준다"}],"mis":"K6-2-u5-X10","explanation":["다시 봐야 하는 것은 글로 적어요.","궁금한 것은 말로 바로 물어요.","헷갈리는 것은 둘을 함께 써요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#11','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C8',2,'mc','auto','「한 번 더 헹궈요」가 전하려는 것은 무엇인가요?',ARRAY['K6-2-u5-X17']::text[],false,'{"seq":11,"concept":"K6-2-u5-C8","difficulty":2,"kind":"mc","stem":"「한 번 더 헹궈요」가 전하려는 것은 무엇인가요?","options":[{"t":"우유갑은 헹구어 펼쳐 말린 뒤 종이로 내놓자","correct":true},{"t":"우유를 마시지 말자","mis":"K6-2-u5-X17"},{"t":"쓰레기는 모두 한 통에 버리자","mis":"K6-2-u5-X17"},{"t":"분리배출은 어려우니 하지 말자","mis":"K6-2-u5-X17"}],"explanation":["장면 이에서 할 일을 보여 줘요.","장면 사에서 종이 칸에 넣어요.","헹구고 펼치고 말리기를 알려요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#12','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C11',2,'match','auto','「한 번 더 헹궈요」의 장면과 그 장면에서 해야 할 일을 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u5-C11","difficulty":2,"kind":"match","stem":"「한 번 더 헹궈요」의 장면과 그 장면에서 해야 할 일을 이으세요.","pairs":[{"l":"장면 일 — 자막으로 제목","r":"무엇을 다룰지 먼저 알린다"},{"l":"장면 이 — 말과 자막을 함께","r":"해야 할 차례를 정확히 남긴다"},{"l":"장면 사 — 웃는 아이와 짧은 말","r":"해 보고 싶은 마음이 들게 한다"}],"mis":"K6-2-u5-X14","explanation":["처음에는 다룰 것을 알려요.","차례는 말과 자막으로 남겨요.","마지막 장면은 마음을 움직여요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#13','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C20',2,'mc','auto','하은이 기사문에서 확인한 사실로 볼 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27']::text[],false,'{"seq":13,"concept":"K6-2-u5-C20","difficulty":2,"kind":"mc","stem":"하은이 기사문에서 확인한 사실로 볼 수 있는 것은 어느 것인가요?","options":[{"t":"이번 달부터 운동장 동쪽에 선을 그어 공 놀이 구역이 생겼다","correct":true},{"t":"모든 학생이 정말 행복해졌다","mis":"K6-2-u5-X26"},{"t":"쉬는 시간마다 백 명도 넘게 온다","mis":"K6-2-u5-X27"},{"t":"다치는 학생이 하나도 없을 것이다","mis":"K6-2-u5-X26"}],"explanation":["행복과 앞날의 짐작은 생각이에요.","백 명은 세어 본 수가 아니에요.","눈으로 확인할 수 있는 것은 구역이 생긴 일이에요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#14','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C19',2,'mc','auto','하은이 기사문의 [전문]을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X28']::text[],false,'{"seq":14,"concept":"K6-2-u5-C19","difficulty":2,"kind":"mc","stem":"하은이 기사문의 [전문]을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이번 달부터 운동장 동쪽에 쉬는 시간 공 놀이 구역이 선을 그어 마련되었다.","correct":true},{"t":"공 놀이 구역이 생겨서 모두 너무너무 행복하다.","mis":"K6-2-u5-X28"},{"t":"기자는 이 구역이 정말 마음에 든다.","mis":"K6-2-u5-X28"},{"t":"공 놀이 구역, 대박!","mis":"K6-2-u5-X28"}],"explanation":["전문은 느낌을 쓰는 곳이 아니에요.","주요 내용을 육하원칙으로 요약해요.","언제 · 어디에서 · 무엇이 드러나게 써요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#15','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C22',2,'mc','auto','준서의 편지에서 빠진 부분이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X33']::text[],false,'{"seq":15,"concept":"K6-2-u5-C22","difficulty":2,"kind":"mc","stem":"준서의 편지에서 빠진 부분이 아닌 것은 어느 것인가요?","options":[{"t":"첫인사","correct":true},{"t":"받는 사람","mis":"K6-2-u5-X33"},{"t":"쓴 날짜와 보내는 사람","mis":"K6-2-u5-X33"},{"t":"없다. 다섯 부분을 모두 갖추었다","mis":"K6-2-u5-X33"}],"explanation":["「잘 지내지?」는 첫인사예요.","받는 사람과 날짜 · 보내는 사람이 빠졌어요.","다섯 부분을 하나씩 확인해요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#16','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C5',2,'mc','auto','장면 ㉮에서 도아의 목소리가 밝고 빠른 것으로 전해지는 것은 어느 것인가요?',ARRAY['K6-2-u5-X08','K6-2-u5-X02','K6-2-u5-X06']::text[],false,'{"seq":16,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"장면 ㉮에서 도아의 목소리가 밝고 빠른 것으로 전해지는 것은 어느 것인가요?","options":[{"t":"내일을 기대하는 들뜬 마음","correct":true},{"t":"준비물의 정확한 개수","mis":"K6-2-u5-X08"},{"t":"나중에 다시 볼 수 있는 기록","mis":"K6-2-u5-X02"},{"t":"굵은 글씨로 강조한 낱말","mis":"K6-2-u5-X06"}],"explanation":["목소리에는 감정이 실려요.","밝고 빠르면 들뜬 마음이 전해져요.","이것이 음성 언어의 특성이에요."],"asset":{"type":"passage","lines":["장면 ㉮ 도아가 시율이를 만나 직접 말로 내일 준비물을 알려 준다.","목소리가 밝고 빠르다.","장면 ㉯ 도아가 학급 게시판에 글로 적어 내일 준비물을 알린다.","중요한 것에 굵은 글씨를 썼다."],"title":"같은 내용, 다른 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#17','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C6',3,'mc','auto','은솔이네 반 상황에서 문자 언어로 전할 내용과 음성 언어로 전할 내용을 알맞게 나눈 것은 어느 것인가요?',ARRAY['K6-2-u5-X10','K6-2-u5-X03','K6-2-u5-X09']::text[],false,'{"seq":17,"concept":"K6-2-u5-C6","difficulty":3,"kind":"mc","stem":"은솔이네 반 상황에서 문자 언어로 전할 내용과 음성 언어로 전할 내용을 알맞게 나눈 것은 어느 것인가요?","options":[{"t":"모일 시각과 챙길 것은 글로 적고, 비 오는 날처럼 궁금한 것은 그 자리에서 말로 묻고 답한다","correct":true},{"t":"모두 말로만 하고 다시 묻지 않는다","mis":"K6-2-u5-X10"},{"t":"모두 글로만 하고 묻는 것은 받지 않는다","mis":"K6-2-u5-X03"},{"t":"아무렇게나 나누어도 된다","mis":"K6-2-u5-X09"}],"explanation":["다시 봐야 하는 것은 글로.","바로 주고받을 것은 말로.","나눈 까닭을 특성과 이어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#18','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C10',3,'mc','auto','「한 번 더 헹궈요」 영상을 평가한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X15']::text[],false,'{"seq":18,"concept":"K6-2-u5-C10","difficulty":3,"kind":"mc","stem":"「한 번 더 헹궈요」 영상을 평가한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장면 이는 말과 자막으로 차례를 잘 붙들었지만, 장면 삼은 요소가 너무 많아 무엇이 중요한지 흐려졌다","correct":true},{"t":"요소가 가장 많은 장면 삼이 가장 잘 만든 장면이다","mis":"K6-2-u5-X13"},{"t":"자막이 있는 장면은 모두 좋은 장면이다","mis":"K6-2-u5-X13"},{"t":"재미있었으니 고칠 것이 없다","mis":"K6-2-u5-X15"}],"explanation":["잘된 장면과 고칠 장면을 갈라요.","요소의 개수가 기준이 아니에요.","무엇을 돕는지로 평가해요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#19','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C21',3,'mc','auto','하은이 기사문의 표제를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X31']::text[],false,'{"seq":19,"concept":"K6-2-u5-C21","difficulty":3,"kind":"mc","stem":"하은이 기사문의 표제를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"운동장에 쉬는 시간 공 놀이 구역 생겨","correct":true},{"t":"운동장 대혁명, 모두가 환호했다","mis":"K6-2-u5-X31"},{"t":"무슨 일이 생겼다","mis":"K6-2-u5-X31"},{"t":"하은이의 운동장 이야기","mis":"K6-2-u5-X31"}],"explanation":["부풀린 말은 빼요.","내용이 없는 제목도 안 돼요.","무슨 일인지 간결하게 드러내요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#20','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C23',3,'mc','auto','준서의 편지를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X36','K6-2-u5-X35']::text[],false,'{"seq":20,"concept":"K6-2-u5-C23","difficulty":3,"kind":"mc","stem":"준서의 편지를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「여름에 할머니께서 자전거 타는 법을 끝까지 잡아 주셔서 혼자 탈 수 있게 되었어요. 정말 고마웠어요.」","correct":true},{"t":"「저번에 그거 진짜 진짜 고마웠어.」","mis":"K6-2-u5-X36"},{"t":"「김치는 짰지만 고마웠어.」","mis":"K6-2-u5-X35"},{"t":"「고마움.」","mis":"K6-2-u5-X36"}],"explanation":["「그거」를 콕 집어 써요.","높임말을 써요.","충고는 빼요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#21','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C14',3,'mc','auto','「학교 둘레 쓰레기 줍기 행사」 안내 글을 일학년 동생들이 읽게 돼요. 가장 알맞게 쓴 것은 어느 것인가요?',ARRAY['K6-2-u5-X24','K6-2-u5-X25','K6-2-u5-X22']::text[],false,'{"seq":21,"concept":"K6-2-u5-C14","difficulty":3,"kind":"mc","stem":"「학교 둘레 쓰레기 줍기 행사」 안내 글을 일학년 동생들이 읽게 돼요. 가장 알맞게 쓴 것은 어느 것인가요?","options":[{"t":"「목요일 아침, 학교 둘레를 함께 걸으며 쓰레기를 주워요. 장갑은 학교에서 줘요.」","correct":true},{"t":"「환경 정화 활동의 일환으로 교내외 쓰레기 수거를 실시함」","mis":"K6-2-u5-X24"},{"t":"「쓰레기 줍기 행사가 있다.」","mis":"K6-2-u5-X25"},{"t":"「쓰레기를 줍자!!! 꼭!!!」","mis":"K6-2-u5-X22"}],"explanation":["어려운 한자어는 동생들이 몰라요.","언제 무엇을 하는지 없으면 할 수 없어요.","쉬운 말로 까닭과 할 일을 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#22','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C2',3,'mc','auto','이 단원을 마친 학생의 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X02','K6-2-u5-X10']::text[],false,'{"seq":22,"concept":"K6-2-u5-C2","difficulty":3,"kind":"mc","stem":"이 단원을 마친 학생의 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"보통은 이렇지만 매체에 따라 달라요. 그래서 그때그때 살펴요","correct":true},{"t":"글이 말보다 낫고, 영상이 글보다 나아요. 그렇게 외웠어요","mis":"K6-2-u5-X03"},{"t":"말은 절대 남지 않으니까 중요한 건 늘 글로만 해야 해요","mis":"K6-2-u5-X02"},{"t":"매체는 아무거나 골라도 상관없어요","mis":"K6-2-u5-X10"}],"explanation":["특성을 규칙으로 굳히지 않아요.","매체에 등수를 붙이지 않아요.","그 자리에 알맞은 것을 까닭과 함께 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#23','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C6',4,'mc','auto','은솔이네 반 안내를 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X10','K6-2-u5-X08']::text[],false,'{"seq":23,"concept":"K6-2-u5-C6","difficulty":4,"kind":"mc","stem":"은솔이네 반 안내를 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말로 안내해 은솔이가 바로 물을 수 있었던 것은 좋았지만, 챙길 것이 여럿이라 글로도 남겨야 지안이처럼 놓치는 사람이 없다","correct":true},{"t":"말로 했으니 처음부터 잘못된 안내다","mis":"K6-2-u5-X03"},{"t":"지안이가 집중하지 않은 것이 문제일 뿐 안내 방법은 고칠 것이 없다","mis":"K6-2-u5-X10"},{"t":"은솔이가 질문해서 안내가 길어졌으니 질문을 받지 말아야 한다","mis":"K6-2-u5-X08"}],"explanation":["말의 장점을 먼저 봐요.","놓친 사람이 생긴 까닭을 특성으로 봐요.","글로도 남기면 서로 보완돼요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#24','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C6',4,'essay','teacher','은솔이네 반 대화를 보고, 선생님의 안내에서 음성 언어의 좋은 점이 드러난 곳과 아쉬운 점이 드러난 곳을 하나씩 찾아 쓰고, 더 잘 전하는 방법을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u5-C6","difficulty":4,"kind":"essay","stem":"은솔이네 반 대화를 보고, 선생님의 안내에서 음성 언어의 좋은 점이 드러난 곳과 아쉬운 점이 드러난 곳을 하나씩 찾아 쓰고, 더 잘 전하는 방법을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 좋은 점 — 은솔이가 비 오는 날 도시락을 묻자 선생님이 바로 답해 주셨다. 음성 언어는 그 자리에서 되묻고 답할 수 있다. 아쉬운 점 — 지안이는 모이는 시각을 벌써 잊어버렸다. 말은 끝나면 소리가 사라지기 때문이다. 방법 — 말로 안내하면서 알림장에 시각과 챙길 것을 적어 주면 좋다. 글은 남아서 놓친 사람이 다시 볼 수 있으니 두 언어가 서로 보완한다.","scoring_points":["음성 언어의 좋은 점을 대화에서 찾았는가","아쉬운 점을 특성과 이어 썼는가","두 언어를 함께 쓰는 방법과 까닭을 썼는가"]},"explanation":["되묻기는 말의 힘이에요.","사라지는 것은 말의 한계예요.","글로 보완해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#25','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C3',4,'essay','teacher','「글이 말보다 낫고, 영상이 글보다 낫다.」는 말이 왜 알맞지 않은지 이 단원에서 배운 것으로 설명하고, 어떻게 알맞은 방법을 골라야 하는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u5-C3","difficulty":4,"kind":"essay","stem":"「글이 말보다 낫고, 영상이 글보다 낫다.」는 말이 왜 알맞지 않은지 이 단원에서 배운 것으로 설명하고, 어떻게 알맞은 방법을 골라야 하는지 쓰세요.","answer_guide":{"answer":"예: 글은 남아서 다시 볼 수 있지만, 말은 목소리로 감정을 생생하게 전하고 그 자리에서 되물을 수 있다. 영상은 여러 방법을 어울러 쓰지만, 책은 오래 두고 천천히 읽을 수 있고 라디오는 일하면서도 들을 수 있다. 이렇게 언어와 매체는 하는 일이 달라 더 나은 것은 없다. 그래서 전하려는 내용과 받는 사람의 처지를 보고, 그 자리에 알맞은 방법을 까닭과 함께 고른다.","scoring_points":["언어 사이에 등수가 없는 까닭을 특성으로 설명했는가","매체 사이에 등수가 없는 까닭을 설명했는가","내용과 받는 사람을 보고 까닭과 함께 고른다고 썼는가"]},"explanation":["하는 일이 달라요.","등수가 없어요.","그 자리에 알맞은 것을."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#1','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C1',1,'sa','auto','음성으로 나타내는 말을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"sa","stem":"음성으로 나타내는 말을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["음성언어","음성 언어"],"explanation":["글자로 나타내는 말은 문자 언어예요.","음성으로 나타내는 말은 음성 언어예요.","바로 전해지고 보통 그 자리에서 사라져요."],"mis":"K6-2-u5-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#2','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C2',1,'mc','auto','「말인데 남는 경우」로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X02']::text[],false,'{"seq":2,"concept":"K6-2-u5-C2","difficulty":1,"kind":"mc","stem":"「말인데 남는 경우」로 알맞은 것은 어느 것인가요?","options":[{"t":"소리를 담아 보낸 생일 인사","correct":true},{"t":"빠르게 지나가는 대화 글","mis":"K6-2-u5-X02"},{"t":"화면을 넘기면 없어지는 자막","mis":"K6-2-u5-X02"},{"t":"수업 시간에 선생님이 한 번 하신 말씀","mis":"K6-2-u5-X02"}],"explanation":["대화 글과 자막은 글인데 흘러가요.","한 번 하신 말씀은 지나가요.","소리를 담아 보내면 말인데도 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#3','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C8',1,'mc','auto','영상에서 [말]은 무엇을 가리키나요?',ARRAY['K6-2-u5-X12','K6-2-u5-X05']::text[],false,'{"seq":3,"concept":"K6-2-u5-C8","difficulty":1,"kind":"mc","stem":"영상에서 [말]은 무엇을 가리키나요?","options":[{"t":"해설하는 사람이 하는 말","correct":true},{"t":"화면에 글자로 뜨는 말","mis":"K6-2-u5-X12"},{"t":"배경에 깔리는 효과음","mis":"K6-2-u5-X12"},{"t":"영상을 올린 사람의 이름","mis":"K6-2-u5-X05"}],"explanation":["글자로 뜨는 말은 자막이에요.","효과음은 소리예요.","해설하는 사람의 말이 [말]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#4','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C5',1,'ox','auto','음성 언어는 목소리로 감정과 의도를 함께 전할 수 있어요.',ARRAY['K6-2-u5-X08']::text[],false,'{"seq":4,"concept":"K6-2-u5-C5","difficulty":1,"kind":"ox","stem":"음성 언어는 목소리로 감정과 의도를 함께 전할 수 있어요.","answer":"O","reason_options":[{"t":"목소리의 크기 · 억양 · 속도가 마음을 실어 나르기 때문에","correct":true},{"t":"음성 언어는 글자로 나타내기 때문에","mis":"K6-2-u5-X08"}],"mis":"K6-2-u5-X08","explanation":["밝은 목소리와 가라앉은 목소리는 느낌이 달라요.","억양과 속도도 마음을 전해요.","이것이 음성 언어의 힘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#5','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C13',1,'mc','auto','바닷물이 바다 쪽으로 빠져나가는 것을 무엇이라고 하나요?',ARRAY['K6-2-u5-X18']::text[],false,'{"seq":5,"concept":"K6-2-u5-C13","difficulty":1,"kind":"mc","stem":"바닷물이 바다 쪽으로 빠져나가는 것을 무엇이라고 하나요?","options":[{"t":"썰물","correct":true},{"t":"밀물","mis":"K6-2-u5-X18"},{"t":"퇴적","mis":"K6-2-u5-X18"},{"t":"여울","mis":"K6-2-u5-X18"}],"explanation":["밀려 들어오는 것은 밀물이에요.","쌓이는 일은 퇴적이에요.","빠져나가는 것이 썰물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#6','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C14',1,'ox','auto','같은 내용이라도 누가 읽느냐에 따라 낱말과 차례가 달라져요.',ARRAY['K6-2-u5-X19']::text[],false,'{"seq":6,"concept":"K6-2-u5-C14","difficulty":1,"kind":"ox","stem":"같은 내용이라도 누가 읽느냐에 따라 낱말과 차례가 달라져요.","answer":"O","reason_options":[{"t":"독자가 아는 것과 알아들을 수 있는 말이 다르기 때문에","correct":true},{"t":"글은 누가 읽든 똑같이 써야 하기 때문에","mis":"K6-2-u5-X19"}],"mis":"K6-2-u5-X19","explanation":["독자마다 배경지식과 수준이 달라요.","그래서 낱말과 차례를 맞춰요.","이것이 독자를 고려하는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#7','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C18',1,'ox','auto','기사문은 느낌이 아니라 사실을 쓰는 글이에요.',ARRAY['K6-2-u5-X26']::text[],false,'{"seq":7,"concept":"K6-2-u5-C18","difficulty":1,"kind":"ox","stem":"기사문은 느낌이 아니라 사실을 쓰는 글이에요.","answer":"O","reason_options":[{"t":"여러 사람에게 사실이나 사건을 알리는 글이기 때문에","correct":true},{"t":"기사문은 재미있게 꾸며 쓰는 글이기 때문에","mis":"K6-2-u5-X26"}],"mis":"K6-2-u5-X26","explanation":["기사문은 사실을 알려요.","직접 보고 듣고 조사한 것을 써요.","느낌을 사실처럼 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#8','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C25',1,'mc','auto','「얇다」는 어떻게 소리 나나요?',ARRAY['K6-2-u5-X39','K6-2-u5-X38']::text[],false,'{"seq":8,"concept":"K6-2-u5-C25","difficulty":1,"kind":"mc","stem":"「얇다」는 어떻게 소리 나나요?","options":[{"t":"[얄따]","correct":true},{"t":"[얍따]","mis":"K6-2-u5-X39"},{"t":"[얇따]","mis":"K6-2-u5-X38"},{"t":"[야르따]","mis":"K6-2-u5-X39"}],"explanation":["뒤에 자음자가 오면 하나만 소리 나요.","얇다는 ㄹ 소리가 나요.","그래서 [얄따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#9','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C5',2,'mc','auto','은솔이가 비 오는 날의 도시락을 물어 바로 답을 들을 수 있었던 까닭은 어느 것인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X09','K6-2-u5-X06']::text[],false,'{"seq":9,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"은솔이가 비 오는 날의 도시락을 물어 바로 답을 들을 수 있었던 까닭은 어느 것인가요?","options":[{"t":"음성 언어는 모르는 곳을 그 자리에서 되물을 수 있어서","correct":true},{"t":"글로 적힌 안내를 다시 읽어서","mis":"K6-2-u5-X01"},{"t":"은솔이가 기억력이 좋아서","mis":"K6-2-u5-X09"},{"t":"선생님 목소리가 커서","mis":"K6-2-u5-X06"}],"explanation":["은솔이는 그 자리에서 물었어요.","선생님이 바로 답해 주셨어요.","되묻기는 말의 특성이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#10','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C9',2,'error','auto','선생님의 안내 방법에 대해 말했어요. 까닭 없이 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X09']::text[],false,'{"seq":10,"concept":"K6-2-u5-C9","difficulty":2,"kind":"error","stem":"선생님의 안내 방법에 대해 말했어요. 까닭 없이 말한 친구는 누구인가요?","options":[{"t":"현우 — 「글로 써야 해. 글이 좋으니까.」","correct":true,"mis_target":"K6-2-u5-X09"},{"t":"예나 — 「챙길 것이 넷이라 글로 적어 두면 집에서 다시 볼 수 있어.」","mis":"K6-2-u5-X09"},{"t":"준기 — 「말로 해 주셔서 은솔이가 바로 물어볼 수 있었어.」","mis":"K6-2-u5-X09"}],"explanation":["예나와 준기는 언어의 특성과 이어 말했어요.","현우는 까닭 없이 좋다고만 했어요.","고른 까닭까지 말해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#11','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C9',2,'mc','auto','장면 이에서 「헹구기 → 펼치기 → 말리기」를 자막으로도 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X11','K6-2-u5-X12']::text[],false,'{"seq":11,"concept":"K6-2-u5-C9","difficulty":2,"kind":"mc","stem":"장면 이에서 「헹구기 → 펼치기 → 말리기」를 자막으로도 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해야 할 차례를 눈으로 다시 확인하게 하려고","correct":true},{"t":"화면을 글자로 가득 채우려고","mis":"K6-2-u5-X13"},{"t":"말을 하지 않아도 되게 하려고","mis":"K6-2-u5-X11"},{"t":"음악을 대신하려고","mis":"K6-2-u5-X12"}],"explanation":["차례는 말로만 하면 놓치기 쉬워요.","자막은 남아 있어요.","말과 자막이 서로 보완해요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#12','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C12',2,'mc','auto','이 영상을 보고 감상을 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u5-X15','K6-2-u5-X16']::text[],false,'{"seq":12,"concept":"K6-2-u5-C12","difficulty":2,"kind":"mc","stem":"이 영상을 보고 감상을 알맞게 말한 것은 어느 것인가요?","options":[{"t":"장면 이에서 자막으로 차례를 보여 줘서 따라 하기 쉬웠다","correct":true},{"t":"그냥 좋았다","mis":"K6-2-u5-X15"},{"t":"별로였다. 재미없었다","mis":"K6-2-u5-X15"},{"t":"장면 삼이 좋았다는 친구는 잘못 본 것이다","mis":"K6-2-u5-X16"}],"explanation":["느낌만 말하면 까닭이 없어요.","다른 느낌이 틀린 것은 아니에요.","어떤 표현 때문인지 함께 말해요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#13','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C21',2,'mc','auto','하은이 기사문의 표제에 대한 평가로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X31','K6-2-u5-X28']::text[],false,'{"seq":13,"concept":"K6-2-u5-C21","difficulty":2,"kind":"mc","stem":"하은이 기사문의 표제에 대한 평가로 알맞은 것은 어느 것인가요?","options":[{"t":"「완전히 바뀌었다」 · 「온 학교가 환호」는 본문에서 확인되지 않아 부풀린 제목이다","correct":true},{"t":"놀라운 말이 많아 읽고 싶어지니 잘 쓴 제목이다","mis":"K6-2-u5-X31"},{"t":"제목은 아무렇게나 써도 된다","mis":"K6-2-u5-X31"},{"t":"표제가 있으니 부제도 꼭 붙여야 한다","mis":"K6-2-u5-X28"}],"explanation":["제목은 내용을 담아야 해요.","본문에 없는 말을 넣으면 안 돼요.","부풀리지 않아요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#14','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C20',2,'error','auto','하은이 기사문의 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?',ARRAY['K6-2-u5-X27','K6-2-u5-X26']::text[],false,'{"seq":14,"concept":"K6-2-u5-C20","difficulty":2,"kind":"error","stem":"하은이 기사문의 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"다올 — 「‘백 명도 넘게’를 ‘이백 명쯤’으로 바꾸면 더 정확해.」","correct":true,"mis_target":"K6-2-u5-X27"},{"t":"세빈 — 「점심시간에 직접 세어 본 수로 바꾸고, 언제 셌는지 밝혀.」","mis":"K6-2-u5-X27"},{"t":"주하 — 「‘다치는 학생이 없을 것’은 확인할 수 없으니 빼.」","mis":"K6-2-u5-X26"}],"explanation":["세빈과 주하는 확인한 사실로 고쳤어요.","다올은 또 다른 수를 지어냈어요.","숫자는 세어 보거나 물어본 것만 써요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#15','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C22',2,'mc','auto','준서의 편지에서 받는 사람을 고려하지 않은 점은 어느 것인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X37']::text[],false,'{"seq":15,"concept":"K6-2-u5-C22","difficulty":2,"kind":"mc","stem":"준서의 편지에서 받는 사람을 고려하지 않은 점은 어느 것인가요?","options":[{"t":"웃어른인 할머니께 높임말을 쓰지 않았다","correct":true},{"t":"편지가 너무 짧다","mis":"K6-2-u5-X22"},{"t":"글씨를 예쁘게 쓰지 않았다","mis":"K6-2-u5-X22"},{"t":"편지지를 꾸미지 않았다","mis":"K6-2-u5-X37"}],"explanation":["길이나 꾸밈은 기준이 아니에요.","받는 사람은 할머니예요.","알맞은 높임말을 써야 해요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#16','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C4',2,'mc','auto','장면 ㉯가 장면 ㉮보다 나은 점은 어느 것인가요?',ARRAY['K6-2-u5-X08','K6-2-u5-X03']::text[],false,'{"seq":16,"concept":"K6-2-u5-C4","difficulty":2,"kind":"mc","stem":"장면 ㉯가 장면 ㉮보다 나은 점은 어느 것인가요?","options":[{"t":"반 친구 모두가 똑같은 내용을 다시 볼 수 있다","correct":true},{"t":"들뜬 마음이 목소리로 생생하게 전해진다","mis":"K6-2-u5-X08"},{"t":"시율이가 그 자리에서 되물을 수 있다","mis":"K6-2-u5-X08"},{"t":"글이 말보다 언제나 좋은 언어다","mis":"K6-2-u5-X03"}],"explanation":["들뜬 목소리와 되묻기는 ㉮의 장점이에요.","㉯는 글로 남아요.","더 좋은 언어가 아니라 알맞은 곳이 달라요."],"asset":{"type":"passage","lines":["장면 ㉮ 도아가 시율이를 만나 직접 말로 내일 준비물을 알려 준다.","목소리가 밝고 빠르다.","장면 ㉯ 도아가 학급 게시판에 글로 적어 내일 준비물을 알린다.","중요한 것에 굵은 글씨를 썼다."],"title":"같은 내용, 다른 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#17','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C2',3,'error','auto','은솔이네 반 상황을 보고 말했어요. 이 단원의 약속과 다르게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X08']::text[],false,'{"seq":17,"concept":"K6-2-u5-C2","difficulty":3,"kind":"error","stem":"은솔이네 반 상황을 보고 말했어요. 이 단원의 약속과 다르게 말한 친구는 누구인가요?","options":[{"t":"라희 — 「말은 언제나 잊어버리니까 중요한 건 절대 말로 하면 안 돼.」","correct":true,"mis_target":"K6-2-u5-X02"},{"t":"도윤 — 「말로 해서 은솔이가 바로 물어볼 수 있었어.」","mis":"K6-2-u5-X08"},{"t":"채원 — 「녹음해 두면 말도 다시 들을 수 있어.」","mis":"K6-2-u5-X02"}],"explanation":["도윤과 채원은 바르게 말했어요.","라희는 「언제나」 · 「절대」로 규칙을 만들었어요.","특성은 기본 성질이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#18','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C11',3,'mc','auto','장면 일에서 조용한 음악을 깔고 자막으로 제목만 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X14','K6-2-u5-X12','K6-2-u5-X13']::text[],false,'{"seq":18,"concept":"K6-2-u5-C11","difficulty":3,"kind":"mc","stem":"장면 일에서 조용한 음악을 깔고 자막으로 제목만 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"무엇을 다룰 영상인지 차분히 먼저 알리려고","correct":true},{"t":"만들 시간이 모자라서","mis":"K6-2-u5-X14"},{"t":"생물이 사는 곳이라는 느낌을 살리려고","mis":"K6-2-u5-X12"},{"t":"자막은 많을수록 좋아서","mis":"K6-2-u5-X13"}],"explanation":["첫 장면은 다룰 것을 알려요.","조용한 음악은 집중하게 해요.","장면마다 해야 할 일이 달라요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#19','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C20',3,'mc','auto','하은이 기사문에서 「쉬는 시간마다 백 명도 넘게 온다고 한다」를 고치려면 무엇을 해야 하나요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27']::text[],false,'{"seq":19,"concept":"K6-2-u5-C20","difficulty":3,"kind":"mc","stem":"하은이 기사문에서 「쉬는 시간마다 백 명도 넘게 온다고 한다」를 고치려면 무엇을 해야 하나요?","options":[{"t":"쉬는 시간에 직접 세어 보고, 언제 몇 번 셌는지 함께 쓴다","correct":true},{"t":"「아주 많이 온다」로 바꾼다","mis":"K6-2-u5-X26"},{"t":"「이백 명」으로 늘려 쓴다","mis":"K6-2-u5-X27"},{"t":"그대로 둔다. 들은 말이니까","mis":"K6-2-u5-X27"}],"explanation":["「~한다고 한다」는 누가 셌는지 몰라요.","숫자를 바꾸어도 지어낸 수예요.","직접 세어 보고 출처를 밝혀요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#20','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C22',3,'mc','auto','준서가 「그때 같이 그거 또 하자」를 고쳐 쓸 때 생각할 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X34','K6-2-u5-X36','K6-2-u5-X33']::text[],false,'{"seq":20,"concept":"K6-2-u5-C22","difficulty":3,"kind":"mc","stem":"준서가 「그때 같이 그거 또 하자」를 고쳐 쓸 때 생각할 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니가 무엇인지 알 수 있게 그 일을 밝히고 높임말로 여쭌다","correct":true},{"t":"그대로 둔다. 할머니는 다 아신다","mis":"K6-2-u5-X34"},{"t":"「그거」를 「그것」으로만 바꾼다","mis":"K6-2-u5-X36"},{"t":"문장을 지운다","mis":"K6-2-u5-X33"}],"explanation":["받는 사람이 헷갈리지 않게 밝혀요.","웃어른께는 높임말로 여쭈어요.","받는 사람을 떠올려요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#21','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C16',3,'error','auto','글 쓰는 과정에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X21','K6-2-u5-X22']::text[],false,'{"seq":21,"concept":"K6-2-u5-C16","difficulty":3,"kind":"error","stem":"글 쓰는 과정에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세온 — 「독자는 계획 세울 때 한 번 생각했으면 고쳐 쓸 때는 안 봐도 돼.」","correct":true,"mis_target":"K6-2-u5-X21"},{"t":"하빈 — 「고쳐 쓸 때 독자가 오해할 만한 표현이 없는지 다시 읽어.」","mis":"K6-2-u5-X22"},{"t":"준우 — 「쓸 거리를 모을 때도 독자가 궁금해할 것을 떠올려.」","mis":"K6-2-u5-X21"}],"explanation":["하빈과 준우는 단계마다 독자를 떠올렸어요.","세온은 처음에만 독자를 생각했어요.","세 단계마다 독자를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#22','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C16',3,'ox','auto','「앞으로 열심히 하겠다」는 지키기 좋은 실천 다짐이에요.',ARRAY['K6-2-u5-X40']::text[],false,'{"seq":22,"concept":"K6-2-u5-C16","difficulty":3,"kind":"ox","stem":"「앞으로 열심히 하겠다」는 지키기 좋은 실천 다짐이에요.","answer":"X","reason_options":[{"t":"언제 · 어디에서 · 무엇을 할지가 없어 막연하기 때문에","correct":true},{"t":"열심히라는 말이 들어가면 다짐이 크기 때문에","mis":"K6-2-u5-X40"}],"mis":"K6-2-u5-X40","explanation":["막연한 다짐은 지키기 어려워요.","언제 · 어디에서 · 무엇을 할지 정해요.","한 문장으로 구체적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#23','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C12',4,'mc','auto','「한 번 더 헹궈요」를 세 걸음으로 감상한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X05','K6-2-u5-X13','K6-2-u5-X15']::text[],false,'{"seq":23,"concept":"K6-2-u5-C12","difficulty":4,"kind":"mc","stem":"「한 번 더 헹궈요」를 세 걸음으로 감상한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"찾기 — 장면 이에 말과 차례 자막 / 잇기 — 자막이 차례를 붙들어 줌 / 말하기 — 그래서 따라 하기 쉽다고 느꼈다","correct":true},{"t":"찾기 — 영상 길이 / 잇기 — 짧아서 좋음 / 말하기 — 재미있었다","mis":"K6-2-u5-X05"},{"t":"찾기 — 장면 삼 / 잇기 — 요소가 많음 / 말하기 — 많아서 최고다","mis":"K6-2-u5-X13"},{"t":"말하기 — 별로였다 / 찾기와 잇기는 하지 않음","mis":"K6-2-u5-X15"}],"explanation":["영상 안의 요소를 찾아요.","무엇을 돕는지 이어요.","느낌과 까닭을 함께 말해요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#24','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C10',4,'essay','teacher','「한 번 더 헹궈요」 영상에서 표현 효과가 있는 장면과 고칠 장면을 하나씩 골라 까닭을 쓰고, 고칠 장면을 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u5-C10","difficulty":4,"kind":"essay","stem":"「한 번 더 헹궈요」 영상에서 표현 효과가 있는 장면과 고칠 장면을 하나씩 골라 까닭을 쓰고, 고칠 장면을 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 표현 효과가 있는 장면 — 장면 이. 해설하는 말로 방법을 알려 주고 「헹구기 → 펼치기 → 말리기」 자막으로 차례를 붙들어 두어 따라 하기 쉽다. 고칠 장면 — 장면 삼. 자막이 화면 가득하고 큰 음악과 빠른 장면이 계속되어 무엇이 중요한지 흐려진다. 고칠 방법 — 헹군 우유갑 하나를 오래 보여 주고, 자막은 「종이 칸에!」 하나만 두고, 그 순간 음악을 낮춘다.","scoring_points":["표현 효과가 있는 장면과 까닭을 썼는가","고칠 장면과 문제를 썼는가","무엇을 돕는가를 기준으로 고칠 방법을 썼는가"]},"explanation":["좋은 장면 먼저.","개수가 아니라 돕는가.","고칠 방법까지."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#25','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C14',4,'essay','teacher','독자를 고려해 글을 쓰는 방법을 쓰기 전 · 쓰는 중 · 쓴 뒤로 나누어 쓰고, 독자를 고려하는 것이 비위를 맞추는 것과 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u5-C14","difficulty":4,"kind":"essay","stem":"독자를 고려해 글을 쓰는 방법을 쓰기 전 · 쓰는 중 · 쓴 뒤로 나누어 쓰고, 독자를 고려하는 것이 비위를 맞추는 것과 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 쓰기 전에는 독자의 흥미 · 배경지식 · 수준 · 매체와 독자가 겪는 어려움을 알아본다. 쓰는 중에는 독자가 관심을 가질 내용을 모아 알아듣기 쉬운 차례로 짜고 필요하면 자료를 넣는다. 쓴 뒤에는 독자 수준에 맞는지, 오해할 표현이 없는지 다시 읽고 고친다. 비위 맞추기는 좋아할 것만 고르거나 어려운 내용을 빼는 것이지만, 독자 고려는 전하려는 것은 그대로 두고 독자에게 닿게 하는 것이다.","scoring_points":["세 단계마다 독자를 고려하는 방법을 썼는가","자료와 고쳐 쓰기를 독자와 이었는가","비위 맞추기와의 차이를 썼는가"]},"explanation":["단계마다 독자.","자료는 이해를 돕게.","전하려는 것은 그대로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#1','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C1',1,'ox','auto','학급 게시판에 적은 안내 글은 문자 언어예요.',ARRAY['K6-2-u5-X01']::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"ox","stem":"학급 게시판에 적은 안내 글은 문자 언어예요.","answer":"O","reason_options":[{"t":"글자로 나타낸 말이기 때문에","correct":true},{"t":"선생님이 말로 하신 내용을 옮겼으니 음성 언어이기 때문에","mis":"K6-2-u5-X01"}],"mis":"K6-2-u5-X01","explanation":["말로 한 내용이라도 글자로 적으면 문자 언어예요.","게시판 안내는 글자로 되어 있어요.","그래서 문자 언어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#2','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C3',1,'mc','auto','이 단원의 약속으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X03']::text[],false,'{"seq":2,"concept":"K6-2-u5-C3","difficulty":1,"kind":"mc","stem":"이 단원의 약속으로 알맞은 것은 어느 것인가요?","options":[{"t":"더 나은 언어나 매체는 없고 그 자리에 알맞은 것이 있다","correct":true},{"t":"글이 말보다 나은 언어다","mis":"K6-2-u5-X03"},{"t":"영상이 가장 좋은 매체다","mis":"K6-2-u5-X03"},{"t":"남는 쪽이 언제나 더 좋은 방법이다","mis":"K6-2-u5-X03"}],"explanation":["언어에 등수가 없어요.","매체에도 등수가 없어요.","그 자리에 알맞은 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#3','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C8',1,'ox','auto','화면의 크기도 매체 자료가 뜻을 나르는 방법이에요.',ARRAY['K6-2-u5-X05']::text[],false,'{"seq":3,"concept":"K6-2-u5-C8","difficulty":1,"kind":"ox","stem":"화면의 크기도 매체 자료가 뜻을 나르는 방법이에요.","answer":"X","reason_options":[{"t":"화면 크기는 내용의 뜻을 나르지 않기 때문에","correct":true},{"t":"화면이 클수록 뜻이 잘 전해지기 때문에","mis":"K6-2-u5-X05"}],"mis":"K6-2-u5-X05","explanation":["뜻을 나르는 것은 말 · 자막 · 장면 · 소리예요.","화면 크기는 보는 기계의 일이에요.","뜻을 나르는 것만 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#4','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C5',1,'mc','auto','음성 언어의 특성이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X08']::text[],false,'{"seq":4,"concept":"K6-2-u5-C5","difficulty":1,"kind":"mc","stem":"음성 언어의 특성이 아닌 것은 어느 것인가요?","options":[{"t":"적은 내용을 여러 사람이 똑같이 나누어 가진다","correct":true},{"t":"그 자리에서 바로 전해진다","mis":"K6-2-u5-X08"},{"t":"모르는 곳을 그 자리에서 되물을 수 있다","mis":"K6-2-u5-X08"},{"t":"듣는 사람의 반응을 보며 말을 바꾼다","mis":"K6-2-u5-X08"}],"explanation":["바로 전해지고, 되묻고, 반응을 보는 것은 말의 특성이에요.","똑같이 나누어 갖는 것은 글의 특성이에요.","두 특성을 갈라 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#5','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C11',1,'ox','auto','영상에서 음악의 빠르기를 바꾸는 것은 느낌을 바꾸려고 쓰는 방법이에요.',ARRAY['K6-2-u5-X14']::text[],false,'{"seq":5,"concept":"K6-2-u5-C11","difficulty":1,"kind":"ox","stem":"영상에서 음악의 빠르기를 바꾸는 것은 느낌을 바꾸려고 쓰는 방법이에요.","answer":"O","reason_options":[{"t":"장면에서 해야 할 일에 맞추어 방법을 고르기 때문에","correct":true},{"t":"음악은 아무 때나 바꾸는 것이기 때문에","mis":"K6-2-u5-X14"}],"mis":"K6-2-u5-X14","explanation":["밝고 빠른 음악은 활기찬 느낌을 줘요.","느낌을 바꿀 때 음악을 바꿔요.","방법마다 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#6','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C17',1,'mc','auto','할 일을 나누어 보여 줄 때 쓰면 좋은 것은 어느 것인가요?',ARRAY['K6-2-u5-X23','K6-2-u5-X25']::text[],false,'{"seq":6,"concept":"K6-2-u5-C17","difficulty":1,"kind":"mc","stem":"할 일을 나누어 보여 줄 때 쓰면 좋은 것은 어느 것인가요?","options":[{"t":"기호와 줄 나눔","correct":true},{"t":"그래프","mis":"K6-2-u5-X23"},{"t":"사진","mis":"K6-2-u5-X23"},{"t":"긴 문단 하나","mis":"K6-2-u5-X25"}],"explanation":["그래프는 수를 견줄 때 좋아요.","사진은 모습을 보여 줄 때 좋아요.","할 일은 기호와 줄 나눔으로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#7','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C19',1,'sa','auto','누가 · 언제 · 어디에서 · 무엇을 · 어떻게 · 왜를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C19","difficulty":1,"kind":"sa","stem":"누가 · 언제 · 어디에서 · 무엇을 · 어떻게 · 왜를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["육하원칙"],"explanation":["여섯 가지 물음이에요.","전문은 이것으로 요약해요.","이것을 육하원칙이라고 해요."],"mis":"K6-2-u5-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#8','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C25',1,'ox','auto','「늙어요」는 [늘거요]로 소리 나요.',ARRAY['K6-2-u5-X38']::text[],false,'{"seq":8,"concept":"K6-2-u5-C25","difficulty":1,"kind":"ox","stem":"「늙어요」는 [늘거요]로 소리 나요.","answer":"O","reason_options":[{"t":"뒤에 모음이 와서 두 소리가 다 나고 ㄱ이 뒷글자로 넘어가기 때문에","correct":true},{"t":"겹받침은 언제나 하나만 소리 나기 때문에","mis":"K6-2-u5-X38"}],"mis":"K6-2-u5-X38","explanation":["늙다는 [늑따]예요.","늙어요는 뒤에 모음이 와요.","ㄱ이 넘어가 [늘거요]가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#9','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C6',2,'ox','auto','선생님의 안내는 말로만 했으니 충분해요.',ARRAY['K6-2-u5-X10']::text[],false,'{"seq":9,"concept":"K6-2-u5-C6","difficulty":2,"kind":"ox","stem":"선생님의 안내는 말로만 했으니 충분해요.","answer":"X","reason_options":[{"t":"모일 시각과 챙길 것이 여럿이라 다시 볼 수 있게 글로도 적어 두면 좋기 때문에","correct":true},{"t":"말은 언제나 정확히 기억되기 때문에","mis":"K6-2-u5-X10"}],"mis":"K6-2-u5-X10","explanation":["챙길 것이 넷이나 되고 시각도 있어요.","지안이처럼 놓친 사람이 생겨요.","글로도 적어 두면 다시 볼 수 있어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#10','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C7',2,'ox','auto','은솔이네 반처럼 챙길 것이 많을 때에는 말과 글을 함께 쓰는 것이 좋아요.',ARRAY['K6-2-u5-X11']::text[],false,'{"seq":10,"concept":"K6-2-u5-C7","difficulty":2,"kind":"ox","stem":"은솔이네 반처럼 챙길 것이 많을 때에는 말과 글을 함께 쓰는 것이 좋아요.","answer":"O","reason_options":[{"t":"말로 놓친 것을 글로 다시 확인할 수 있기 때문에","correct":true},{"t":"같은 내용을 두 번 하면 겹쳐서 쓸모없기 때문에","mis":"K6-2-u5-X11"}],"mis":"K6-2-u5-X11","explanation":["말은 생생하지만 놓칠 수 있어요.","글은 남아요.","함께 쓰면 서로 보완해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#11','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C10',2,'mc','auto','장면 삼의 문제점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X04']::text[],false,'{"seq":11,"concept":"K6-2-u5-C10","difficulty":2,"kind":"mc","stem":"장면 삼의 문제점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자막을 화면 가득 채우고 큰 음악과 빠른 장면을 계속 써서 무엇이 중요한지 흐려졌다","correct":true},{"t":"자막이 많아서 가장 잘 만든 장면이다","mis":"K6-2-u5-X13"},{"t":"음악이 있어서 문제가 없다","mis":"K6-2-u5-X13"},{"t":"말이 없으니 영상이 아니다","mis":"K6-2-u5-X04"}],"explanation":["요소가 많다고 잘 전해지지 않아요.","어디를 봐야 할지 흐려져요.","표현 효과는 무엇을 돕는가로 봐요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#12','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C10',2,'error','auto','장면 삼을 고치는 방법을 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X10']::text[],false,'{"seq":12,"concept":"K6-2-u5-C10","difficulty":2,"kind":"error","stem":"장면 삼을 고치는 방법을 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"소율 — 「자막을 더 많이 넣고 음악도 더 크게 하면 돼.」","correct":true,"mis_target":"K6-2-u5-X13"},{"t":"이준 — 「종이 하나만 오래 보여 주고 자막은 꼭 남길 말만 두면 돼.」","mis":"K6-2-u5-X10"},{"t":"하린 — 「중요한 곳에서 음악을 바꾸면 눈길이 모여.」","mis":"K6-2-u5-X10"}],"explanation":["이준과 하린은 무엇을 도울지 생각했어요.","소율은 개수만 늘렸어요.","많이 넣는다고 잘 전해지지 않아요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#13','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C20',2,'ox','auto','하은이가 「다음 달에 놀이 기구가 새로 들어온다는 소문」을 기사문에 쓴 것은 알맞아요.',ARRAY['K6-2-u5-X27']::text[],false,'{"seq":13,"concept":"K6-2-u5-C20","difficulty":2,"kind":"ox","stem":"하은이가 「다음 달에 놀이 기구가 새로 들어온다는 소문」을 기사문에 쓴 것은 알맞아요.","answer":"X","reason_options":[{"t":"확인하지 못한 소문은 기사문에 쓰지 않기 때문에","correct":true},{"t":"소문도 많은 사람이 알면 좋기 때문에","mis":"K6-2-u5-X27"}],"mis":"K6-2-u5-X27","explanation":["옆 반 친구 말을 들었을 뿐이에요.","누구에게 확인한 것이 아니에요.","확인하지 못한 것은 쓰지 않아요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#14','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C20',2,'ox','auto','「아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다」는 기사문에 알맞은 문장이에요.',ARRAY['K6-2-u5-X26']::text[],false,'{"seq":14,"concept":"K6-2-u5-C20","difficulty":2,"kind":"ox","stem":"「아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다」는 기사문에 알맞은 문장이에요.","answer":"X","reason_options":[{"t":"확인할 수 없는 쓴 사람의 짐작이기 때문에","correct":true},{"t":"좋은 일을 알리는 문장이기 때문에","mis":"K6-2-u5-X26"}],"mis":"K6-2-u5-X26","explanation":["「아마 ~ 것이다」는 짐작이에요.","누구도 다시 확인할 수 없어요.","생각을 사실처럼 쓰지 않아요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#15','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C23',2,'ox','auto','준서의 「저번에 그거 진짜 고마웠어」는 고마운 마음이 잘 닿는 문장이에요.',ARRAY['K6-2-u5-X36']::text[],false,'{"seq":15,"concept":"K6-2-u5-C23","difficulty":2,"kind":"ox","stem":"준서의 「저번에 그거 진짜 고마웠어」는 고마운 마음이 잘 닿는 문장이에요.","answer":"X","reason_options":[{"t":"무엇이 고마웠는지 콕 집어 쓰지 않아 막연하기 때문에","correct":true},{"t":"「진짜」를 넣어 아주 고마워 보이기 때문에","mis":"K6-2-u5-X36"}],"mis":"K6-2-u5-X36","explanation":["「그거」가 무엇인지 알 수 없어요.","할머니도 무슨 일인지 헷갈릴 수 있어요.","고마운 일을 콕 집어 써요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#16','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C25',2,'match','auto','낱말과 소리를 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"K6-2-u5-C25","difficulty":2,"kind":"match","stem":"낱말과 소리를 알맞게 이으세요.","pairs":[{"l":"붉어요","r":"[불거요]"},{"l":"짧아요","r":"[짤바요]"},{"l":"늙다","r":"[늑따]"}],"mis":"K6-2-u5-X38","explanation":["붉어요 · 짧아요는 뒤에 모음이 와 두 소리가 다 나요.","늙다는 뒤에 자음자가 와 하나만 나요.","뒤에 오는 것을 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#17','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C7',3,'mc','auto','선생님이 다음 날 아침 다시 알릴 때 가장 알맞은 방법과 까닭은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X10','K6-2-u5-X03']::text[],false,'{"seq":17,"concept":"K6-2-u5-C7","difficulty":3,"kind":"mc","stem":"선생님이 다음 날 아침 다시 알릴 때 가장 알맞은 방법과 까닭은 어느 것인가요?","options":[{"t":"칠판에 시각과 챙길 것을 적어 두고 말로도 짚어 준다 — 놓친 것을 글로 확인하고 궁금한 것은 말로 물을 수 있으니까","correct":true},{"t":"어제 말했으니 다시 알리지 않는다 — 한 번 말한 것은 모두 기억하니까","mis":"K6-2-u5-X02"},{"t":"방송으로 크게 한 번 더 말한다 — 크면 잊지 않으니까","mis":"K6-2-u5-X10"},{"t":"글로만 적는다 — 글이 말보다 낫니까","mis":"K6-2-u5-X03"}],"explanation":["놓친 친구가 있었어요.","글은 남고 말은 물을 수 있어요.","둘을 함께 쓰면 서로 보완해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#18','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C12',3,'error','auto','「한 번 더 헹궈요」를 감상했어요. 까닭 없이 느낌만 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X15']::text[],false,'{"seq":18,"concept":"K6-2-u5-C12","difficulty":3,"kind":"error","stem":"「한 번 더 헹궈요」를 감상했어요. 까닭 없이 느낌만 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「장면 사가 제일 좋았어. 그냥.」","correct":true,"mis_target":"K6-2-u5-X15"},{"t":"서아 — 「장면 사에서 아이가 웃는 장면과 짧은 말 때문에 나도 해 보고 싶었어.」","mis":"K6-2-u5-X15"},{"t":"민호 — 「장면 이의 자막 덕분에 차례를 잊지 않았어.」","mis":"K6-2-u5-X15"}],"explanation":["서아와 민호는 표현과 느낌을 이었어요.","태윤은 까닭이 없어요.","어떤 표현 때문인지 함께 말해요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#19','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C19',3,'error','auto','하은이 기사문의 전문을 육하원칙으로 고치려고 해요. 잘못 짝 지은 친구는 누구인가요?',ARRAY['K6-2-u5-X29']::text[],false,'{"seq":19,"concept":"K6-2-u5-C19","difficulty":3,"kind":"error","stem":"하은이 기사문의 전문을 육하원칙으로 고치려고 해요. 잘못 짝 지은 친구는 누구인가요?","options":[{"t":"하나 — 「‘왜’ — 운동장 동쪽에」","correct":true,"mis_target":"K6-2-u5-X29"},{"t":"지훈 — 「‘언제’ — 이번 달부터」","mis":"K6-2-u5-X29"},{"t":"수빈 — 「‘무엇을’ — 공 놀이 구역을」","mis":"K6-2-u5-X29"}],"explanation":["지훈과 수빈은 바르게 짝 지었어요.","「운동장 동쪽에」는 어디에서예요.","여섯 물음에 맞게 나눠요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#20','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C24',3,'mc','auto','준서가 할머니께 편지를 전할 매체를 고를 때 가장 알맞게 생각한 것은 어느 것인가요?',ARRAY['K6-2-u5-X10','K6-2-u5-X03','K6-2-u5-X37']::text[],false,'{"seq":20,"concept":"K6-2-u5-C24","difficulty":3,"kind":"mc","stem":"준서가 할머니께 편지를 전할 매체를 고를 때 가장 알맞게 생각한 것은 어느 것인가요?","options":[{"t":"할머니가 두고두고 읽으실 수 있게 손 편지로 써서 방학 때 직접 건넨다","correct":true},{"t":"가장 빨리 보낼 수 있는 짧은 문자로 보낸다","mis":"K6-2-u5-X10"},{"t":"영상이 언제나 더 좋으니 영상으로 만든다","mis":"K6-2-u5-X03"},{"t":"예쁘게 꾸미는 데 시간을 다 쓰고 내용은 줄인다","mis":"K6-2-u5-X37"}],"explanation":["마음과 받는 사람의 처지를 봐요.","매체에 등수는 없어요.","건네고 반응을 들으면 완성이에요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#21','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C17',3,'mc','auto','「우리 반 아침 독서 시간에 읽은 책 수가 달마다 늘었다」를 알릴 때 가장 알맞은 자료는 어느 것인가요?',ARRAY['K6-2-u5-X23','K6-2-u5-X13','K6-2-u5-X25']::text[],false,'{"seq":21,"concept":"K6-2-u5-C17","difficulty":3,"kind":"mc","stem":"「우리 반 아침 독서 시간에 읽은 책 수가 달마다 늘었다」를 알릴 때 가장 알맞은 자료는 어느 것인가요?","options":[{"t":"달마다 읽은 책 수를 견주는 그래프","correct":true},{"t":"책 표지 사진 여러 장","mis":"K6-2-u5-X23"},{"t":"화려한 꾸밈 그림","mis":"K6-2-u5-X13"},{"t":"자료 없이 「많이 늘었다」만 쓰기","mis":"K6-2-u5-X25"}],"explanation":["수의 변화를 보여 줘야 해요.","견줄 때는 표나 그래프가 좋아요.","자료는 글과 이어져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#22','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C16',3,'mc','auto','배운 것을 실천하는 다짐으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X40']::text[],false,'{"seq":22,"concept":"K6-2-u5-C16","difficulty":3,"kind":"mc","stem":"배운 것을 실천하는 다짐으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「다음 주 학급 알림 글을 쓸 때, 읽을 사람이 할 일을 기호로 나누어 적겠다.」","correct":true},{"t":"「앞으로 글을 열심히 잘 쓰겠다.」","mis":"K6-2-u5-X40"},{"t":"「다들 독자를 생각합시다.」","mis":"K6-2-u5-X40"},{"t":"「매일매일 모든 글을 완벽하게 쓰겠다.」","mis":"K6-2-u5-X40"}],"explanation":["언제 · 어디에서 · 무엇을이 보여요.","내가 할 일이에요.","지킬 수 있는 크기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#23','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C18',4,'mc','auto','하은이 기사문을 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X31','K6-2-u5-X32','K6-2-u5-X30']::text[],false,'{"seq":23,"concept":"K6-2-u5-C18","difficulty":4,"kind":"mc","stem":"하은이 기사문을 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기삿거리는 알맞지만, 제목이 부풀려졌고 전문에 느낌을 썼으며, 소문 · 지어낸 수 · 짐작이 사실처럼 들어갔고 자료 출처가 없다","correct":true},{"t":"흥미로운 말이 많아 잘 쓴 기사문이다","mis":"K6-2-u5-X31"},{"t":"사진이 있으니 믿을 만한 기사문이다","mis":"K6-2-u5-X32"},{"t":"운동장 이야기라서 기사문이 될 수 없다","mis":"K6-2-u5-X30"}],"explanation":["잘된 점을 먼저 짚어요.","사실 · 제목 · 출처를 하나씩 봐요.","고칠 곳을 정확히 짚어요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#24','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C20',4,'essay','teacher','하은이 기사문에서 고쳐야 할 곳을 세 가지 찾아 왜 고쳐야 하는지 쓰고, 표제와 전문을 고쳐 쓰세요. 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u5-C20","difficulty":4,"kind":"essay","stem":"하은이 기사문에서 고쳐야 할 곳을 세 가지 찾아 왜 고쳐야 하는지 쓰고, 표제와 전문을 고쳐 쓰세요. 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 첫째, 「온 학교가 환호」는 본문에서 확인되지 않아 부풀린 제목이다. 둘째, 「백 명도 넘게 온다고 한다」는 세어 보지 않은 수이고, 놀이 기구 이야기는 확인하지 못한 소문이다. 셋째, 「다치는 학생이 하나도 없을 것」은 쓴 사람의 짐작이다. 또 사진의 출처가 없다. 고친 표제 — 운동장에 쉬는 시간 공 놀이 구역 생겨. 고친 전문 — 이번 달부터 운동장 동쪽에 쉬는 시간 공 놀이 구역이 선을 그어 마련되었다.","scoring_points":["고칠 곳을 세 가지 바르게 찾았는가","사실 · 확인 · 출처를 기준으로 까닭을 썼는가","부풀리지 않은 표제와 육하원칙에 맞는 전문을 썼는가"]},"explanation":["확인한 것만.","제목은 부풀리지 않게.","전문은 요약."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#25','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C21',4,'essay','teacher','우리 학교에서 독자인 학생들이 관심을 가질 만하고 직접 확인할 수 있는 기삿거리를 하나 정해, 기사문 계획(독자 · 기삿거리 · 필요한 자료 · 자료 수집 방법)을 세우고 부풀리지 않은 표제를 쓰세요. 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u5-C21","difficulty":4,"kind":"essay","stem":"우리 학교에서 독자인 학생들이 관심을 가질 만하고 직접 확인할 수 있는 기삿거리를 하나 정해, 기사문 계획(독자 · 기삿거리 · 필요한 자료 · 자료 수집 방법)을 세우고 부풀리지 않은 표제를 쓰세요. 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 독자 — 우리 학교 학생. 기삿거리 — 이번 달부터 바뀐 아침 등교 길 안전 도우미 활동. 필요한 자료 — 도우미가 서는 자리를 표시한 그림, 도우미 학생의 말. 수집 방법 — 아침에 직접 정문에 나가 보고, 도우미 학생에게 물어보고, 그림은 내가 그려 출처를 밝힌다. 표제 — 정문 앞 아침 길, 안전 도우미가 지킨다.","scoring_points":["독자가 관심 있고 확인할 수 있는 기삿거리를 골랐는가","계획의 네 가지를 모두 썼는가","출처를 생각하고 부풀리지 않은 표제를 썼는가"]},"explanation":["관심 있고 확인할 수 있게.","계획 네 가지.","부풀리지 않은 제목."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#1','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C1',1,'mc','auto','음성 언어의 예로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X01']::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"mc","stem":"음성 언어의 예로 알맞은 것은 어느 것인가요?","options":[{"t":"아침 조회 시간의 교장 선생님 말씀","correct":true},{"t":"교실 벽에 붙은 시간표","mis":"K6-2-u5-X01"},{"t":"알림장에 적은 준비물","mis":"K6-2-u5-X01"},{"t":"책에 인쇄된 이야기","mis":"K6-2-u5-X01"}],"explanation":["시간표 · 알림장 · 책은 글자로 되어 있어요.","조회 말씀은 음성으로 전해져요.","그래서 음성 언어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#2','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C3',1,'ox','auto','인쇄 매체는 이제 쓸모가 없는 매체예요.',ARRAY['K6-2-u5-X03']::text[],false,'{"seq":2,"concept":"K6-2-u5-C3","difficulty":1,"kind":"ox","stem":"인쇄 매체는 이제 쓸모가 없는 매체예요.","answer":"X","reason_options":[{"t":"매체마다 주로 쓰는 방법이 달라 알맞은 곳이 다르기 때문에","correct":true},{"t":"영상 매체가 모든 일을 더 잘하기 때문에","mis":"K6-2-u5-X03"}],"mis":"K6-2-u5-X03","explanation":["책과 신문은 오래 두고 다시 볼 수 있어요.","매체마다 알맞은 곳이 달라요.","쓸모없는 매체는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#3','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C4',1,'mc','auto','영상 매체가 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":3,"concept":"K6-2-u5-C4","difficulty":1,"kind":"mc","stem":"영상 매체가 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"음성 언어 · 문자 언어 · 그림 · 소리 · 움직임을 어울러 쓴다","correct":true},{"t":"문자 언어에 표와 사진만 더한다","mis":"K6-2-u5-X04"},{"t":"음성 언어에 음악만 더한다","mis":"K6-2-u5-X04"},{"t":"글자만 쓴다","mis":"K6-2-u5-X04"}],"explanation":["문자 언어에 표와 사진은 인쇄 매체예요.","음성 언어에 음악은 음성 매체예요.","영상은 여러 방법이 어우러져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#4','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C4',1,'ox','auto','글은 한 번 쓰고 나면 고칠 수 없어요.',ARRAY['K6-2-u5-X07']::text[],false,'{"seq":4,"concept":"K6-2-u5-C4","difficulty":1,"kind":"ox","stem":"글은 한 번 쓰고 나면 고칠 수 없어요.","answer":"X","reason_options":[{"t":"천천히 생각하며 쓴 뒤에 고칠 수 있기 때문에","correct":true},{"t":"글은 그대로 남기 때문에","mis":"K6-2-u5-X07"}],"mis":"K6-2-u5-X07","explanation":["글은 쓴 뒤에 다시 읽을 수 있어요.","그래서 고칠 수도 있어요.","고쳐 쓰기도 글의 특성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#5','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C12',1,'mc','auto','영상 감상의 세 걸음을 차례대로 쓴 것은 어느 것인가요?',ARRAY['K6-2-u5-X15']::text[],false,'{"seq":5,"concept":"K6-2-u5-C12","difficulty":1,"kind":"mc","stem":"영상 감상의 세 걸음을 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"찾기 → 잇기 → 말하기","correct":true},{"t":"말하기 → 찾기 → 잇기","mis":"K6-2-u5-X15"},{"t":"잇기 → 말하기 → 찾기","mis":"K6-2-u5-X15"},{"t":"보기 → 끄기 → 잊기","mis":"K6-2-u5-X15"}],"explanation":["먼저 무엇이 쓰였는지 찾아요.","그것이 무엇을 돕는지 이어요.","마지막에 느낌과 까닭을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#6','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C15',1,'mc','auto','독자를 고려한 글쓰기로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X20','K6-2-u5-X24']::text[],false,'{"seq":6,"concept":"K6-2-u5-C15","difficulty":1,"kind":"mc","stem":"독자를 고려한 글쓰기로 알맞은 것은 어느 것인가요?","options":[{"t":"전하려는 것은 그대로 두고 알아들을 수 있게 짠다","correct":true},{"t":"독자가 좋아할 것만 골라 쓴다","mis":"K6-2-u5-X20"},{"t":"어려운 이야기는 모두 뺀다","mis":"K6-2-u5-X20"},{"t":"어려운 낱말을 많이 써서 훌륭해 보이게 한다","mis":"K6-2-u5-X24"}],"explanation":["좋아할 것만 고르면 비위 맞추기예요.","어려운 낱말은 독자에게 닿지 않아요.","전하려는 것은 두고 닿게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#7','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C20',1,'mc','auto','기사문에 쓸 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u5-X27','K6-2-u5-X26']::text[],false,'{"seq":7,"concept":"K6-2-u5-C20","difficulty":1,"kind":"mc","stem":"기사문에 쓸 수 있는 것은 어느 것인가요?","options":[{"t":"직접 들은 사람의 말","correct":true},{"t":"확인하지 못한 소문","mis":"K6-2-u5-X27"},{"t":"그럴 것 같아서 지어낸 숫자","mis":"K6-2-u5-X27"},{"t":"「모두 기뻐했다」 같은 내 생각","mis":"K6-2-u5-X26"}],"explanation":["소문과 지어낸 수는 쓰지 않아요.","내 생각을 사실처럼 쓰지 않아요.","직접 들은 말은 옮겨 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#8','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C23',1,'mc','auto','힘든 일을 겪는 친구에게 힘을 내라는 마음을 전할 때 알맞은 말은 어느 것인가요?',ARRAY['K6-2-u5-X35','K6-2-u5-X36']::text[],false,'{"seq":8,"concept":"K6-2-u5-C23","difficulty":1,"kind":"mc","stem":"힘든 일을 겪는 친구에게 힘을 내라는 마음을 전할 때 알맞은 말은 어느 것인가요?","options":[{"t":"내가 곁에 있을게. 필요하면 언제든 말해 줘","correct":true},{"t":"그러게 내가 미리 조심하라고 했잖아","mis":"K6-2-u5-X35"},{"t":"힘내","mis":"K6-2-u5-X36"},{"t":"다음부터는 이렇게 해 봐","mis":"K6-2-u5-X35"}],"explanation":["섣부른 충고는 힘이 되지 않아요.","한 마디만으로는 막연해요.","곁에 있다는 말을 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#9','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C6',2,'mc','auto','선생님이 안내를 더 잘 전하려면 어떻게 하면 좋을까요?',ARRAY['K6-2-u5-X10','K6-2-u5-X03','K6-2-u5-X25']::text[],false,'{"seq":9,"concept":"K6-2-u5-C6","difficulty":2,"kind":"mc","stem":"선생님이 안내를 더 잘 전하려면 어떻게 하면 좋을까요?","options":[{"t":"말로 안내하고 알림장에도 모일 시각과 챙길 것을 적어 준다","correct":true},{"t":"같은 말을 더 큰 목소리로 한 번 더 한다","mis":"K6-2-u5-X10"},{"t":"글로만 알리고 질문은 받지 않는다","mis":"K6-2-u5-X03"},{"t":"안내를 짧게 줄여 시각만 말한다","mis":"K6-2-u5-X25"}],"explanation":["말로 하면 질문을 받을 수 있어요.","글로 적으면 다시 볼 수 있어요.","두 언어를 함께 쓰면 서로 보완해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#10','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C5',2,'mc','auto','선생님이 「좋은 질문이에요」라고 답한 장면에서 알 수 있는 음성 언어의 특성은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X06','K6-2-u5-X07']::text[],false,'{"seq":10,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"선생님이 「좋은 질문이에요」라고 답한 장면에서 알 수 있는 음성 언어의 특성은 어느 것인가요?","options":[{"t":"듣는 사람의 반응을 보며 다시 설명할 수 있다","correct":true},{"t":"적은 내용이 오래 남는다","mis":"K6-2-u5-X02"},{"t":"글자의 크기로 강조한다","mis":"K6-2-u5-X06"},{"t":"천천히 생각하며 고칠 수 있다","mis":"K6-2-u5-X07"}],"explanation":["은솔이의 물음을 듣고 답을 더해 주셨어요.","듣는 사람의 반응에 맞춰 설명을 보탰어요.","마주 보고 말하기 때문이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#11','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C12',2,'ox','auto','장면 이의 말과 자막이 차례를 기억하는 데 도움이 되었다는 것은 영상 안에서 함께 확인할 수 있어요.',ARRAY['K6-2-u5-X16']::text[],false,'{"seq":11,"concept":"K6-2-u5-C12","difficulty":2,"kind":"ox","stem":"장면 이의 말과 자막이 차례를 기억하는 데 도움이 되었다는 것은 영상 안에서 함께 확인할 수 있어요.","answer":"O","reason_options":[{"t":"그 장면에 무엇이 쓰였고 무엇을 돕는지는 영상에서 찾을 수 있기 때문에","correct":true},{"t":"무엇을 돕는지는 사람마다 달라 확인할 수 없기 때문에","mis":"K6-2-u5-X16"}],"mis":"K6-2-u5-X16","explanation":["장면 이에 말과 자막이 있어요.","자막에 차례가 적혀 있어요.","이것은 함께 확인할 수 있는 거예요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#12','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C8',2,'ox','auto','장면 사의 웃는 아이 장면은 어떤 일이 벌어지는지 한눈에 보여 주는 일을 해요.',ARRAY['K6-2-u5-X12']::text[],false,'{"seq":12,"concept":"K6-2-u5-C8","difficulty":2,"kind":"ox","stem":"장면 사의 웃는 아이 장면은 어떤 일이 벌어지는지 한눈에 보여 주는 일을 해요.","answer":"O","reason_options":[{"t":"장면과 움직임은 말로 길게 할 것을 한눈에 보여 주기 때문에","correct":true},{"t":"장면은 영상의 장식일 뿐 뜻을 나르지 않기 때문에","mis":"K6-2-u5-X12"}],"mis":"K6-2-u5-X12","explanation":["아이가 우유갑을 종이 칸에 넣어요.","말로 길게 하지 않아도 알 수 있어요.","장면도 뜻을 날라요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#13','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C21',2,'mc','auto','하은이 기사문의 [자료]를 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X23','K6-2-u5-X32','K6-2-u5-X13']::text[],false,'{"seq":13,"concept":"K6-2-u5-C21","difficulty":2,"kind":"mc","stem":"하은이 기사문의 [자료]를 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"사진을 누가 언제 찍었는지 출처를 밝힌다","correct":true},{"t":"사진을 세 장 더 넣는다","mis":"K6-2-u5-X23"},{"t":"사진은 그대로 두고 아무것도 적지 않는다","mis":"K6-2-u5-X32"},{"t":"사진 대신 화려한 그림을 넣는다","mis":"K6-2-u5-X13"}],"explanation":["자료는 개수가 중요하지 않아요.","어디에서 얻었는지 알아야 믿을 수 있어요.","출처를 밝혀요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#14','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C21',2,'mc','auto','하은이가 기삿거리를 고른 것에 대한 평가로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X30','K6-2-u5-X27']::text[],false,'{"seq":14,"concept":"K6-2-u5-C21","difficulty":2,"kind":"mc","stem":"하은이가 기삿거리를 고른 것에 대한 평가로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 학교 학생이 관심을 가질 만하고 직접 가서 확인할 수 있는 일이라 기삿거리는 알맞다","correct":true},{"t":"운동장 이야기는 아무도 관심이 없어 알맞지 않다","mis":"K6-2-u5-X30"},{"t":"먼 나라 이야기를 골랐어야 한다","mis":"K6-2-u5-X30"},{"t":"기삿거리가 좋으면 소문을 써도 된다","mis":"K6-2-u5-X27"}],"explanation":["독자는 우리 학교 학생이에요.","운동장은 가서 볼 수 있어요.","기삿거리는 좋지만 쓰는 방법을 고쳐야 해요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#15','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C23',2,'mc','auto','「근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.」가 이 편지에 알맞지 않은 까닭은 어느 것인가요?',ARRAY['K6-2-u5-X33','K6-2-u5-X22','K6-2-u5-X34']::text[],false,'{"seq":15,"concept":"K6-2-u5-C23","difficulty":2,"kind":"mc","stem":"「근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.」가 이 편지에 알맞지 않은 까닭은 어느 것인가요?","options":[{"t":"고마운 마음을 전하는 편지에 충고를 넣어 마음이 흐려졌다","correct":true},{"t":"김치 이야기는 편지에 쓰면 안 되는 낱말이라서","mis":"K6-2-u5-X33"},{"t":"문장이 짧아서","mis":"K6-2-u5-X22"},{"t":"할머니가 김치를 모르셔서","mis":"K6-2-u5-X34"}],"explanation":["편지의 목적은 고마움이에요.","충고는 이 마음과 맞지 않아요.","마음에 맞는 내용을 골라요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#16','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C25',2,'ox','auto','「짧다」는 [짭따]로 소리 나요.',ARRAY['K6-2-u5-X39']::text[],false,'{"seq":16,"concept":"K6-2-u5-C25","difficulty":2,"kind":"ox","stem":"「짧다」는 [짭따]로 소리 나요.","answer":"X","reason_options":[{"t":"짧다는 ㄹ이 소리 나서 [짤따]로 읽기 때문에","correct":true},{"t":"겹받침은 언제나 뒤의 것이 소리 나기 때문에","mis":"K6-2-u5-X39"}],"mis":"K6-2-u5-X39","explanation":["짧다는 ㄹ이 소리 나요.","그래서 [짤따]예요.","낱말마다 소리 나는 쪽을 소리 내어 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#17','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C9',3,'mc','auto','지안이에게 은솔이가 답해 주는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X25','K6-2-u5-X02','K6-2-u5-X07']::text[],false,'{"seq":17,"concept":"K6-2-u5-C9","difficulty":3,"kind":"mc","stem":"지안이에게 은솔이가 답해 주는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「여덟 시 사십 분까지 정문이야. 나도 헷갈릴까 봐 알림장에 적어 뒀어.」","correct":true},{"t":"「몰라. 그냥 일찍 와.」","mis":"K6-2-u5-X25"},{"t":"「말은 원래 다 잊어버리는 거야.」","mis":"K6-2-u5-X02"},{"t":"「글로 적는 건 쓸데없어.」","mis":"K6-2-u5-X07"}],"explanation":["정확한 시각을 알려 줘요.","글로 적어 두면 다시 볼 수 있어요.","두 언어의 특성을 함께 썼어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#18','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C9',3,'mc','auto','장면 삼을 「한 번 더 헹궈요」에 맞게 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X11','K6-2-u5-X14']::text[],false,'{"seq":18,"concept":"K6-2-u5-C9","difficulty":3,"kind":"mc","stem":"장면 삼을 「한 번 더 헹궈요」에 맞게 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"헹군 우유갑 하나를 오래 보여 주고, 자막은 「종이 칸에!」만 두고, 그 순간 음악을 낮춘다","correct":true},{"t":"물건을 더 많이 더 빨리 보여 준다","mis":"K6-2-u5-X13"},{"t":"자막을 모두 지우고 음악만 크게 한다","mis":"K6-2-u5-X11"},{"t":"장면 삼을 처음으로 옮기기만 한다","mis":"K6-2-u5-X14"}],"explanation":["하나를 오래 보여 줘요.","꼭 남길 말만 자막으로.","중요한 곳에서 소리를 바꿔요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#19','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C18',3,'mc','auto','하은이 기사문 전체를 고칠 때 가장 먼저 지켜야 할 것은 어느 것인가요?',ARRAY['K6-2-u5-X31','K6-2-u5-X23','K6-2-u5-X26']::text[],false,'{"seq":19,"concept":"K6-2-u5-C18","difficulty":3,"kind":"mc","stem":"하은이 기사문 전체를 고칠 때 가장 먼저 지켜야 할 것은 어느 것인가요?","options":[{"t":"확인한 사실만 남기고, 생각은 누구의 생각인지 밝히고, 소문은 뺀다","correct":true},{"t":"놀라운 말을 더 넣어 읽고 싶게 만든다","mis":"K6-2-u5-X31"},{"t":"사진을 여러 장 더 넣는다","mis":"K6-2-u5-X23"},{"t":"기자의 느낌을 더 자세히 쓴다","mis":"K6-2-u5-X26"}],"explanation":["기사문은 사실이라고 믿고 읽어요.","자료와 꾸밈은 그다음이에요.","확인한 것만 남겨요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#20','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C22',3,'error','auto','준서의 편지를 고칠 점을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X33','K6-2-u5-X34']::text[],false,'{"seq":20,"concept":"K6-2-u5-C22","difficulty":3,"kind":"error","stem":"준서의 편지를 고칠 점을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"윤서 — 「편지지를 더 예쁜 것으로 바꾸면 돼.」","correct":true,"mis_target":"K6-2-u5-X22"},{"t":"도겸 — 「맨 앞에 ‘할머니께’를 쓰고 끝에 날짜와 ‘손자 준서 올림’을 써.」","mis":"K6-2-u5-X33"},{"t":"나은 — 「‘안녕!’ 대신 ‘할머니, 건강하게 지내셨어요?’로 써.」","mis":"K6-2-u5-X34"}],"explanation":["도겸과 나은은 빠진 부분과 높임말을 짚었어요.","윤서는 겉모습을 고치려 했어요.","고쳐 쓰기는 받는 사람에게 닿게 하는 일이에요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#21','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C15',3,'mc','auto','「놀이터 그네 순서 지키기」를 알리는 글을 쓸 때 독자 고려를 바르게 한 것은 어느 것인가요?',ARRAY['K6-2-u5-X20','K6-2-u5-X24','K6-2-u5-X23']::text[],false,'{"seq":21,"concept":"K6-2-u5-C15","difficulty":3,"kind":"mc","stem":"「놀이터 그네 순서 지키기」를 알리는 글을 쓸 때 독자 고려를 바르게 한 것은 어느 것인가요?","options":[{"t":"순서를 지켜야 하는 까닭(부딪쳐 다칠 수 있음)은 그대로 두고, 줄 서는 자리를 그림으로 보여 준다","correct":true},{"t":"동생들이 싫어할 수 있으니 순서 이야기는 빼고 그네가 재미있다고만 쓴다","mis":"K6-2-u5-X20"},{"t":"「안전 수칙 준수」처럼 짧고 어려운 말로 쓴다","mis":"K6-2-u5-X24"},{"t":"그림만 넣고 글은 쓰지 않는다","mis":"K6-2-u5-X23"}],"explanation":["까닭을 빼면 전하려는 것이 사라져요.","어려운 말은 닿지 않아요.","그림은 글을 돕는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#22','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C10',3,'mc','auto','이 단원의 약속 「표현 효과는 무엇을 돕는가로 본다」를 바르게 쓴 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X15']::text[],false,'{"seq":22,"concept":"K6-2-u5-C10","difficulty":3,"kind":"mc","stem":"이 단원의 약속 「표현 효과는 무엇을 돕는가로 본다」를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"이 자막은 낯선 낱말을 정확히 남기도록 돕는다","correct":true},{"t":"이 영상은 자막이 열 개라서 효과가 크다","mis":"K6-2-u5-X13"},{"t":"이 음악은 크니까 좋다","mis":"K6-2-u5-X15"},{"t":"이 장면은 그냥 멋있다","mis":"K6-2-u5-X15"}],"explanation":["개수로 재지 않아요.","크기나 멋은 까닭이 아니에요.","무엇을 돕는지로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#23','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C22',4,'mc','auto','준서의 편지를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X36']::text[],false,'{"seq":23,"concept":"K6-2-u5-C22","difficulty":4,"kind":"mc","stem":"준서의 편지를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"받는 사람과 날짜 · 보내는 사람을 넣고, 높임말로 바꾸고, 「그거」를 콕 집어 밝히고, 김치 충고는 빼서 고마운 마음만 담는다","correct":true},{"t":"글씨를 더 크게 쓰고 편지지를 바꾼다","mis":"K6-2-u5-X22"},{"t":"「진짜」를 더 많이 넣어 고마움을 키운다","mis":"K6-2-u5-X36"},{"t":"모두 지우고 「고마워요」 한 줄만 쓴다","mis":"K6-2-u5-X36"}],"explanation":["빠진 부분을 채워요.","받는 사람에게 맞는 말로 바꿔요.","마음에 맞는 내용만 남겨요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#24','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C23',4,'essay','teacher','준서의 편지를 받는 사람과 전하려는 마음을 생각하며 다섯 부분을 갖추어 고쳐 쓰세요. 고마운 일은 그럴 법한 일을 하나 정해 콕 집어 쓰고, 날짜는 ○○월 ○○일로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u5-C23","difficulty":4,"kind":"essay","stem":"준서의 편지를 받는 사람과 전하려는 마음을 생각하며 다섯 부분을 갖추어 고쳐 쓰세요. 고마운 일은 그럴 법한 일을 하나 정해 콕 집어 쓰고, 날짜는 ○○월 ○○일로 쓰세요.","answer_guide":{"answer":"예: 할머니께 / 할머니, 그동안 건강하게 잘 지내셨어요? / 여름 방학 때 제가 자전거를 못 타서 속상해할 때 할머니께서 뒤에서 끝까지 잡아 주셔서 혼자 탈 수 있게 되었어요. 그때 「넘어져도 괜찮다」고 해 주신 말씀이 정말 고마웠어요. 겨울 방학에 또 찾아뵐게요. / 늘 건강하세요. / ○○월 ○○일 손자 준서 올림","scoring_points":["다섯 부분을 모두 갖추었는가","할머니께 알맞은 높임말을 썼는가","고마운 일을 콕 집고 충고를 빼 마음에 맞게 썼는가"]},"explanation":["빠진 부분을 채워요.","높임말로.","그 일을 콕 집어요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#25','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C25',4,'essay','teacher','「붉다」, 「얇아요」, 「늙다」, 「짧아요」를 소리 나는 대로 쓰고, 왜 그렇게 소리 나는지 겹받침의 규칙으로 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u5-C25","difficulty":4,"kind":"essay","stem":"「붉다」, 「얇아요」, 「늙다」, 「짧아요」를 소리 나는 대로 쓰고, 왜 그렇게 소리 나는지 겹받침의 규칙으로 설명하세요.","answer_guide":{"answer":"예: 붉다 [북따], 얇아요 [얄바요], 늙다 [늑따], 짧아요 [짤바요]. 우리말은 받침에서 한 번에 한 소리만 낼 수 있어서, 붉다 · 늙다처럼 뒤에 자음자가 오면 겹받침 가운데 하나만 소리 난다. 얇아요 · 짧아요처럼 뒤에 모음이 오면 두 소리가 다 나고 뒤엣것인 ㅂ이 뒷글자로 넘어가 소리 난다.","scoring_points":["네 낱말을 바르게 썼는가","자음자 앞에서 하나만 나는 규칙을 썼는가","모음 앞에서 뒤엣것이 넘어가는 규칙을 썼는가"]},"explanation":["뒤에 무엇이 오나 봐요.","자음자 앞 하나.","모음 앞 둘, 뒤엣것이 넘어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
